INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023477', 'AN2040', '岡栄太郎', '岡栄太郎は、清水みなとの同じ中学校の後輩である。彼はみなとの過去を知る人物だ。みなとを慕う気持ちから、栄太郎は山並高校に入学した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210791-4hJbIHAsgPcu.png', '8月21日', NULL, '西山宏太朗', 170, 210791, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
