INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023481', 'AN2040', '江尻武一', '江尻武一は山並高校の生徒だ。彼は騒がしく、短気で、すぐに喧嘩を吹っかける。中学時代は野球部に所属していた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216693-mwNNTvRObb7o.png', '12月5日', NULL, '古川慎', 178, 216693, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
