INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023483', 'AN2040', '網浜秀吾', 'シュゴは山並高校の生徒だ。中学時代は水泳部だった。才能があり、クールな性格だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216692-EtiSi6dn9aoN.png', NULL, NULL, '斉藤壮馬', NULL, 216692, 'SUPPORTING', 60) ON CONFLICT DO NOTHING;
