INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023485', 'AN2040', '牛窓善晴', '牛窓善晴は山並高校の生徒だ。内向的な性格のため、自分の気持ちをうまく表現することが苦手だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216695-o5pfxIdyaAEW.png', '1月20日', NULL, '廣瀬大介', 168, 216695, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
