INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023487', 'AN2040', '猪俣ババヤロ豊', '猪俣ババヤロ豊は、山並高校の生徒です。父親はナイジェリア人です。彼は穏やかな性格です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216694-UdoiyyWkH7NR.png', '5月18日', NULL, '畠中祐', 188, 216694, 'SUPPORTING', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023488', 'AN2040', '清水明日海', 'アズミはミナトの妹だ。二人は多くの兄弟姉妹と同じように喧嘩や口論を繰り返しているが、アズミは、家族の人生を永遠に変えてしまったあの夜の記憶に苛まれている。その記憶は、ミナトにはないものだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b243478-sSXdja25w2SL.jpg', NULL, NULL, '遠藤璃菜', NULL, 243478, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023489', 'AN2041', '園崎魅音', 'ミオンは前原圭一のクラスで最年長の生徒だ。年長者として学級委員長を務めており、リーダーとして皆から尊敬されている。変態的なおてんば娘のような振る舞いをし、自らを「おじさん」と呼んでいるが、その裏には少女らしい一面も隠している。 美音は、雛沢で絶大な影響力を持つ「三大家」の一つ、園崎家の次期当主である。部活の仲間とゲームをする際、彼女は冷酷なことで知られており、しばしば最も恥ずかしい罰ゲームを考案する。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1611-z9SVkC9loi4y.png', '7月10日', NULL, 'ゆきのさつき', NULL, 1611, 'MAIN', 1547) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023490', 'AN2041', '竜宮レナ', 'Rena is a girl who returned from Ibaraki to Hinamizawa one year ago and now is in the same grade level as Keiichi. She is very kind and capable and takes care of Keiichi and her friends whenever possible, but is also naive and is usually subject to light teasing by Keiichi. She is distinguished by her obsession with things she perceives as adorable, calling them kāii (かぁいい), a slurred form of kawaii (かわいい) meaning "cute." Those tend to be moekko characters or items she finds while scouring the l', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1427-28AR4oy0y2Hw.png', '7月28日', NULL, '中原麻衣', 158, 1427, 'MAIN', 2945) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023491', 'AN2041', '園崎詩音', 'シオンはミオンの一卵性双生児の妹で、現在はオキノミヤに住んでいる。性格は異なるものの、彼女とミオンはよく入れ替わってしまうため、二人を区別するのが難しいこともある。       彼女は園崎家によって私立の全寮制学校へ送られたが、そこから脱走して故郷の近くに戻り、現在は葛西と一緒に暮らしている。それでも、彼女と美音は親密な関係を保っている。ほとんどのストーリー展開において、彼女は他の主要キャラクターとは別の学校に通っている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1313-wLhW5uDxdhqA.png', '7月10日', NULL, 'ゆきのさつき', NULL, 1313, 'MAIN', 1655) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023492', 'AN2041', '北条沙都子', '里子は、圭一の学校の年下の同級生だ。彼女は独特な話し方をしており、すべての文の最後に「わ」をつけてしまうが、それが文法的に間違っていることもある。幼いながらも罠を仕掛けるのが非常に上手で、圭一を相手に練習するのが好きだ。  非常に元気で遊び好きな性格だが、実はかなり泣き虫なところがあり、美音や圭一によくからかわれる。また、同居している理香とはとても仲が良い。彼女は日本語が苦手だ。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1612-lL5sulSea1fZ.png', '6月24日', NULL, 'かないみか', NULL, 1612, 'MAIN', 1190) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023493', 'AN2041', '前原圭一', '圭一は、有名で極めて裕福な芸術家の息子であり、故郷で一連の不運な出来事に遭遇した後、最近ひなみざわに引っ越してきた。そのカリスマ的で活気あふれる性格と巧みな話術のおかげで、彼はすぐに町に溶け込み、新しい友達を作り、いくつかの部活動でも活躍している。 とはいえ、彼は少し内気な面もあり、時には簡単に動揺してしまうこともある。武器が必要な時は、サトシの古いバットを振るう。ケイイチは部活動の中でよく冗談の的になるが、そこから彼は', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1851-stMK6YF2jvhS.png', '4月13日', NULL, '保志総一朗', NULL, 1851, 'MAIN', 1102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023494', 'AN2041', '間宮リナ', 'リナは、物語『罪滅ぼし編』において、レナの人生に現れる女性である。彼女は北条鉄平の恋人であり、二人は共謀して、脅迫や恐喝によって男性たちから金をだまし取っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b10741-w0rRitrCubVK.png', '7月31日', NULL, '渡辺美佐', NULL, 10741, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023495', 'AN2041', '前原伊知郎', '前原伊知郎は『ひぐらしのなく頃に』シリーズの登場人物であり、前原藍子の夫、前原圭一の父親、そして前原家の屋敷を建てた人物である。彼は芸術家として活動しており、若い少女を非常に好んでいるようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236531-BK2oPfzxtOjH.png', NULL, NULL, '松本保典', NULL, 236531, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023496', 'AN2041', '大石蔵人', '大石黒道は、沖ノ宮のベテラン刑事であり、個人的な事情から、定年退職までに雛沢殺人事件の謎を解明すると誓っている。その荒っぽい捜査手法や、事件解決のために手段を選ばない姿勢から、村人からは厄介者扱いされている。', 59, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3775-CQOkJnyiCThk.png', '11月15日', NULL, '茶風林 ', NULL, 3775, 'SUPPORTING', 228) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023497', 'AN2041', '葛西辰由', 'タツヨシは、秘密工作員のような風貌をした園崎家の使用人である。かつてはより活発に活動していたが、現在はシオンの世話役として落ち着いている。彼はなぜかテッペイとリナの両方を知っており、彼らの生活様式やしつこい手口も把握している。   『祭林編』では、入江クリニックへの襲撃の際、並外れた強さと戦闘経験を見せつけ、山犬のメンバーを次々と制圧している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b14928-DIdiJ3r5dsHH.jpg', '12月23日', NULL, '立木文彦', NULL, 14928, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023498', 'AN2041', '富田大樹', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252948-BpWbTXvdZ0h3.png', NULL, NULL, '松元惠', NULL, 252948, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023499', 'AN2041', '富竹ジロウ', 'ひなみざわの村に頻繁に訪れる写真家（特に「わたんがし祭り」の時期）。     彼の性格については、これ以外にあまり知られていない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b10024-Bu0fiJR4Iz9x.jpg', '9月14日', NULL, '大川透', NULL, 10024, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023500', 'AN2041', '公由喜一郎', '「三大家」の一家の当主であり、雛見沢の公式な村長でもある。温厚な老人のように見えるが、雛見沢の敵に対しては激しい憎悪を抱いている。村長という地位は、雛見沢の大部分の実権を園崎お魎が握っているため、主に名目上のものに過ぎない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b14929-Pz9C3YPFo8s5.jpg', NULL, NULL, '山野史人', NULL, 14929, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023501', 'AN2041', 'エウア', '羽生に似た角を生やした女性。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212187-d2JYFn1H2VzW.png', NULL, NULL, '日高のり子', NULL, 212187, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023502', 'AN2041', '鷹野三四', 'ミヨは村の診療所で看護師として働いている。彼女は雛沢の過去や文化に強い関心を持ち、自分の推測をすべてノートに書き留めている。時折、彼女の話は極めて謎めいていて背筋が凍るようなものになることもある――彼女は人々を不安にさせることを楽しんでいるようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b4934-hyXYSNh1Yqtu.jpg', '6月20日', NULL, '伊藤美紀 ', NULL, 4934, 'SUPPORTING', 416) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023503', 'AN2041', '北条鉄平', 'テッペイは、サトコとサトシの叔父であり、養父でもある。両親が亡くなった後、彼と妻はサトコとサトシの世話をせざるを得なくなったが、二人を虐待していた。現在はオキノミヤに住んでいる。 笠井によると、彼は売春斡旋業者であり、愛人のリナを利用して男性たちから金をだまし取っているという。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b9464-o4p2oDIloadU.jpg', '5月28日', NULL, '宝亀克寿', NULL, 9464, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023504', 'AN2041', '竜宮保典', 'レナの父', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245031-nKiVeukeGOc8.png', NULL, NULL, '家中宏', NULL, 245031, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023505', 'AN2041', '入江京介', '恭介は村の診療所の院長だ。若く、しかも重度のメイドフェチであるにもかかわらず、地域社会からは非常に尊敬されている。彼は快活に往診を行い、皆の健康を心から気遣っているようだ。 彼は（半分冗談で）サトコがもっと年をとったら結婚したいと認めているが、リカがレストラン「エンジェル・モート」の制服を着ているときは、彼女にアプローチすることも厭わない。さらに、彼は村のリトルリーグの監督も務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b7445-X8OacDAXCwqK.png', '12月3日', NULL, '関俊彦', NULL, 7445, 'SUPPORTING', 68) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023506', 'AN2041', '園崎茜', 'オリョーの娘であり、ソノザキ姉妹の母である彼女は、部外者と結婚したために相続権を剥奪されたにもかかわらず、ソノザキ家を率いている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b11935-k3UjMcUlaJO8.png', '11月6日', NULL, '井上喜久子', NULL, 11935, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023507', 'AN2041', '知恵留美子', 'ルミコはケイイチのクラスの女性教師で、『月姫』のシエル先輩をパロディ化したキャラクターです（使用許可はType-Monから得ています）。 アニメシリーズにおける彼女役の声優は、『月姫』アニメ版のシエルと同じ声優が担当している。 このパロディに合わせ、彼女の大好物はシエルと同じくカレーライスであり、カレーの名誉を守るためなら、とてつもない、そして少々恐ろしいほどの手段も厭わない。これは『ひぐらしのなく頃に レイ』のOVAで、彼女が激怒する場面でも描かれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b6696-hxF6CrBnVSYE.png', '5月3日', NULL, '折笠富美子', NULL, 6696, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023508', 'AN2041', '古手羽入', '羽生は『祭林編』に登場する謎めいた「転校生」である。彼女の頭には濃い色の角が2本生えており、そのうちの1本はわずかに欠けている（ただし、彼女を「怪物」と呼ぶ高野を除き、誰もそれに気づいたり言及したりしていないようだ）。   実のところ、彼女はリカの生涯を通じてリカの前に姿を現していたが、『祭林編』と『見つくる編』になって初めて、他者と交流する力を得た。そこで彼女はリカの遠縁を装い、「古手羽入」という名前を与えられた。多くのc', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3128-ms0vxrk4ZoGN.png', '8月1日', NULL, '堀江由衣', NULL, 3128, 'SUPPORTING', 545) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023509', 'AN2041', '前原藍子', '前原愛子は、前原圭一の母親である。彼女は『鬼隠し編』で、夫の前原一郎と共に初登場する。アニメの最初の2シーズンでは、彼女の登場シーンや詳細な描写はほとんどないが、漫画版では何度か登場する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236530-FGPLOUx3ZMLd.png', NULL, NULL, '松井菜桜子', NULL, 236530, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023510', 'AN2041', '竜宮礼子', 'レナの母親。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252940-3IlgsYeE4PMv.png', NULL, NULL, '櫻井浩美', NULL, 252940, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023511', 'AN2042', '渡辺摩利', 'マリは第一高校の道徳委員会の委員長です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88200-4TtqKvqX36N8.png', NULL, NULL, '井上麻里奈', NULL, 88200, 'SUPPORTING', 91) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023512', 'AN2042', '中条あずさ', '2年生の生徒。第一高校の生徒会書記。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72563-E0zvek4ZgDGC.png', NULL, NULL, '小笠原早紀', NULL, 72563, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023513', 'AN2042', '市原鈴音', '鈴音は高校3年生です。彼女は第一高校の生徒会会計を務めています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88183-3fkbbuQDq3Cf.png', NULL, NULL, '中原麻衣', NULL, 88183, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023514', 'AN2042', '一色愛梨', '彼女は第三高校の生徒であり、魔法の主要コースの生徒でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232668-39WQ0mv46xKh.png', NULL, NULL, 'Lynn', NULL, 232668, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023515', 'AN2042', '明智英美', '第一高校の1年生で、柴兄妹と同じ学年。九校対抗戦の新人部門において、アイス・ピラー・ブレイクとスピード・シューティングの種目で、同校の代表選手の一人となっている。本名はアメリア・明智英美・ゴールディで、よく「エイミ」と呼ばれる。  （出典：魔高校の烈星ウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188681-BstdIek9QqUL.jpg', NULL, NULL, '西明日香', NULL, 188681, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023516', 'AN2042', '十七夜栞', '彼女は第三高校の生徒で、1年Cコースの生徒です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232667-45lff6mNN8Wv.png', NULL, NULL, '種﨑敦美', NULL, 232667, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023517', 'AN2042', '四十九院沓子', '彼女は第三高校の生徒で、1年C組に在籍している。彼女は、神道系の古代魔法を継承するツクシイ家の後継者である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232669-MmGAwqqDvAne.png', NULL, NULL, '木戸衣吹', NULL, 232669, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023518', 'AN2042', '水尾佐保', '彼女は第三高校の生徒で、3年1組に在籍しています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232670-ID1ytko1KGsE.png', NULL, NULL, '石飛恵里花', NULL, 232670, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023519', 'AN2043', 'カサネ・ランドール', '制圧部隊所属：第567期　ID：RRK567301　能力：念力　武器：投げナイフ　冷徹で現実的、他人に対して無関心な態度をとるが、比類なき戦闘感覚を持つ少女。 幼い頃に「他者」に襲われたことをきっかけに、他者抑圧部隊に入隊した。訓練をクラス首席で修了した。幼い頃、「他者」の襲撃で両親を亡くした。その後、ランドール家に養子として引き取られた。養父母は彼女を決して……のように扱ったことはなかった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213799-RPqLAJDeDzFc.png', '6月10日', NULL, '瀬戸麻沙美', 161, 213799, 'MAIN', 127) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023520', 'AN2043', 'ユイト・スメラギ', '抑圧部隊所属：第567部隊　クラスID：WSY567369　能力：念動力　武器：刀　明るく楽観的で、意志が強く、心優しい少年。ニューヒムカの建国の父を祖に持つスメラギ家の次男である。 彼の家系は代々政治家の家系であり、父のジョウ・スメラギは現政権の首班、兄のカイトは「他者」抑圧部隊の隊長を務めている。幼少期に「他者」に襲われ、危うく命を落とすところだったが、ある人物に救われた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213800-LflAa3fnmyO3.png', '1月1日', NULL, '榎木淳弥', 173, 213800, 'MAIN', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023521', 'AN2043', 'キョウカ・エデン', '制圧部隊：第538部隊　クラスID：KEK538232　能力：複製　武器：クロスボウ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225075-UKJyduthrRPL.png', '11月30日', NULL, '原由実', 168, 225075, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023522', 'AN2043', 'ジョウ・スメラギ', '現在のスメラギ家の当主は、ニューヒムカの創設者であり、ニューヒムカ評議会議長でもあった人物の末裔である。彼は国家元首である。また、ユイトの父であり、「異形鎮圧部隊」の隊長であるカイト・スメラギでもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244219-Y40mIqmcPf4D.png', NULL, NULL, '勉磯部', NULL, 244219, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
