INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023524', 'AN2043', 'ワタル・フレイザー', 'ワタルはOSFのプラトン・オペレーターであり、半径約500キロメートル圏内であれば、テレパシーでチームと通信することができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244221-Mrzg8gcdcYLz.png', NULL, NULL, '高梨謙吾', NULL, 244221, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
