INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023537', 'AN2043', 'カイト・スメラギ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243747-gzt1rozfvfVd.png', NULL, NULL, '小林親弘', NULL, 243747, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023538', 'AN2044', '渡辺さらさ', '彼女はコカ・スクールの女優志望生であり、センテニアル・クラスの他の生徒たちはもちろん、学校全体の中でもひときわ際立っている。それは、彼女の明るい性格や、学校で一番背が高いという理由だけではない。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215082-TR09CcCMN82H.png', '11月10日', NULL, '千本木彩花', NULL, 215082, 'MAIN', 298) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023539', 'AN2044', '奈良田愛', '男性に対する不信感から所属していたグループを脱退した元アイドルは、過去、とりわけ男性から逃れるために、コーカ学園に入学した。彼女は、クラスメートであり寮の同室者でもあるサラサを、最初はうっとうしいと感じていた。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218335-yROmkATZyb1g.png', NULL, NULL, '花守ゆみり', NULL, 218335, 'MAIN', 187) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023540', 'AN2044', '杉本紗和', 'コカの大ファンである彼女は、プリマ・バレリーナになるチャンスを諦めて、コカ・スクールに入学した。彼女はセンテニアルクラスの学級委員を務めている。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218334-NNzu9KbNDYd5.jpg', NULL, NULL, '上坂すみれ', NULL, 218334, 'MAIN', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023541', 'AN2044', '星野薫', '彼女は二代目高賀女優の娘で、サラサやアイと同じクラスに在籍している。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218333-nCFZouhVTqM0.jpg', NULL, NULL, '大地葉', NULL, 218333, 'MAIN', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023542', 'AN2044', '沢田千夏', '彼女は「澤田双子」の一人である。高賀の公演で見たウサギの衣装をまとった双子に感化され、双子の姉と共に高賀学園のオーディションを受けたが、姉が合格できなかったため入学を延期した。これが二人の関係における決定的な分岐点となった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218337-bEwR13fCHVA2.png', NULL, NULL, '松田利冴', NULL, 218337, 'MAIN', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023543', 'AN2044', '沢田千秋', '彼女は「澤田双子」のうち、より元気な方です。 高歌の公演で見た「ウサギの女性双子」に感化され、彼女は双子の姉と共に高歌学園のオーディションを受けたが、最初のオーディションで合格できなかったため、姉は入学を延期せざるを得なくなり、それが二人の関係における火種となってしまった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218339-hPj2VjAiItbd.png', NULL, NULL, '松田颯水', NULL, 218339, 'MAIN', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023544', 'AN2044', '山田彩子', '内気で恥ずかしがり屋で、体重に関する悩みにも悩まされていた彼女は、そのプレッシャーのせいで学校を辞めようかとさえ思ったほどだった。しかし、その実力が過小評価されているにもかかわらず、彼女はセンテニアル・クラスで最も才能のあるパフォーマーの一人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218338-mkOxqUy02u9y.jpg', NULL, NULL, '佐々木李子', NULL, 218338, 'MAIN', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023545', 'AN2044', '安道守', '彼は『オペラ座の怪人』での演技から、コカ・スクールの卒業生や演劇ファンからは「ファントム」として知られている。公演中の事故をきっかけに現在は俳優業を引退し、コカ・スクールの講師を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231197-nKUaHClFyzHe.png', NULL, NULL, '諏訪部順一', NULL, 231197, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023546', 'AN2044', '小園桃', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b367849-PikcufS7RFP5.png', NULL, NULL, '逢田梨香子', NULL, 367849, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023547', 'AN2044', '奈良田太一', 'アイの叔父であり、彼女が唯一信頼する男性。彼はコカ・スクールの講師を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231196-8gGvQqLPdLM9.png', NULL, NULL, '野島健児', NULL, 231196, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023548', 'AN2044', '野島聖', '2年生の1人で、アイの学生アドバイザーを務めている。時々サラサを少しいじめることもあるが、彼女なりのやり方で、アイの指導に熱心に取り組んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231198-Q3lIEeo4qD8Y.png', NULL, NULL, '花澤香菜', NULL, 231198, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023549', 'AN2044', '中山リサ', 'サラサの学生アドバイザーを務める2年生。ヒジリがサラサに対して少し意地悪な態度をとるたびに、彼女はサラサを擁護してくれる。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231199-emlhUV75UK68.png', NULL, NULL, '小松未可子', NULL, 231199, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023550', 'AN2044', '里美星', '「高香ウィンタートロープ」のトップスターで、アイやサラサと親しい間柄。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218336-NoTf8IDyoeja.jpg', NULL, NULL, '七海ひろき', NULL, 218336, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
