INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023564', 'AN2045', '柊摩央', 'ライバルアイドルグループ「サニー・パス」のメンバーの一人。彼女はサニー・パスの「セクシー・ナイト」と称されている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244080-e2IB39y45uGa.png', NULL, NULL, '結木ゆな', NULL, 244080, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
