INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023566', 'AN2045', '聖澤悠奈', 'ライバル学嬢アイドルグループ「サニー・パス」のメンバーの一人。グループの「太陽」と呼ばれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244082-VY8QY6b9M03F.png', NULL, NULL, '吉武千颯', NULL, 244082, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023567', 'AN2045', '葉月花', 'レンの母親であり、由井ヶ丘女子高校の創設者。かつては神宮音楽学校でスクールアイドルとして活動していた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254042-POKgJTWwklGY.png', NULL, NULL, '遠藤綾', NULL, 254042, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023568', 'AN2046', '由比鶴乃', '無鉄砲で元気いっぱいの魔法少女。鶴野は家族、とりわけ、かつて由井家を繁栄へと導いた祖父と曽祖父を深く愛している。彼女は、由井家の名声を回復させるため、最強の魔法少女になるべく戦っている。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151332-2qOSzoKJdwcj.png', '3月31日', NULL, '夏川椎菜', NULL, 151332, 'MAIN', 126) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023569', 'AN2046', '二葉さな', '悲観的な魔法少女のサナは、家族や周囲の人々から拒絶されてきたため、自信がほとんどない。しかし、彼女を必要とする人々のそばには静かに寄り添い、その時が来ればいつでも助けようとしている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151330-m4shBzpgZU6W.png', '3月14日', NULL, '小倉唯', NULL, 151330, 'MAIN', 123) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023570', 'AN2046', '環いろは', 'イロハは、自分が見ている奇妙な夢の真相を突き止めるために上浜を訪れた。心優しい性格で、他人のことを気にかけすぎてしまう傾向がある。流行には疎く、スマホの操作もあまり得意ではない。普段は控えめだが、肝心な時には闘志を燃やすこともある。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151326-8QHFe36L9IOI.png', '8月22日', NULL, '麻倉もも', NULL, 151326, 'MAIN', 272) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023571', 'AN2046', '深月フェリシア', 'フェリシアは、元気いっぱいで意志の強い活発な魔法少女であり、両親の命を奪った魔女たちを憎んでいる。現在は傭兵として、上浜の至る所で魔女を狩っている。その強気な物腰の裏には、優しい心と動物への愛情が隠されている。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151331-CKO6cTPXfcyg.png', '9月19日', NULL, '佐倉綾音', NULL, 151331, 'MAIN', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023572', 'AN2046', '七海やちよ', '上浜で7年間、魔女と戦ってきたベテランの魔法少女。八千代は、この街のことや魔法少女全般について詳しい。彼女は他の魔法少女たちとは距離を置きつつ、上浜市の「噂」に関する資料をまとめています。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151327-HxWD725TKSxQ.png', '1月9日', NULL, '雨宮天', NULL, 151327, 'MAIN', 283) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023573', 'AN2046', '佐倉杏子', '武器：槍　京子は、物語の後半で街にやってくるベテランの魔法少女だ。面白いことに、彼女は戦っている最中であっても、いつも何かを食べている姿が見られる。    貧しい家庭で育ったため、彼女はしばしば食料を盗まざるを得ず、食料を無駄にする人間を嫌っている。この考え方は「グリーフシード」に対しても同様で、彼女は完全に成長した魔女だけを標的にしている。 京子は他のメンバーよりもずっと長く魔法少女として活動しており、その経験から技量も優れている。彼女は、伸びたり、複数の槍に分かれたりする槍を操る。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40006-zOwYYimuiO3m.png', NULL, NULL, '野中藍', NULL, 40006, 'SUPPORTING', 2724) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023574', 'AN2046', '早乙女和子', '和子はまどかの担任教師だ。男性との関係が長続きしないため、その点に関しては非常に不満を抱いている。 授業中も、男性について愚痴をこぼすことがよくあります。また、まどかの母親であるかなめじゅんことも親しい関係にあるようです。    （出典：公式制作ノート＆魔法少女ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b39785-LR0WC4uHFSl4.jpg', NULL, NULL, '岩男潤子', NULL, 39785, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023575', 'AN2046', '十咎ももこ', 'いつも新人を探している魔法少女。真ん中の子であるモモコは、2人の兄のボーイッシュな影響を受けているが、ぬいぐるみのような可愛くて女の子らしいものが大好きだ。可愛いものが大好きなので、女性アイドルのファンでもある。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151334-ick9EKoi1jYN.png', '7月17日', NULL, '小松未可子', NULL, 151334, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023576', 'AN2046', '美樹さやか', '武器：カットラス　まどかの同級生。まどかがキュゥべぇを救出するのを手伝ったことをきっかけに、自身も魔法少女になるよう誘われることになる。友人たちを深く思いやり、片思いしている上条京介という病気の少年を助けたいと願っている。 魔法少女になる前、さやかは魔女狩りの際に身を守るため、麻美が魔法で強化した野球のバットを武器として使っていた。    さやかは青を基調としたデザインで、それが彼女を英雄的で「正義感あふれる」存在に見せている。さらに、彼女が身につけている', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b38395-d24OayatTB5h.jpg', NULL, NULL, '喜多村英梨', NULL, 38395, 'SUPPORTING', 2667) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023577', 'AN2046', '宮尾時雨', NULL, 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249731-8HiQVDjwsdPX.png', NULL, NULL, '鬼頭明里', NULL, 249731, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023578', 'AN2046', '秋野かえで', '心配性なカエデは、すぐに怖がってしまう。その一方で、親切で思いやりがあり、友達のためならリスクを厭わない。動物や植物、昆虫、そして自然全般が大好きだ。ガーデニングを楽しむほか、あまり得意ではないけれど、クレーンゲームも好きだ。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151329-JLmYxNT0H6SU.png', NULL, NULL, '大橋彩香', NULL, 151329, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023579', 'AN2046', 'キュゥべぇ', '彼は、ある少女が「魔法少女」となり、魔女と戦うことを条件に、その少女のどんな願いでも叶えてあげられる使い魔だ。    重大なネタバレ：', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b38566-XzE2iqAodRQK.jpg', NULL, NULL, '加藤英美里', NULL, 38566, 'SUPPORTING', 809) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023580', 'AN2046', '水波レナ', '人に対して心を開くのが苦手な魔法少女。レナは自信のなさを補うために強がった態度をとるため、彼女をよく知らない人からは誤解されがちだ。食にうるさく、甘いものが大好き。また、大のアイドルファンでもある。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151333-zLGgpKD6bg6g.png', NULL, NULL, '石原夏織', NULL, 151333, 'SUPPORTING', 74) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023581', 'AN2046', '八雲みたま', '上浜の片隅でコーディネーターとして活動する魔法少女。自ら戦うことができないため、アイテムの提供や魔法の調整と引き換えに「グリーフシード」を受け取っている。普段は陽気な性格で親しみやすい笑顔を見せているが、彼女の正体を知る魔法少女はほとんどいない。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158077-C1nRoq2AXp65.png', NULL, NULL, '堀江由衣', NULL, 158077, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023582', 'AN2046', 'アリナ・グレイ', '「誰も魔女になる必要のない世界」を築こうとしている魔法少女、アリナは、生と死に執着する芸術の天才であり、作品制作に没頭し、魔女たち自身を題材にした傑作を生み出すことを夢見ている。創作のスランプに陥った際には、自分自身を作品のモデルにすることもある。  彼女はよく人をからかい、かなり傲慢なところがある。戦っている最中でさえ笑っている。また、物事が思い通りにいかないときはすぐに怒り出す。彼女の行動は予測不能で衝動的だ。彼女は非常に――', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162222-aSbZX8yZVRin.png', NULL, NULL, '竹達彩奈', NULL, 162222, 'SUPPORTING', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023583', 'AN2046', '黒江', '黒江は宝崎市に住む魔法少女だ。黒江は時折、伊呂波と一緒に戦うこともあるが、基本的には定期的に集まって情報を交換する程度の知り合い同士である。黒江は生死をかけた戦いを恐れており、魔法少女であることから解放されたいと願っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151328-u4LnWfsvYkID.jpg', NULL, NULL, '花澤香菜', NULL, 151328, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023584', 'AN2046', '梓みふゆ', '7年前、美冬は八千代とペアを組んで戦っていた。    美冬は、年下の魔法少女たちから「お姉さん的存在」と見なされている。これは彼女がベテランであることに由来する。家事に苦手意識があり、よく友人たちに世話を焼いてもらっている。優しくて穏やかだが、精神的に弱いため、時折判断を誤ってしまうこともある。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164865-7XlbIsoFEZmD.png', NULL, NULL, '中原麻衣', NULL, 164865, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023585', 'AN2046', '安名メル', '毎日の占い結果を頼りに生きている魔法少女。運勢が「吉」なら、彼女はとても楽観的になる。もし「凶」なら、魔女狩りに行くことさえしない。占いが大好きだが、予言がいつも的中してしまうため、他の魔法少女たちから占うことを禁じられている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164973-Dk1jsHXufjcn.png', NULL, NULL, '高尾奏音', NULL, 164973, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023586', 'AN2046', '環うい', 'みんなを幸せにするために自分に何ができるのか、悩みながら奮闘している魔法少女。外の世界のことをほとんど知らずに育ったため、周囲に遅れをとらないよう必死に努力している。人の良いところを見つけるのが得意で、誰に対しても嫌悪感を抱くことはない。トカとネムは彼女の親友で、イロハは彼女の姉である。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164942-5ehVw7qtuqKO.png', NULL, NULL, '石見舞菜香', NULL, 164942, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023587', 'AN2046', '暁美ほむら', 'ホムラは、まどかの見た終末的な悪夢の中に初めて登場する魔法少女である。その夢の翌日、彼女はまどかの通う学校に転校してくる。美しく、謎めいた人物で、学業もスポーツも抜群の才能を発揮する。 そのため、他人には冷淡な態度をとっているにもかかわらず、瞬く間に人気者となる。彼女はまどかのことをよく知っているようで、まどかが魔法少女になるのを阻止しようとしている。第1話ではキュゥべぇを攻撃するが、マミに阻止されてしまう。    ほむらの際立つ黒い髪は', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b38005-T3NR8p2f021x.jpg', NULL, NULL, '斎藤千和', NULL, 38005, 'SUPPORTING', 12036) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023588', 'AN2046', '天音月夜', 'ツカサの双子の妹、ツクヨは魔法少女たちを解放したいと願っている。音楽、書道、舞踊の絶え間ない訓練により、彼女はかなりの腕前を身につけた。同級生たちからは慕われているものの、心を開けるような友人は一人もいない。 姉のツカサと一緒にいる時だけ、彼女は安らぎを感じることができる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164867-EvLp4MKoZfnC.png', NULL, NULL, '内田真礼', NULL, 164867, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023589', 'AN2046', '万年桜のウワサ', 'ウワサは、自分のそばに少女たちが集まるのを待ちわび、そうして初めて満開の花を咲かせることができる。彼女は「噂」にいくつかの修正を加えることでそこから抜け出すことはできるが、一般的な知識に乏しいため、周囲からは変わり者だと見なされている。彼女はいつも、自分の山に戻りたい、あるいは愛する人たちと一緒にいたいと願っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249738-uNWYEtA6WpMQ.png', NULL, NULL, '鈴木みのり', NULL, 249738, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023590', 'AN2046', '柊ねむ', '魔女のいない世界を作るために奮闘する魔法少女。ネムは、ただ誰かに認められたいという思いから物語を書き始めたが、その作品をネット上に投稿して初めて、文豪として知られるようになった。彼女の夢は、自分の物語で世界全体を包み込むことだ。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158075-ITBg7tfifMNj.jpg', NULL, NULL, '諸星すみれ', NULL, 158075, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023591', 'AN2046', '鹿目まどか', '14歳の少女。魔法少女ほむらと、彼女を魔法少女に変身させてあげると申し出た使い魔のキュゥべぇとの出会いをきっかけに、人生が一変する。 彼女は自分には特別な資質や才能などないと考えていたが、魔女と戦うマミの姿を見て、彼女のような素晴らしくクールな魔法少女になりたいと思うようになる。他人を助けるためだけに魔法少女になりたいと願う、かなり無私無欲な少女だ。彼女には、膨大な魔法の潜在能力が秘められていると言われている。   M', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b37832-lzVj5IkUciLd.jpg', '10月3日', 'A', '悠木碧', 152, 37832, 'SUPPORTING', 5181) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023592', 'AN2046', '天音月咲', '月夜の双子の妹である月沙は、魔法少女たちを解放したいと願っている。伝統的な竹工芸の職人の家に生まれ、彼女は父とその弟子を支えるために家事を切り盛りしている。明るく友達も多いが、心を開けるのは月夜だけだ。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164869-Lk8FEAQZc7mO.png', NULL, NULL, '内田彩', NULL, 164869, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023593', 'AN2046', 'アイ', '「果てしない孤独」のウワサ。もともとは人間によって構築されたAIだったが、後に「果てしない孤独」に閉じ込められた孤独な少女の一人である二葉さなによって「アイ」と名付けられた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b164866-SmAmHd5hc3FP.png', NULL, NULL, '咲々木瞳', NULL, 164866, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023594', 'AN2046', '里見灯花', '魔女のいない世界を作るために活動する魔法少女。里見医療センターの所長の娘であり、同センターの患者でもあるトカは、天体物理学の神童だ。数々のガジェットや装置に囲まれながら、彼女はただひとつの夢――宇宙のすべてを知ること――を追い求め、研究を続けている。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158076-8cRUXgz5Fynm.png', NULL, NULL, '釘宮理恵', NULL, 158076, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023595', 'AN2046', '巴マミ', '巴マミはベテランの魔法少女であり、まどかの通う学校の3年生だ。両親が交通事故で亡くなった後、マミはペントハウスで一人暮らしをしている。マミ自身はキュゥべぇと契約を結んだことで、その事故を生き延びた。 マミは、周囲の人々を救い、導き、守ることに特に力を注いでおり、これは魔法少女という役割に対する伝統的な無私の姿勢である。彼女はその中で最年長であるため、まどかやさやかにとってはまるで母親のような存在だ。彼女の名前は、ある言葉をもじったものと考えられる。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b38194-gnlnx4XN4HYP.jpg', NULL, NULL, '水橋かおり', NULL, 38194, 'SUPPORTING', 1890) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023596', 'AN2046', '和泉十七夜', '「東のボス」。平等と平和を願う魔法少女。利他的で正義感にあふれ、そのカリスマ性によって、人々は彼女の存在感と言葉の力に惹きつけられる。貧しい家族を養うために生活費を稼がなければならないため、彼女は毎日、いくつものアルバイトに追われている。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247006-9D3ApHWFo6ko.png', NULL, NULL, '千本木彩花', NULL, 247006, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
