INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023617', 'AN2048', '毛利玲菜', 'レナは、東京の高校に通う明るく元気な高校2年生だ。彼女はいわゆる「ギャル」であり、若者層に人気のSNS「カワスタ」で数万人のフォロワーを誇るインフルエンサーでもある。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213474-7PRFIk97mN3j.png', '6月7日', NULL, '伊藤彩沙', 162, 213474, 'MAIN', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023618', 'AN2048', '伏辺或斗', 'アルトは東京に住む小学生です。ゲームが得意で、eスポーツの大会にも出場し、賞金を獲得したことがあります。病気の母親の代わりに家事をすべてこなしてきたため、年齢の割に大人びていて、少し生意気なところもあります。', 11, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b213472-rpQZfU6WkfOr.png', '11月3日', NULL, '堀江瞬', 146, 213472, 'MAIN', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023619', 'AN2048', '織田龍平', 'リュウヘイは、東京の高校に通う2年生だ。明るく、気さくで、率直な性格の持ち主だ。正義感が強く、考える前に行動してしまうタイプだ。キックボクシングを習っている。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213477-rsPBxoz7183Y.png', '7月4日', NULL, '阿座上洋平', 185, 213477, 'MAIN', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023620', 'AN2048', 'ジェシカ・クレイボーン', 'ジェシカはアメリカ出身の謎めいた少女だ。見た目は小学生のようだが、実際の年齢は成人だと言われている。彼女はかつて米陸軍に所属していたと主張しており、常に冷静に作戦を遂行している。', 31, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213473-T4N9LzMY5r4Y.png', '9月21日', NULL, '悠木碧', 148, 213473, 'MAIN', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023621', 'AN2048', '伊吹咲愛莉', 'エリは、東京の高校に通う、クールで真面目な高校2年生だ。成績は優秀で、父親は警察庁の幹部である。優等生ではあるが、あまり笑顔を見せず、いつも周囲の話し合いを傍観している。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213475-nFiLmYqxh893.png', '1月5日', NULL, '高野麻里佳', 167, 213475, 'MAIN', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023622', 'AN2048', 'トリス', 'リュヘイとその仲間たちに「ノッカーアップ」という能力を授けた謎の生物。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b213476-Cw9DfaJXzLVh.png', NULL, NULL, 'もものはるな', 70, 213476, 'MAIN', 2) ON CONFLICT DO NOTHING;
