INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023637', 'AN2049', '和泉一織', '彼は和泉三月の実の弟で、「クール」な性格の持ち主だ。両親は「フォンテ・ショコラ」というケーキ店を経営しており、店内は可愛らしく装飾されているため、その影響で彼も結局は可愛いものが好きになった。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126159-JP89KQJs2J5o.png', '1月25日', NULL, '増田俊樹', NULL, 126159, 'MAIN', 282) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023638', 'AN2049', '逢坂壮五', '逢坂壮五は、時折迷いを見せることもありますが、ほとんどの場合、非常に穏やかで心を落ち着かせてくれる存在です。 ただ、彼は非常に控えめで、自分の望みよりも礼儀を重んじ、物事の順序を守ることを優先する。しかし、彼には「スイッチ」があり、それを押せば、壮五は瞬く間にIDOLiSH7の中でも最も威圧的なメンバーの一人へと変貌する。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126247-56SleuAnKbVJ.png', '5月28日', NULL, '阿部敦', 175, 126247, 'MAIN', 343) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023639', 'AN2049', '七瀬陸', '七瀬陸は、その華奢な体つきからは想像できないほど、可愛らしく元気な性格の持ち主だ。 それでも、彼はできる限りのことに一生懸命取り組み、他人の負担になりたくないと願っている。幼少期のほとんどを病院での生活と退院を繰り返して過ごしたため、陸にはまだ世の中のことがよく分かっていないことが多く、感情を隠さず表に出してしまうため、その純真さがしばしば表れてしまう。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126246-RvhjVQ6iNoBC.png', '7月9日', NULL, '小野賢章', 173, 126246, 'MAIN', 331) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023640', 'AN2049', '和泉三月', '和泉三月は、IDOLiSH7の他のメンバーのほとんどにとって、前向きなエネルギーの源となっています。彼は、年下のメンバーたちの多くや、実の弟である和泉一織に対して、兄のような役割を果たしています。', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125894-dQdnk7GPrHri.png', '3月3日', NULL, '代永翼', 165, 125894, 'MAIN', 247) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023641', 'AN2049', '四葉環', NULL, 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126095-OsZ0wjvuSrH0.png', '4月1日', NULL, 'KENN', 183, 126095, 'MAIN', 284) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023642', 'AN2049', '六弥ナギ', '六弥ナギは、その際立ったルックスと高いカリスマ性が相まって、いわば「モテまくる男」となっており、女性とイチャイチャしている姿をよく目にする。しかし、そのカリスマ性は諸刃の剣でもある。彼の性格とルックスのせいで、幼い頃は友達があまりいなかったからだ。 その結果、彼は誰よりもIDOLiSH7を愛している。困難な状況に直面した時、仲間たちの顔に笑顔を取り戻すことができるのは、たいていナギが仲間たちに対して抱く、誰の目にも明らかな愛情のおかげだ。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126248-TQtG2jVaVvdb.png', '6月20日', NULL, '江口拓也', 180, 126248, 'MAIN', 257) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023643', 'AN2049', '二階堂大和', '二階堂大和は、とても怠け者で気楽な印象を与えるが、自分の仕事には非常に情熱を注いでおり、IDOLiSH7の他のメンバーのことをとても大切に思っている。 彼が「リーダー」の座に就いたのは、単にグループ内で最年長だったからに過ぎず、実はIDOLiSH7のオーディションを辞退しようかとさえ考えていたほどだ。', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126106-V5VZFlzoBaiY.png', '2月14日', NULL, '白井悠介', NULL, 126106, 'MAIN', 195) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023644', 'AN2049', '八乙女楽', '八乙女楽は口が悪く、かなり威圧的なオーラを漂わせているため、「ヤオトメ・プロ」社長の息子はどれほど厄介な人物なのか、さまざまな噂が飛び交っている。ファンにとっては、彼こそが最も抱きしめてほしいと思うセクシーな男性なのだ。', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126250-c0JKhjXD7x1D.png', '8月16日', NULL, '羽多野渉', 183, 126250, 'SUPPORTING', 380) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023645', 'AN2049', '岡崎凛人', 'Re:valeのマネージャー', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192988-ZRMG82gol7aF.jpg', NULL, NULL, '古川慎', NULL, 192988, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023646', 'AN2049', '花巻すみれ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b243920-Q6GgQWWJyTRp.jpg', NULL, NULL, '渕上舞', NULL, 243920, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023647', 'AN2049', '九条天', '彼は一見、小悪魔のような風貌をしており、完璧主義者で、実力に関しては厳しい。 彼は、公の場にいるときはいつでも、1日24時間、1年365日、完璧なパフォーマンスを披露するために全力を尽くすと心に誓った。その高いプロ意識ゆえに、以前から彼を知っている人でさえ、彼が冷淡な性格だと誤解しがちだ。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89894-royCGylW0TwD.png', '7月9日', NULL, '斉藤壮馬', 173, 89894, 'SUPPORTING', 389) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023648', 'AN2049', '八乙女宗助', 'ヤオトメ・プロダクションズの社長であり、ガクの父親。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190930-eGu53pJQNXir.jpg', NULL, NULL, '小西克幸', NULL, 190930, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023649', 'AN2049', '春原瑠璃', 'モモの姉。弟にRe:valeを最初に紹介したのは彼女だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210808-f9lsK0nk7ruS.jpg', NULL, NULL, '斎藤千和', NULL, 210808, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023650', 'AN2049', '春原百瀬', '春原百瀬、通称「モモ」は、デュオ「Re:vale」のエネルギッシュでキュートなメンバーです！モモには少しいたずら好きな一面があり、ユキを自分の企みに巻き込んでしまうようです。彼は二人組の「ボケ」役で、常に突拍子もない発言をしています。  しかし、モモは周囲の状況や他人のことを驚くほどよく観察しており、他人を気遣うためにかなりの努力を惜しまないようだ。その一方で、実は自分自身のことに関してはかなり無頓着な面もある。', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b143807-53bbiEPYHzkB.jpg', '11月11日', NULL, '保志総一朗', NULL, 143807, 'SUPPORTING', 440) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023651', 'AN2049', '狗丸トウマ', 'ZoLのボーカル、狗丸トウマは、かつては音楽に真剣に取り組んでいたが、現在はTRIGGERへの復讐のためだけに活動している。彼はIDOLiSH7もTRIGGERも嫌っているが、かつて七瀬陸が困っていた時には、彼を背負って助けたこともある。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158599-YwCDN5LIa806.jpg', '11月29日', NULL, '木村昴', 176, 158599, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023652', 'AN2049', '折笠千斗', '折笠千斗（通称「ユキ」）は、デュオ「Re:vale!」の中で、冷静沈着なメンバーです。 ユキは、モモの奇行に対していつも謝り続けている。彼はこのペアのツッコミ役であり、モモがその時々に見せる馬鹿げた行動を的確に指摘し、そのツッコミを最後まで貫く。  意外なことに、ユキは実はとても笑いがこみ上げやすく、あるいは冷静さを失いやすい。たいていは、彼が正そうとしているモモの行動そのものが原因でそうなってしまう。彼は、自分より後に業界に入った後輩たちを大変大切にしており、', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b143808-Q3kmz4Y93V4a.jpg', '12月24日', NULL, '立花慎之介', NULL, 143808, 'SUPPORTING', 272) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023653', 'AN2049', '棗巳波', '南夏目は、かつて子役として頭角を現した天才児だが、その落ち着きのある優しい笑顔の裏には闇を隠している。ZoLの作詞家である。また、非常に優れた占い師でもあり、その能力を駆使して、他人のさまざまな性格的特徴を指摘することが多い。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158601-piFLtTkXQ7TK.jpg', '6月8日', 'AB', '西山宏太朗', 174, 158601, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023654', 'AN2049', '小鳥遊紡', '小鳥遊紡は、男性アイドルグループ「IDOLiSH7」のマネージャーです。彼女はとても礼儀正しく、優しい女の子です。彼女は、父親が経営する音楽事務所「タカナシ・プロダクションズ」で働いています。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127081-nuRCpkrxVf7v.jpg', NULL, NULL, '佐藤聡美', NULL, 127081, 'SUPPORTING', 88) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023655', 'AN2049', '亥清悠', 'ZoLのボーカル兼ダブルセンター。春海遥は甘い顔立ちをしているが、その裏では自分を認めてくれない相手には一切譲らない。泉伊織や四葉玉樹と同じ高校に通う、自己中心的な高校生である。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158597-qZfr6WWXiUij.jpg', '12月6日', NULL, '広瀬裕也', 170, 158597, 'SUPPORTING', 114) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023656', 'AN2049', '大神万理', 'バンリは音楽事務所「タカナシ・プロダクションズ」で働くスタッフの一人で、事務所のために献身的に尽くす心優しい男性です。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152146-PdvVvuBCZ0zd.jpg', '9月8日', NULL, '興津和幸', NULL, 152146, 'SUPPORTING', 112) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023657', 'AN2049', '御堂虎於', 'ZoLのメンバー。自分に強い自信を持っており、女性を軽々しく扱う傾向がある。', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158600-KuTLeFGGp644.jpg', '3月15日', NULL, '近藤隆', 185, 158600, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
