INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023659', 'AN2049', '月雲了', '彼は、ZoLの所属事務所であるツクモ・プロダクションズの元社長である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226465-NotdDNUDqRiX.jpg', NULL, NULL, '高橋広樹', NULL, 226465, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023660', 'AN2049', '十龍之介', '十龍之介は、実はとても内気で臆病な青年で、兄弟たちと一緒に育ったため、女性と話すのが苦手だ。 また、父が経営するホテルで女性に対して発した言葉からも、リュウの純真さがうかがえる。彼は年下の人に対して非常に親切で思いやりがあり、ほぼ誰に対しても兄のような振る舞いをしている。', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126249-gK2KBhVzlRLG.png', '10月12日', NULL, '佐藤拓也', 190, 126249, 'SUPPORTING', 188) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023661', 'AN2049', '小鳥遊音晴', 'タカナシ・プロダクションズの社長であり、ツムギの父親。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190929-eXYDtc4hxiId.jpg', NULL, NULL, '千葉進歩', NULL, 190929, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
