INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023663', 'AN2050', '流 拓馬', 'ナガレ・リョーマの息子であり、『ゲッターロボ アーク』のパイロットの一人。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b57369-K7kR3tE4JWu1.jpg', NULL, NULL, '内田雄馬', NULL, 57369, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023664', 'AN2050', '神隼人', '『ゲッターロボ』の第2代パイロットであるハヤトは、サイコパスでありながら極めて知性的な不良として描かれている。当初は学生革命グループのリーダーとして登場するが、リョウマとの戦いの末、早乙女研究所に捕らえられ、ゲッターロボの物語に巻き込まれる。当初はゲッター2のパイロットとして活躍した。 彼は『ゲッターロボ』シリーズ全作に登場した唯一のキャラクターであり、普通の10代の少年から、大人の大佐、そして老いた科学者まで、さまざまな役割を演じてきた。  ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/8663.jpg', NULL, NULL, '内田直哉', NULL, 8663, 'MAIN', 151) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023665', 'AN2050', 'カムイ・ショウ', 'カムイ・ショウは、恐竜と人間のハイブリッドである。彼はゲッターチームのメンバーだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217343-7FseKJGljjW1.png', NULL, NULL, '向野存麿', NULL, 217343, 'MAIN', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023666', 'AN2050', '山岸獏', '山岸獏は、自身も僧侶であるメシア・タヒルの弟であり、流拓馬の仲間である。彼はゲッターチームのメンバーである。  （出典：ゲッターロボウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b217344-EQBrSIRNEJpS.jpg', NULL, NULL, '寸石和弘', NULL, 217344, 'MAIN', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023667', 'AN2050', '橘翔', '橘翔は、同名の漫画に登場する「ゲッターロボGo」のパイロットの一人である。彼女は立花博士の娘であり、親しい関係にあった立花真一の妹でもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b174767-5FS2YGJogIdc.jpg', NULL, NULL, '浅川悠', NULL, 174767, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023668', 'AN2050', 'ロン・シュヴァイツァ博士', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244824-XRfJhCZ4dNzU.jpg', NULL, NULL, '小野大輔', NULL, 244824, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023669', 'AN2050', '一文字號', '『ゲッターロボGo.Go』の主人公は、驚異的な力と運動能力を持つ意志の強い10代の少年だが、暴力的な面もあり、当初は人生にほとんど興味を示していなかった。その大胆な行動がやがて神隼人大佐の目に留まり、NISARに加入させられ、ゲッターロボGoの3人のパイロットの一人となる。    また、漫画を大まかに基にしたOVA『新ゲッターロボ対ネオゲッターロボ』でも主人公として登場している。その役割やキャラクターは多少似ているが、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/15784.jpg', NULL, NULL, '櫻井孝宏', NULL, 15784, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023670', 'AN2050', '巴武蔵', '3人目のパイロットである彼は、非常に熱血な若者で、ゲッターマシン「ベア」とゲッター3を操縦する。武蔵は小柄で太っているが、県の柔道部の主将として試合で一度も負けたことがないほど、身体能力は非常に高い。 ゲッターロボのパイロットになるために必要な体力・精神力のテストには不合格となるものの、その熱血な気性と頑固さでそれを補い、チームにとって欠かせない存在となる。武蔵のドジで不器用な性格は、作品の大きな特徴を形成しており、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/18490.jpg', NULL, NULL, '辻親八', NULL, 18490, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023671', 'AN2050', 'ゴル', 'ゴル皇帝は、恐竜帝国の指導者である。地球のマグマの中で数千年の時を過ごした後、地表への進出を望む彼は、地球の主要都市や、帝国にとって最大の脅威であるゲッターロボが潜む地域への攻撃を指揮している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b219018-JlsVanFaPUwF.jpg', NULL, NULL, '置鮎龍太郎', NULL, 219018, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023672', 'AN2050', '流竜馬', 'リョーマはゲッターチームの初代リーダーであり、多くの『ゲッターロボ』作品における主人公である。原作漫画では、彼は極めて凶暴な武道家として描かれており、「道場破壊者」ことナガレ・イチガンの息子である。   竜馬が初めて早乙女博士の助手たちに発見されたのは、父の名誉を傷つけた者たちへの復讐を果たすため、空手大会に乱入した時だった。その腕前に感銘を受けた早乙女は、彼の能力を試すため、3人の殺し屋を送り込んだ。竜馬は1人を殺し、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b6107-jDp1qzjQAsxL.jpg', NULL, NULL, '石川英郎', NULL, 6107, 'SUPPORTING', 378) ON CONFLICT DO NOTHING;
