INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023674', 'AN2050', '敷島博士', '早乙女研究所で働いていた科学者の一人。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/43686.jpg', NULL, NULL, '多田野曜平 ', NULL, 43686, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
