INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023676', 'AN2050', '車弁慶', '第2期漫画シリーズの第3話となるパイロットエピソードでは、弁慶が百鬼帝国との戦いに加わる。彼はゲッターロボGの第3形態である「ゲッターポセイドン」を操縦する。熱狂的な野球ファンである彼のパイロットスーツには、審判用の防護ベストやマスクなど、野球の用具がいくつか取り入れられている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/8662.jpg', NULL, NULL, '梁田清之', NULL, 8662, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023677', 'AN2050', 'バイス', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244821-CsKA426O3h3M.jpg', NULL, NULL, '高橋良輔', NULL, 244821, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023678', 'AN2050', '早乙女博士', 'ほとんどの『ゲッターロボ』の作品において、彼はもともと深宇宙探査のために設計された機械「ゲッターロボ」の発明家であり、やがて「ゲッターレイ」と呼ばれる宇宙エネルギーを発見し、それに没頭するようになる。 娘は早乙女みちる、息子は早乙女達人であり、家族全員が早乙女研究所で彼と共に働き、暮らしている。また、早乙女博士は通常、適任な新しいゲッターロボのパイロットを選抜する責任者でもあり、その選抜はしばしば、残酷で危険な体力テストを通じて行われる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b17723-pUGqDboAPZNm.png', NULL, NULL, '菅生隆之', NULL, 17723, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
