INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023690', 'AN2051', '篁志季', 'SolidSのリーダー。（出典：公式サイト）', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/123980-WU0rOjD36Xfa.jpg', '1月25日', 'A', '江口拓也', 178, 123980, 'MAIN', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023691', 'AN2051', '藤村衛', '「Growth」のメンバーであり、かつてはニートだったがコキにスカウトされた守は、明るく気さくな性格の謎めいた青年だ。とても人懐っこく、誰とでもすぐに打ち解けることができる。守は、その破壊的な生活態度とは対照的に、独自の世界観からインスピレーションを得て音楽を生み出す、神がかった才能の持ち主である。  （出典：公式サイト）', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123967-EcLPCsBv3LeV.jpg', '10月5日', 'B', '寺島惇太', 176, 123967, 'MAIN', 22) ON CONFLICT DO NOTHING;
