INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023697', 'AN2052', '桃山みらい', 'キラリガオカ中学校の1年生。好奇心旺盛な一方で、人目につくのが苦手な内向的な性格。下手だけど愛嬌のあるイラストを描くのが好き。キャッチフレーズは「キラット」。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n124856-Y0EBY29ESKzG.png', '7月12日', NULL, '林鼓子', NULL, 124856, 'MAIN', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023698', 'AN2052', '彩瀬なる', '中学2年生の14歳の少女で、愛らしい性格の持ち主。物事を飾り付けるのがとても得意で、目につくものは何でも飾り付けてしまう。 少しおっとりした性格で、お気に入りの店「ディア・クラウン」のようなプリズムショップをいつか持ちたいという夢を抱いている。しかし、初めてのプリズムショーに参加したことをきっかけに、原宿にある「プリズムストーンショップ」の店長に就任することになる。彼女は音楽の「色」を見ることができる。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b80423-YdFrM0vOrijK.jpg', '3月3日', 'O', NULL, 145, 80423, 'MAIN', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023699', 'AN2052', '春音あいら', 'アイラは、ジュンという男性に「プリズムスター」としてスカウトされた中学生の女の子だ。彼女はとても不器用で、スポーツもあまり得意ではない。アイラはいつも物事の明るい面を見ようとし、ミオンの大ファンだ。とても純真だが、誰に対しても思いやりがある。 彼女には、よくからかう弟と、いつも彼女を応援してくれる双子の妹が2人いる。とんでもなく不器用ではあるが、服のコーディネートは抜群に上手で、それはかつてプリズムショーのスタイリストだった母親、オミ・ハルから受け継いだ才能かもしれない。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b42115-x2jSxcbWrige.png', '9月3日', NULL, NULL, NULL, 42115, 'MAIN', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023700', 'AN2052', '上葉みあ', '彼女は、ナンバーワンを目指して全力を尽くす、エネルギッシュな10代の少女だ。彼女の決め台詞には、「ミアがイチバン！」、驚いた時の「ガァァァァーン！」、そして「キ・ド・アイ・ラック！」（モチベーション・パッション・ラブ・ラック）などがある。 一見、かなり鈍感で、率直に言って頭が悪いように見えますが、その率直さと純真さが彼女の原動力となっています。プリズミーのメンバーは皆、ミアの言い回しが下手なことを知っていますが、彼女は誰に対しても悪意を持っているわけではありません。彼女は決して嘘をつかず、常にルールを守って行動しています。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b57199-LXMcfUm4Xul8.png', '8月8日', NULL, NULL, NULL, 57199, 'MAIN', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023701', 'AN2052', '夢川ゆい', '夢川ゆいは『アイドルタイム プリパラ』の主人公であり、アボカド学園の6年生です。彼女は「ラブリータイプ」のアイドルで、ブランド「ファンタジータイム」を好んでいます。 彼女はよく文の途中や最後に「ゆめ」を付け加えたり、ラアラの「カピスチェ！」のように「ゆめかわ」をキャッチフレーズとして使ったりする。また、MY☆DREAMのチームリーダーでもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/126058-CcMEd8eZPSac.jpg', '8月18日', NULL, NULL, NULL, 126058, 'MAIN', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023702', 'AN2052', '真中らぁら', 'ラアラは明るく陽気な性格で、よく壁を跳ね回る姿が見られます。彼女が働くのはレストランなので、リクエストを受ける際、口癖の「カピスチェ！」 （カシコマ！）と口にする癖がある。ラアラは声がとても小さいことを非常に気にしており、そのせいで歌うときはとても小声になりがちだ。プリパラでのパフォーマンス中だけ、大声で歌う勇気を出せるようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n88927-u0LjjmO70eTt.jpg', '11月20日', NULL, NULL, NULL, 88927, 'MAIN', 211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023703', 'AN2053', '煉獄杏寿郎', '戦闘スタイル：火炎吐息　「炎の柱」としての任務に対して非常に熱心で、しばしば陽気なほど風変わりな一面を見せる。人当たりが良く、親切で、厳しい修行と規律から培われた並外れた火炎術と剣術を誇る。   彼は、幼い頃に母から叩き込まれた道徳観と信条を忠実に守る高潔な戦士である。その中でも最も重要なのは、「生まれながらにして強い者は、弱い者を守る義務がある」という信念である。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129133-VlTPowwt68rJ.png', '5月10日', NULL, '日野聡', 177, 129133, 'MAIN', 12034) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023704', 'AN2053', '魘夢', '種族：鬼　魘夢は、人間を苦しめることだけを喜びとする、サディスティックで残忍な鬼である。彼は無惨に対して絶対的な忠誠を誓っており、おそらく自分自身を気遣う以上に無惨を大切に思っている。また、他の下級鬼たちを「フォール」と蔑称し、彼らを嫌悪している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139737-1YaFT0Xvxwaz.png', NULL, NULL, '平川大輔', 168, 139737, 'SUPPORTING', 567) ON CONFLICT DO NOTHING;
