INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023709', 'AN2053', '煉獄槇寿郎', '京十郎と千十郎の父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b193379-54MeZxQdvZ9o.jpg', NULL, NULL, '小山力也', NULL, 193379, 'SUPPORTING', 100) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023710', 'AN2053', '竈門炭十郎', '竈門炭十郎は、竈門葵枝の夫であり、炭治郎、禰豆子、武雄、花子、茂、六太の亡き父であった。炭十郎は、物静かで思慮深く、寛容で、カリスマ性があり、愛情深い人物だった。 彼は家族と穏やかな関係を築き、たじろに人生について頻繁に説教をしていた。外見は穏やかだったが、周囲を静かに見極める力と、気高く高潔なオーラを漂わせていた。息子の話によると、彼は目立つことや、他人に自分の真の実力を見せつけることを好まなかったという。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206330-dDKOKM4O2pVg.png', NULL, NULL, '三木眞一郎', NULL, 206330, 'SUPPORTING', 149) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023711', 'AN2053', 'トミ', 'お弁当屋。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b257801-tw7AIdZIo0Ay.png', NULL, NULL, '井上喜久子', NULL, 257801, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023712', 'AN2053', '煉獄千寿郎', '煉獄杏寿郎の弟であり、煉獄槇寿郎と煉獄瑠火の息子。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b193380-W10Kx339cY4D.png', NULL, NULL, '榎木淳弥', NULL, 193380, 'SUPPORTING', 221) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023713', 'AN2053', '切り裂き', '「切り裂き」とは、ムゲン・トレインの調査中に現れ、数多くの人間への襲撃を行った悪魔につけられたあだ名である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252147-gRa8umJxLWGs.jpg', NULL, NULL, '伊藤健太郎', NULL, 252147, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
