INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023716', 'AN2053', '竈門竹雄', 'タケオは、竈門炭治郎の最初の弟だった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196852-zzu0xZXJrFr9.png', NULL, NULL, '大地葉', NULL, 196852, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023717', 'AN2053', '猗窩座', '「十二魔蒙」の一員であり、上蒙三の地位にある。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141694-0COi0GVXPuEn.png', NULL, NULL, '石田彰', 173, 141694, 'SUPPORTING', 4230) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023718', 'AN2053', '竈門葵枝', 'キエは竈門炭治郎の母親です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b196849-xnYBt0Jf5Htf.png', NULL, NULL, '桑島法子', NULL, 196849, 'SUPPORTING', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023719', 'AN2054', '古見硝子', '立場：女神　親族：古見笑介（弟）、古見秀子（母）、古見将賀（父）、古見結子（祖母）、古見晶（いとこ）、古見定義 （叔父）　古見硝子は本作の主人公である。学校では「マドンナ」と称されているが、コミュニケーション障害と呼べるほど他人と交流することができない。  ショウコは、ファンたちから、腰まで流れるつややかな濃い紫がかった黒髪の少女として描かれている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121956-5FbIbcd6gAZW.png', '12月25日', 'A', '古賀葵', 168, 121956, 'MAIN', 8307) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023720', 'AN2054', '只野仁人', '役職：会長　親族：只野瞳（妹）　只野仁人は、ほぼあらゆる点でごく平凡な人物である。彼の名前は「ただの男」という意味だ。彼は古見硝子と真っ先に親しくなった人物である。  只野は、ごく普通の外見で、身長も体重も平均的な、ありふれた生徒としてよく描かれる。服装のスタイルも比較的典型的だ。彼の唯一の特徴といえば、黒髪の中に一筋ある白い立ち毛である。文化祭で女装を強いられた際、彼は……', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b78093-QnJ9wDICvhSR.png', '9月29日', 'O', '梶原岳人', 168, 78093, 'MAIN', 2782) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023721', 'AN2054', '長名なじみ', '役職：副社長　ナジミは、性別が不明な謎めいた学生です。コミュニケーション能力に長けており、会って数分もすれば誰とでもすぐに親しくなれます。幼少期、ナジミは頻繁に転校を繰り返していたため、数え切れないほどの友達を作ることができました。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126825-J4GTiz4OHDa5.png', '4月1日', NULL, '村川梨衣', NULL, 126825, 'MAIN', 2244) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023722', 'AN2054', '地洗井茂夫', 'キアライ・シゲオは1年1組の生徒です。キアライはソノダやシノビノと友達です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160221-pqsCU44cyQyz.png', '7月8日', NULL, '赤羽根健治', NULL, 160221, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023723', 'AN2054', '尾根峰ねね', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130872-FkJv0wh1Y5Yx.png', '7月7日', NULL, '青木瑠璃子', NULL, 130872, 'SUPPORTING', 501) ON CONFLICT DO NOTHING;
