INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023725', 'AN2054', '園田大勢', '園田泰生は1年1組の生徒だ。園田は千原や忍野と友達である。この3人が最も目立つのは第6巻の第75話と第77話で、そこでは3人がクラスの女子（＋ナジミ）のうち、誰と付き合うのが一番いいかについて話し合っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160224-ScC6rjK9l6nV.png', '9月8日', NULL, '佐藤悠雅', NULL, 160224, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023726', 'AN2054', '尾鶏かえで', 'のんびり屋で、物事をゆっくり進めるのが好きな女の子。そのせいで、クリスマスから元日までずっと暖炉の映像を見続けていたほどだ。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249856-u7JjuRKqdD2O.png', '6月10日', NULL, '森山由梨佳', NULL, 249856, 'SUPPORTING', 408) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023727', 'AN2054', '雁巣真姫', '真木カリスは、古見翔子の美容師だ。カリスは顧客に対して非常にプロフェッショナルな対応を見せている。古見が店に来ると、カリスは古見が何も言わなくても、彼女が何を望んでいるかを正確に理解することができる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160218-FZJYaO97YsV1.png', NULL, NULL, '伊藤静', NULL, 160218, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023728', 'AN2054', '忍野裳乃', '忍野モノは1年1組の生徒だ。彼は千原や園田と友達である。この3人は第6巻の第75話と第77話で特に目立っており、そこで3人はクラスの女子（＋ナジミ）のうち、誰と付き合うのが一番いいかについて話し合っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160222-powdZ52BxB3W.png', '10月16日', NULL, '小野賢章', NULL, 160222, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023729', 'AN2054', '山井恋', '山井恋は、小見翔子の1-1組の同級生の一人です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130874-Q77FIzvZcFz1.png', '11月8日', NULL, '日高里菜', NULL, 130874, 'SUPPORTING', 165) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023730', 'AN2054', '勅使河原欲子', 'ホシコが初めて登場するのは、第43話「アルバイト」の8～9ページで、コミがポケットティッシュを配っている場面であり、ホシコはまさにティッシュを必要としていた。 ホシコはコミに気づくが、自分でティッシュを受け取りに行くのはあまりにも切羽詰まった行動だ。非言語的なサインを読み取るのが得意なコミは、ホシコから発せられる「ティッシュが欲しい」という強烈なオーラを察知し、見事にホシコに初めてのポケットティッシュのパックを手渡すことに成功する。', 26, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160225-eyokLCmxJ6ei.png', NULL, NULL, '向井莉生', NULL, 160225, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023731', 'AN2054', '上理卑美子', '上理卑美子は、内気で自信のない少女として描かれている。また、ラーメン店のレビューブログを運営しており、自らを「ラーメン通」だと自負している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130869-lkVsFPB1KXw5.jpg', '4月30日', 'B', '藤井ゆきよ', NULL, 130869, 'SUPPORTING', 194) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023732', 'AN2054', '古見笑介', '親族：古見結子（祖母）、古見将賀（父）、古見秀子（母）、古見定義（叔父）、古見良子（叔母）、古見硝子（姉）、古見晶 （いとこ） 古見笑介はショウコの弟である。普段は物静かだが、会話は上手だ。笑介は短く刈り込んだ髪型で、前髪で目が隠れていることが多い。 それでも、その容姿は母や姉に似ており、ハンサムな男性と言える。  正介は多くの特徴を', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130870-9fSkcaHdQXFq.png', NULL, NULL, '榎木淳弥', NULL, 130870, 'SUPPORTING', 545) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023733', 'AN2054', '古見晶', '古見晶は、翔介と翔子のいとこである。当初、彼女は、言葉を発することができず、黙って晶をじっと見つめ続ける翔子の様子に怖がっていた。しかし、うどん祭りに訪れた際、翔子にくすぐられたことをきっかけに、二人は親しくなった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130876-id56lFSXz6s0.png', NULL, NULL, '本渡楓', NULL, 130876, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023734', 'AN2054', '根津野ちか', '根津野ちかは、多田野、翔子、奈仁美より1学年上の生徒で、翔子のスポーツ面でのライバルである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160203-y6up72MlNbZn.png', NULL, NULL, '潘めぐみ', NULL, 160203, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023735', 'AN2054', '中々思春', '中二病のせいで、普段から曖昧な話し方をする生徒。自分は「アルソット・レス・プリマヴェーラ」であり、古見硝子は「コミリア姫」だと主張している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128378-M2kHIBoYvazc.png', '2月29日', NULL, '大久保瑠美', NULL, 128378, 'SUPPORTING', 501) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023736', 'AN2054', '只野瞳', '親族：只野仁人（兄）　只野瞳は只野仁人の妹である。人の心を読む能力という点では兄に似ている。物事に消極的で内気な兄とは対照的に、彼女は活発な性格だ。  瞳は小柄な少女で、兄と同じく大きくて丸い目をしており、表情も似ている。ミディアムレングスの髪を短いツインテールに結っている。 普段「普通」と見なされる兄とは対照的に、瞳は', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130878-E6iil2Bh2JIX.png', NULL, NULL, '内田真礼', NULL, 130878, 'SUPPORTING', 158) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023737', 'AN2054', '古見良子', '小見緑央は翔子の叔母です。彼女は翔子の母親と同じくらい活発なので、知らず知らずのうちに翔子を威圧してしまうことがあります。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130877-CzNhth7ommrZ.png', NULL, NULL, '篠原恵美', NULL, 130877, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023738', 'AN2054', '古見秀子', '親族：古見結子（義母）、古見将賀（夫）、古見定義（義兄）、古見硝子（娘）、古見笑介（息子）、古見晶 （姪）　古見秀子（旧姓：仁見秀子）は、翔子と翔介の母親である。外見は娘に似ているが、性格は10代の少女そのもので、「永遠に17歳」だと主張している。 絶望すると、彼女は「永遠の18歳」になってしまう。息子や娘と同様に、秀子も美しいとされている。対照的に、彼女はとてもおしゃべりだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130867-cdy2mWlQhiX9.png', NULL, NULL, '井上喜久子', NULL, 130867, 'SUPPORTING', 403) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023739', 'AN2054', '古見結子', '親族：古見将賀（息子）、古見定義（息子）、古見秀子（嫁）、古見良子（嫁）、 古見晶（孫娘）、古見硝子（孫娘）、古見笑介（孫）　古見結子は、翔子、晶、笑介の祖母である。厳格だが、家族に対しては優しい。訪ねてくると、たいてい彼らにゲームを挑んでくる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130875-FbYx3qQw7qhS.png', NULL, NULL, '滝沢久美子', NULL, 130875, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023740', 'AN2054', '矢田野まける', '矢田野まけるは、翔子と競い合うのが好きな、競争心の強い女の子だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130871-g7EkLNAqyAbe.png', '1月3日', NULL, '前島亜美', NULL, 130871, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023741', 'AN2054', '古見将賀', '親族：古見結子（母）、古見定義（兄）、古見秀子（妻）、古見硝子（娘）、古見笑介（息子）、古見晶 （姪）　古見将賀は、ショウコとショウスケの父親である。ダンディな中年男性として描かれている。将賀はめったに口を開かず、言葉で自分の考えを表現するのに苦労することもあり、時には簡単に動揺してしまうこともある。  若々しい妻の態度とは対照的に、正義はしばしば成熟した、冷静沈着な姿を見せる。厳格な印象を与えることもあるが、実際には家族思いな一面も描かれている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130865-Ztgp75hdKhQ2.png', NULL, NULL, '星野充昭', NULL, 130865, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
