INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023743', 'AN2054', '鬼ヶ島朱子', '鬼ヶ島のあかこは、もともと山井レンの友人グループの一員だった。彼女の名前は「鬼ヶ島の赤い少女」という意味で、これは『桃太郎』の物語に由来している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158375-J4dfkOKW0Prf.png', '2月3日', NULL, 'ブリドカット・セーラ・恵美', NULL, 158375, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023744', 'AN2054', '井中のこ子', '井中のこ子は、田舎出身であることにコンプレックスを抱いている。その後、彼女は翔子と友達になった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130879-P5pabeiKSflK.png', NULL, NULL, '潘めぐみ', NULL, 130879, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023745', 'AN2054', '古見定義', '古見定義は、翔子の叔父であり、彼女の父の兄弟である。翔子は、彼と自分が父と同じように性格が似ているため、仲良くやれているのだと考えている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130873-i00gSJiQLq7q.png', NULL, NULL, NULL, NULL, 130873, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
