INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023756', 'AN2056', 'カゲ', '「カゲ」は、文字通り「影」であり、ボッジの最初の友達となる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b209533-bICkAMcaURRi.png', NULL, NULL, '村瀬歩', NULL, 209533, 'MAIN', 1334) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023757', 'AN2056', 'ボッジ', 'ボッス王国の長男である王子。ボッジは、生まれつき異常に小柄で虚弱、そして耳が聞こえない。彼は、伝説の王である父・ボッスの影の下で生きてきた、力なき王子である。 父の後を継いで、世界一の王になりたいと願っている。ボッジは極めて勤勉で誠実であり、その人柄ゆえに、たとえ彼のことを常に理解できなくても、人々は彼に惹きつけられる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209532-s7ciwKqKrIw7.png', NULL, NULL, '日向未南', NULL, 209532, 'MAIN', 4286) ON CONFLICT DO NOTHING;
