INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023765', 'AN2056', '狩人', 'ボッス王国と冥界の間に広がる森に住む、名もなき王。ボッジは森で道に迷った際、この王と一瞬だけ遭遇した。（出典：王様ランキング Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b310015-dYA79bmbb4rs.jpg', NULL, NULL, '大畑伸太郎', NULL, 310015, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
