INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023770', 'AN2056', 'ゲスラン', 'ゲスランは、ボー王国の貴族であり、シャドウ一族に対する政治的な動機による大量虐殺に加担した人物である。（出典：王様ランキング Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b324990-3LHxpS237ILM.png', NULL, NULL, '最上嗣生', NULL, 324990, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
