INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023795', 'AN2057', 'ディア', 'ある外国出身の貴婦人。彼女は世界でも屈指の強さを誇る魔法使いの一人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157691-TY88sUXtm1Br.png', NULL, NULL, '上田麗奈', NULL, 157691, 'MAIN', 995) ON CONFLICT DO NOTHING;
