INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023812', 'AN2058', 'フレデリカ・ローゼンフォルト', 'シンとそのチームが、連邦から保護を受けた後、エルンストの邸宅で出会った少女。彼女は「スピアヘッド飛行隊」のマスコットとして配属されている。10歳という幼い年齢とは思えないほど、知性と話し方が大人びている。', 10, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161718-kWIdyUGRk0wj.png', '2月7日', NULL, '久野美咲', 130, 161718, 'MAIN', 820) ON CONFLICT DO NOTHING;
