INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023822', 'AN2058', 'シデン・イーダ', 'シデン・イーダは、「女王の騎士団」としても知られるブリシンガメン戦隊の隊長であり、レギオンによる大規模な攻勢の際、共和国の防衛を率いた部隊の指揮を執った。彼女の通称「サイクロプス」は、左右の瞳の色が異なる（異色眼）ことから、機能している目が片方しかないように見えることに由来している。  連邦による共和国の救出後、彼女の中隊は第86ストライク・パッケージへの参加を志願した。現在、シデンとブリシンガメン中隊は、動員部隊の防衛を担当している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239614-IGrxEPbt7MoR.jpg', NULL, NULL, '泊明日菜', NULL, 239614, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023823', 'AN2058', 'キリヤ・ノウゼン', '彼は、アウグスタ・フレデリカ・アデル＝アドラーの専属の騎士であり、世話役でもあった。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258614-wL72SzRX4nGp.png', NULL, NULL, '上村祐翔', NULL, 258614, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
