INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023825', 'AN2058', 'ザファル・イディナローク', 'ザファルは、ロア・グラシア連合王国の皇太子であり、ヴィカの兄である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265564-XCvFioFcuQNE.png', NULL, NULL, '水中雅章', NULL, 265564, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023826', 'AN2059', '運命', 'L.V. ベートーヴェン「交響曲第5番 ハ短調 作品67」　彼女は、その体内に「運命」を宿すミュージックアートである。淑女のような外見とは裏腹に、表情はほとんど変わらず、口調は常に穏やかで礼儀正しい。 一見すると可愛らしいが、口は鋭く、甘いものが大好きな、型破りな性格の持ち主だ。彼女とパートナーである指揮者のタクトとは、深く長い過去を共有している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215188-U9LE5bw90V7S.png', NULL, NULL, '若山詩音', NULL, 215188, 'MAIN', 1995) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023827', 'AN2059', '朝雛タクト', 'ミュージックアート「運命」と契約を結んだ指揮者。「何よりも音楽を最優先する」という信念を持っている。（出典：公式サイト、翻訳） 父親は、ボストンでの悲劇的な事件で亡くなった著名な指揮者、朝雛ケンジである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234535-jZd0cPwruwkJ.jpg', NULL, NULL, '内山昂輝', NULL, 234535, 'MAIN', 942) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023828', 'AN2059', 'アンナ・シュナイダー', 'タクトの幼なじみであり、運命的な「姉妹」でもある少女。明るく思いやりのある性格の持ち主である。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246856-YUIZhVRuEfXp.jpg', NULL, NULL, '本渡楓', NULL, 246856, 'MAIN', 399) ON CONFLICT DO NOTHING;
