INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023853', 'AN2060', '四谷みこ', '家族：四谷真守（父）、四谷透子（母）、四谷恭介（弟）　ミコには、普通の人には見えない恐ろしい超自然的なものが見える能力があるが、トラブルを避けるために、見えないふりをしている。 彼女の「霊感」は視覚を圧倒してしまう。まるでガラスの反射が強すぎて、その向こう側が見えなくなるようなものだ。霊と対峙する際、彼女は平静を装おうとするが、内心では恐怖に震えている。また、彼女は……', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139631-JC76pYY2Q51Z.png', '10月17日', NULL, '雨宮天', 160, 139631, 'MAIN', 2580) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023854', 'AN2060', '二暮堂ユリア', '霊が見えるという能力を持っていることから、自分は少し特別な存在だと信じている、霊媒師志望の少女。しかし、彼女には「下級の霊」しか見えないという事実を知らず、目に見えない大きな危険から自分を守ろうとするミコの行動を、悪意のある行為だと誤解してしまう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156860-P5bAY1m97tX7.png', '4月3日', NULL, '佐倉綾音', 140, 156860, 'MAIN', 323) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023855', 'AN2060', '百合川ハナ', 'ミコの親友。彼女は、友人を苦しめている超自然的な恐怖について全く気づいていないが、その並外れた生命力のせいで、知らず知らずのうちに多くの恐怖を引き寄せてしまっている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139632-b95rh3VplAYY.png', '7月8日', NULL, '本渡楓', 156, 139632, 'MAIN', 424) ON CONFLICT DO NOTHING;
