INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023876', 'AN2060', '四谷恭介', 'ミコの弟。 恭介は、黒髪の短い少年だ。彼はミコをとても大切に思っており、警戒すべき彼氏がミコにいるのではないかとさえ思い込むほどだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199026-pdiaoi3idV9F.png', NULL, NULL, '花守ゆみり', NULL, 199026, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
