INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023889', 'AN2061', '花籠咲', 'サキはミライの同級生であり、彼が想いを寄せる相手であり、偶然にも「神」の候補者でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/89974-8jid4hCdl92v.jpg', NULL, NULL, '市道真央', NULL, 89974, 'MAIN', 223) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023890', 'AN2061', '架橋明日', '家族が交通事故で亡くなった後、彼は虐待的な叔父と叔母に育てられた。受けた虐待の末、彼は高層ビルから身を投げて自殺を図ったが、ナッセに救われた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89231-ohzYpY5dOXZw.jpg', NULL, NULL, '入野自由', NULL, 89231, 'MAIN', 225) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023891', 'AN2061', 'ナッセ', 'ナッセはミライの命の恩人であり、その立場から、ミライがこれまで経験してきたこと、彼に関わるあらゆることを知っています。特に、里親として引き取られて以来、叔母と叔父から精神的虐待を受けてきたという事実については、よく把握しています。  彼女は、ビルから飛び降りようとしたミライの命を救い、自由と愛を与えることで、彼に幸せになる可能性をもたらした。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/89232-PvyFC7R21rZo.jpg', NULL, NULL, '小倉唯', NULL, 89232, 'MAIN', 341) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023892', 'AN2061', 'ルベル', 'サキの天使。彼はかなり計算高く、人を操る傾向があり、ナッセは、その性格こそが彼が二級天使に格下げされ、サキに赤い矢しか授けることができない理由だと考えている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/89973-0osNLAv99nk3.jpg', NULL, NULL, '花江夏樹', NULL, 89973, 'MAIN', 116) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023893', 'AN2061', '底谷 一', '生まれつき不細工だったソコタニは、母親が自殺し、バルタが現れて彼の守護天使となるまで、常に周囲から疎まれていた。バルタの力を使って、ソコタニは金を手に入れ、整形手術で美しい顔を手に入れたが、コミュニケーション能力の低さゆえに、依然として女の子の心を掴むことはできなかった。 彼はカナデに執着し、その部下になることを申し出る。カナデはそれを受け入れるが、その代償として別の「神候補」を捕らえることを条件とした。（出典：ウィキペディア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169620-aXdIgqld1XYh.jpg', NULL, NULL, '前野智昭', NULL, 169620, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023894', 'AN2061', '明日の叔父', '架橋明日の虐待的な叔父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172063-JpeylbbNuVJz.png', NULL, NULL, '落合福嗣', NULL, 172063, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023895', 'AN2061', '小日向冬子', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b259424-oWExZrfTLTLy.jpg', NULL, NULL, '田澤茉純', NULL, 259424, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023896', 'AN2061', 'オガロ', 'オガロは第一級の天使であり、「闇の天使」である。彼女は十三天使の一人であり、中海修滋を神の候補者として選んだ。（出典：プラチナ・ウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169624-ayFPGeytLYMH.png', NULL, NULL, '朴璐美', NULL, 169624, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023897', 'AN2061', 'バルタ', 'バルタは第一級の天使であり、「直感の天使」である。彼は十三天使の一人であり、底谷一を神の候補者として選んだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169627-CzN2gBcezM80.jpg', NULL, NULL, '緑川光', NULL, 169627, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023898', 'AN2061', '幕松竜二', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b259425-AlrU8X3IfX3i.jpg', NULL, NULL, 'ボルケーノ太田', NULL, 259425, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023899', 'AN2061', 'ヤゼリ', 'ヤゼリは第二級の天使である。彼は「十三の天使」の一人であり、手毬由理を自身の「神候補」として選んだ。出典：プラチナエンド Wiki', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b172072-ZfDT9thSH6mB.jpg', NULL, NULL, '竹内良太', NULL, 172072, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023900', 'AN2061', '山田美々々', '数名の中学生の女子を殺害した容疑で逮捕されたアマチュアモデル。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172061-SrZ1LjbnV8LD.png', NULL, NULL, '前田佳織里', NULL, 172061, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
