INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023902', 'AN2061', 'ム二', 'ムニは特別ランクの天使であり、「破壊の天使」である。彼は13人の天使の一人であり、米田を「神の候補者」として選んだ。（出典：プラチナエンド Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169629-vXEBTXIYBZCP.png', NULL, NULL, '平野文', NULL, 169629, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
