INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023904', 'AN2061', '結糸向', '結糸向は、天使ペネマによって神の候補者に選ばれた人間である。当初、彼はドナルド・トランプに似たジョーク用のマスクを使って正体を隠していた。    （出典：プラチナエンド Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169621-5cOoYwET0ldi.jpg', NULL, NULL, '潘めぐみ', NULL, 169621, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023905', 'AN2061', '手毬由理', '手毬由理は、天使ヤゼリによって神の候補者に選ばれた人間である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169625-N48dlxeMCSuy.jpg', NULL, NULL, '大西沙織', NULL, 169625, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023906', 'AN2061', 'バレ', 'バレは第一級の天使であり、「知識の天使」である。彼女は十三天使の一人であり、六階堂七斗を神の候補者として選んだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169628-dSLrPf7E9EIG.jpg', NULL, NULL, '茅野愛衣', NULL, 169628, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023907', 'AN2061', '明日の叔母', '架橋明日の虐待的な叔母。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172069-4SnuoA8yMOPj.png', NULL, NULL, '小林ゆう', NULL, 172069, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023908', 'AN2061', '田淵 三郎', '田淵三郎は、天使のエグラによって「神の候補者」に選ばれた人間である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172065-PKMpnsJRmPFg.png', NULL, NULL, '吉野裕行', NULL, 172065, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023909', 'AN2061', '弓木愛美', '彼女はエージェントであり、星雅矢のパートナーでもあり、未来たちが残りの神候補者全員を集めるのを手伝っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260803-iTsYEdAWGsGn.png', NULL, NULL, '石川由依', NULL, 260803, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023910', 'AN2061', '中海修滋', '中海修滋は、天使オガロによって神の候補者に選ばれた人間である。（出典：プラチナエンド Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169623-0LifBjL8GuPy.jpg', NULL, NULL, '山下大輝', NULL, 169623, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023911', 'AN2061', '六階堂七斗', 'アパレル会社の商品企画担当として働く「神候補」。彼は末期がんと闘っており、まず赤い矢を使って、自分が亡くなった後に家族が生活できるだけの資金を確保し、次に私立探偵を雇って、さらに多くの「神候補」を見つけ出そうとしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169579-L2GUkb1selio.jpg', NULL, NULL, '森川智之', NULL, 169579, 'SUPPORTING', 135) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023912', 'AN2061', '老いた神', '神とは、天国の天使たちよりも上位に立つ存在である。出典：プラチナエンド Wiki', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b172073-ByjqBZgDPfu4.png', NULL, NULL, '屋良有作', NULL, 172073, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023913', 'AN2061', '中矢間知代', '中矢間知代は、天使ジャミによって「神の候補者」に選ばれた人間である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172070-9NSZaZlk7kaY.png', NULL, NULL, '杉浦しおり', NULL, 172070, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
