INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023915', 'AN2061', '米田我工', '米田我工は、天使ム二によって「神候補」に選ばれた人間である。彼は、このシリーズで最後に明らかになった神候補である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169622-jjCVXDJrtAe0.jpg', NULL, NULL, '津田健次郎', NULL, 169622, 'SUPPORTING', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023916', 'AN2061', '生流奏', 'このシリーズの主な敵役であり、他の候補者を全員殺すことさえ厭わず、あらゆる手段を講じて神になろうとしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122073-ux6dtoTDK2n3.jpg', NULL, NULL, '石川界人', NULL, 122073, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023917', 'AN2061', 'ロドリゲス 頓馬', 'ロドリゲス・トンマは、天使ルタによって「神候補」に選ばれた人間である。  トンマは非常に利己的な人物であり、神候補として新たに手に入れた力を平然と使い、女性たちに自分を好きになるよう強要することにも何の躊躇いもない。また、彼は非常に自惚れが強く、テレビのインタビューで「すでに神のような気分だ」と厚かましく語っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169630-kF3j2PzC17ke.png', NULL, NULL, '杉田智和', NULL, 169630, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023918', 'AN2061', '畠山省吾', '畠山省吾は、天使エマカによって「神の候補者」に選ばれた人間である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172062-UDfgW1iV7JTh.png', NULL, NULL, '平川大輔', NULL, 172062, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023919', 'AN2061', '六階堂あや', 'ナナトの妊娠中の妻。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b261505-4eoYGC4bmZkA.png', NULL, NULL, '田中理恵', NULL, 261505, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023920', 'AN2061', 'ぺネマ', 'ペネマは第一級の天使であり、「遊びの天使」である。彼は十三天使の一人であり、結糸向を神の候補者として選んだ。出典：プラチナエンド Wiki', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b172071-rWxtjvL0dhz0.png', NULL, NULL, 'KENN', NULL, 172071, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023921', 'AN2061', 'メイザ', 'メイザは特別ランクの天使であり、「貪欲の天使」である。彼女は十三天使の一人であり、生流奏（通称：メトロポリマン）を自身の神候補として選んだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169626-nSxIIS8H7twh.png', NULL, NULL, '井上喜久子', NULL, 169626, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023922', 'AN2061', 'ルタ', 'ルタは第二級の天使である。彼は十三天使の一人であり、ロドリゲス・トンマを神の候補者として選んだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172067-3eXBtkOAt045.png', NULL, NULL, '子安武人', NULL, 172067, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023923', 'AN2061', 'ジャミ', 'ジャミは第二級の天使である。彼は「十三の天使」の一人であり、中矢間知代を自身の「神候補」に選んだ。出典：プラチナエンド Wiki', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b172068-4aN2YQkfohlx.png', NULL, NULL, '芳野由奈', NULL, 172068, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023924', 'AN2061', '六階堂菜々香', 'ナナトの幼い娘。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b261506-MvTg3mEjLON9.png', NULL, NULL, '羊宮妃那', NULL, 261506, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023925', 'AN2061', '中海啓一', NULL, 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b320192-2EIgPupdtFFv.png', NULL, NULL, '小林大紀', NULL, 320192, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023926', 'AN2062', 'モーエン', 'モーエンはアデミの父親であり、町の警備隊長である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316348-nFp3s1hD1zBg.jpg', NULL, NULL, '成澤卓', NULL, 316348, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023927', 'AN2062', 'アレス・スロア', '主人公のパーティーの一員であるアレスは、「リーダー」の印を授かっている。その知性と魔法の才能により、魔術師として卓越した能力を発揮する一方で、彼は傲慢で、並外れて野心家でもある。彼はギデオンをパーティーから追い出し、周囲には「彼が自らの意思で去った」と説明した。  （出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196216-9U1VMfe5lWaC.png', NULL, NULL, '八代拓', NULL, 196216, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023928', 'AN2062', 'ミド', 'ナオの夫であり、タンタの父親であるミドは、ハーフエルフではなく人間だ。彼は冒険の道を捨て、大工の仕事に専念している。ゴンゾほど熟練した職人ではないが、計算が得意で、サポート役として活躍している。 ゴンゾでさえ、ミドがいないところでは彼を称賛することもある。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226690-HJGnhs1FbJ50.png', NULL, NULL, '三品健', NULL, 226690, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023929', 'AN2062', 'ストームサンダー', '「ストーム」は単なるあだ名に過ぎないが、ゾルタンのダウンタウンにある家具店を経営するハーフオークの職人だ。彼は概してレッドと仲が良い。腕は確かな職人だが、物腰や態度は荒々しい。しかし、実際に金を払ってくれる客相手になると、たちまち卓越したセールスマンへと変貌する。  （出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206864-kbGvBAMViXmF.png', NULL, NULL, '上田燿司', NULL, 206864, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023930', 'AN2062', 'Byuui', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314080-BlPnEWx6SkqI.jpg', NULL, NULL, '興津和幸', NULL, 314080, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023931', 'AN2062', 'ニューマン', 'ニューマンのゾルタンにある診療所の医師は、「迅速調剤」の印に恵まれており、どんな薬でもわずか1時間で調剤することができる。レッドと共にタンタの「白目病」を診断して以来、彼はレッドを信頼するようになった。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206861-w24H7HTe9JQh.png', NULL, NULL, '魚建', NULL, 206861, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023932', 'AN2062', 'シサンダン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314081-n8GLKr7wypNP.jpg', NULL, NULL, '興津和幸', NULL, 314081, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023933', 'AN2062', 'ディル', '「火の魔術師」の印を授かった男、ディルはかつて、人々を拉致していたオウルベアを倒す手助けを求めていたアルベールに、助言を与えたことがある。 ギデオンとリットは覚えていないが、かつてロッガーヴィアでの魔王軍との戦いで、彼と出会ったことがある。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b240580-S69kHNFdJXJZ.png', NULL, NULL, '利根健太朗', NULL, 240580, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023934', 'AN2062', '女の子', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260900-wulkt1ydzjOt.png', NULL, NULL, '白石れい', NULL, 260900, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023935', 'AN2062', 'Ugeugesan', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b314085-cURKlN4hrv9K.png', NULL, NULL, NULL, NULL, 314085, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023936', 'AN2063', '武田晴海', '武田春美は、『先輩がうざい後輩の話』の主人公の一人です。彼は、自分を「うざい」と思っている会社の後輩社員の先輩です。頼りになる人物ですが、少し鈍感なところがあります。  武田は、黒髪の短髪で、大柄でがっしりとした体格の男性だ。同僚を喜んで助ける、気さくな人物である。彼は五十嵐の担当として、常に彼女を支え、助けるために最善を尽くし、彼女のミスについては上司に謝罪することさえ厭わない。彼は彼女を気にかけている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131620-QlKhkQzaIisw.png', '3月9日', NULL, '武内駿輔', NULL, 131620, 'MAIN', 372) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023937', 'AN2063', '五十嵐双葉', '五十嵐は、比較的ほっそりとした体型の小柄な若い女性で、よく子供と間違えられる。そのため、子供のように扱われることがあり、それが彼女を苛立たせている。普段は肩までの長さの緑色の髪をポニーテールに結んでおり、森のような緑色の瞳をしている。オフィスではスーツ姿を見かけることが多い。  先輩の武田と出会った瞬間から、彼女は彼の言動のすべてに次第に苛立ちを覚えるようになった。武田は、その言葉遣いや笑い声、体格、そして彼女をポンポンと叩く仕草などで、常に彼女を苛立たせている。', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131618-828IMDr1fgbP.png', '3月9日', NULL, '楠木ともり', NULL, 131618, 'MAIN', 777) ON CONFLICT DO NOTHING;
