INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023939', 'AN2063', '大石', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248686-DDJkK8tl9DsR.png', NULL, NULL, '小田柿悠太', NULL, 248686, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023940', 'AN2063', '風間蒼汰', '風間聡太は、『先輩がうざい後輩の話』に登場する脇役の一人である。彼は、五十嵐双葉の勤める会社の先輩である。風間は、黒のショートヘアの若者で、白いボタンダウンシャツに黒の作業ズボンを合わせ、時折青いネクタイを締めている姿が見られる。 風間は退屈な性格で、見た目も地味であり、友人はあまりいないようだ。彼は正月を一人で過ごし、ビデオゲームをするのが好きだ。また、折り紙作りが趣味である。耳が敏感だ。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131621-93Jca5HnFFUn.png', NULL, NULL, '土田玲央', NULL, 131621, 'SUPPORTING', 508) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023941', 'AN2063', '土方', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248687-yc5S6X6s5BOG.png', NULL, NULL, '近藤孝行', NULL, 248687, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023942', 'AN2063', '桜井桃子', '桜井トコは、『先輩がうざい後輩の話』に登場する脇役の一人です。桜井は、長い黒髪をした若い女性です。右目の下にほくろがあります。  彼女は五十嵐双葉の勤める会社の先輩であり、その容姿と親しみやすい人柄から、男性社員の間で非常に人気がある。五十嵐と同じ部署で働いており、風間聡太に密かに想いを寄せている。', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131619-pOu8tYzf1WXl.png', '4月1日', 'O', '早見沙織', NULL, 131619, 'SUPPORTING', 825) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023943', 'AN2063', '黒部夏美', '黒部夏美は、中学時代からの五十嵐双葉の幼なじみだ。彼女は友達のことを心から気にかけているが、いたずらをするのが好きだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131622-E91m99j1bdjO.png', NULL, NULL, '青山玲菜', NULL, 131622, 'SUPPORTING', 614) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023944', 'AN2063', '桜井優人', '桜井優人は、桜井桃子の弟である。彼は高校への入学を機に、姉の住む町へ引っ越した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244077-cxNydFqHfuOv.png', NULL, NULL, '堀江由衣', NULL, 244077, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023945', 'AN2063', '月城モナ', '月城は独特の存在感と話し方を持っている。オフィスに恋愛雑誌を持ち込んだり、紙で指を切った際に五十嵐の指を舐めて治そうとしたりするなど、彼女の行動や振る舞いはかなり奇妙だ。人への挨拶の際、よくロシア語のフレーズを使う。（出典：『私の先輩はウザい』Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244078-UQVluI4dPyE1.png', '10月10日', 'AB', '古賀葵', 160, 244078, 'SUPPORTING', 225) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023946', 'AN2063', 'おじいちゃん', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248684-nsbXYQ6RGEPj.png', NULL, NULL, '大塚明夫', NULL, 248684, 'SUPPORTING', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023947', 'AN2064', 'ウィリアム・G・マリーブラッド', '彼は「死者の都」出身の孤独な人間であり、前世の漠然とした記憶を持って生まれ、成人するまでアンデッドの一団に育てられた。その後、グレイスフィールに誓いを立て、守護神の信仰を回復させつつ、冒険と文明を求めて都を後にした。  彼は幼少の頃、ハイキングに掛けられた封印を解くための生贄として、悪魔たちによって「死者の都」へ連れてこられた。しかし、あるアンデッドの一団に可愛がられ、引き取られた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129745-gmUvsvhY0FPw.jpg', NULL, NULL, '河瀬茉希', NULL, 129745, 'MAIN', 306) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023948', 'AN2064', 'ロビィナ・グッドフェロー', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255117-8P52MjHVQs94.png', NULL, NULL, '鈴木絵理', NULL, 255117, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023949', 'AN2064', 'アンナ', '彼女は、ウィリアムを支援するためにバグリー司教から派遣された司祭であり、トーチポートの街で日常業務を統括する主要人物の一人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264180-cc3G0EM7PYLI.png', NULL, NULL, '渡部恵子', NULL, 264180, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023950', 'AN2064', 'ブラッド', '彼はかつて人間だった、巨体の骨格を持つ人型男性で、髪は赤く、目はウィロー・オ・ウィスプのような光を放っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129746-1OY3uvdjUw8b.jpg', NULL, NULL, '小西克幸', NULL, 129746, 'SUPPORTING', 127) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023951', 'AN2064', 'レイストフ', 'レイストフは、卓越した腕前の冒険者であり、ウィリアムの仲間でもあった。彼は冒険者としての活動を引退し、新婚の妻アンナと共に落ち着いて暮らすことを決めた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129748-JuAH7nb0FVUI.jpg', NULL, NULL, '乃村健次', NULL, 129748, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023952', 'AN2064', 'メネルドール', 'メネルドールは、ハーフエルフの追放者であり、ウィリアムの最も忠実な友人である。かつては冒険者であり、狩人でもあった。彼は人間とエルフの混血である。髪は銀色でポニーテールに結んでおり、瞳はヒスイのような色をしている。  メネルドールは、エルフが暮らすエリンの大森林、北方の草原で生まれた。エルフと人間の血が混ざっているため、彼は追放者となり、住民たちとは誰とも仲良くすることができなかった。その後、彼は家を出て、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129750-NZoJAvMMbxn0.png', NULL, NULL, '村瀬歩', NULL, 129750, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023953', 'AN2064', 'トム', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264177-Kb5cpvFviUli.png', NULL, NULL, '浜田賢二', NULL, 264177, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023954', 'AN2064', 'マリー', 'マリーは、女神マテルに深く信仰を捧げる信者であり、マテルから「マテルの娘」という称号を授けられた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129744-stW6jrN4Sdi9.jpg', NULL, NULL, '堀江由衣', NULL, 129744, 'SUPPORTING', 139) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023955', 'AN2064', 'ジョン', 'ジョンは、後にトーチ・ポートとなるビースト・ウッズにある村の一つに住んでいた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264178-MdQ4EnI9QSzW.png', NULL, NULL, '手塚ヒロミチ', NULL, 264178, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023956', 'AN2064', 'グレイスフィール', 'グレイスフィールは、炎と絶え間ない変化を司る神秘的な女神である。彼女はウィリアムの守護神である。彼女は長い黒髪と金色の瞳を持つ人型の女神だ。穏やかな顔立ちをしており、その際立った特徴を覆うフード付きのローブを身にまとっている。右手には、通常は長い柄のついたランタンを握っている。 彼女の現れ形では、温かな炎の姿をとる。グレイスフィールは炎と流動の女神である。彼女はユニオン時代、多くの信者を擁する名高い神であった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129753-E5mBHrKOTSfa.jpg', NULL, NULL, '悠木碧', NULL, 129753, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023957', 'AN2064', 'エセルバルド・レックス・サウスマーク', 'エテバルドはオーウェン王の弟である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264176-iCS8HSPD7fEU.png', NULL, NULL, '田丸篤志', NULL, 264176, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023958', 'AN2064', 'オーガスタス', 'オーガスタスは幽霊のような存在だ。彼はグレイスフィールドの使者のような存在となり、ハイキングの封印を守っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129747-FN0MVY3k6RAB.jpg', NULL, NULL, '飛田展男', NULL, 129747, 'SUPPORTING', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023959', 'AN2064', 'マープル', 'マープルはビースト・ウッズのある村の住人だった。悪魔が彼らの土地を荒らした際、多くの犠牲者の一人として命を落としたが、その後、亡霊となって戻り、メネルドールに別れを告げてその場を去った。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264179-eQG5zk9ZWhd9.png', NULL, NULL, '勝生真沙子', NULL, 264179, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023960', 'AN2064', 'スタグネイト', 'スタグネイトは、アンデッドと結びついた悪意の女神である。彼女はウィリアムの敵であり、彼に特別な関心を寄せる。敵同士であるにもかかわらず、彼の旅路を見守り、彼を助ける。   彼女はいたずら好きで狡猾だ。人間をこよなく愛し、他者の道しるべとなる英雄たちを永遠の存在にしたいと願っている。また、彼の最期の瞬間に自身の「エコー」がとった行動について、後悔と恥じらいを感じている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129751-ZPdLRP9BHajw.jpg', NULL, NULL, '高橋広樹', NULL, 129751, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023961', 'AN2064', 'バート・バグリー', '彼は、ホワイトセイルズの神殿を統括する首席司教である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264182-JbMIGyPCk1lC.png', NULL, NULL, '稲葉実', NULL, 264182, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023962', 'AN2064', 'アントニオ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255116-7sYlONCvCKQf.png', NULL, NULL, '遊佐浩二', NULL, 255116, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
