INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023964', 'AN2065', 'サリア', 'サリアはレベル700の獣人ゴリラだが、「進化の果実」の力を借りて進化すると女性となり、それ以降は人間の姿やゴリラの姿に自由に行き来できるようになるほか、部分的な変身も可能となる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237558-C4S93dEXWWoz.png', NULL, NULL, '花澤香菜', NULL, 237558, 'MAIN', 186) ON CONFLICT DO NOTHING;
