INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023983', 'AN2066', 'イリナ・ルミネスク', '種族：ヴァンパイア　彼女は人々から「呪われた種族」として扱われており、人間を憎んでいる。ある理由から、彼女は月へ行きたいという強い意志を持っており、宇宙飛行士になることを目指している。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213450-fvSqTC6XYe7i.png', '9月19日', NULL, '林原めぐみ', 158, 213450, 'MAIN', 706) ON CONFLICT DO NOTHING;
