INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023985', 'AN2066', 'ローザ・プレヴィツカヤ', 'ローザ・プレヴィツカヤは空軍中尉であり、唯一の女性宇宙飛行士候補生である。彼女はかつて「スングラードの白いバラ」として知られたエースパイロットだった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213449-BqnqpBwDrTNF.png', NULL, NULL, '小松未可子', NULL, 213449, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023986', 'AN2066', 'スラヴァ・コローヴィン', 'スラヴァ・コロヴィンは、共和国の宇宙船を設計する天才エンジニアである。彼の存在は一般には秘密にされており、人々は彼を「主任設計官」という肩書きでしか呼んでいない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239621-FhiqauMtxKk3.jpg', NULL, NULL, '土師孝也', NULL, 239621, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
