INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024000', 'AN2066', 'フョードル・ゲルギエフ', 'フョードル・ゲルギエフは、ジルニトラ共和国の最高指導者であり、前政権を打倒してこの地位に就いた。 彼は1960年9月、アルナク連合王国の「プロジェクト・ヘルメス」に対抗して、自国から初めての人類を宇宙へ送り出す計画である「プロジェクト・メクタ」を発表した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239622-yTEnjKRQgYMV.png', NULL, NULL, '緒方賢一', NULL, 239622, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024001', 'AN2067', '立花夕月', 'タマヒコの嫁。タマヒコの父親が20万円で買い取った。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139895-sJXsDrmmcAIV.jpg', '12月31日', NULL, '会沢紗弥', NULL, 139895, 'MAIN', 525) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024002', 'AN2067', '志磨珠彦', '明治38年、裕福な家庭に生まれた青年。 漫画の物語が始まる1年前、彼は自動車事故に遭い、その事故で母親を亡くし、右腕の機能を完全に失ってしまった。彼は千葉にある一族の屋敷を譲り受け、身の回りの世話をしてもらうために20万円で花嫁を買わされた。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139894-C4NPrBOP0tzq.jpg', '9月1日', NULL, '小林裕介', NULL, 139894, 'MAIN', 199) ON CONFLICT DO NOTHING;
