INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024014', 'AN2068', '仁礼光', '所属チーム：カゲウラ分隊　ランク：B　分隊内役職：オペレーター　仁礼光は、Bランク第2位の「カゲウラ分隊」のオペレーターである。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179776-jZMC9rXdlcqV.jpg', '7月27日', 'B', '小堀友里絵', NULL, 179776, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024015', 'AN2068', '弓場拓磨', 'ユバはユバ部隊（Bランク第8位）の隊長であり、風神の候補者11人のうちの1人である。彼は非常に熱血で威圧感があり、真面目な人物として映り、その実直な態度にはほとんど攻撃的とも言えるほどだ。 とはいえ、状況によってはその振る舞いが度を越していると見なされることもある。善意に駆られている時でさえ、彼の言葉遣いは粗野で、口調は荒々しい。遅刻には決して寛容ではない。戦闘では、ユバはその極めて素早い抜刀を活かし、それによって準備を整え、斬り……', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b251190-yuwHF4P2Cd2B.png', '4月30日', 'AB', '檜山修之', NULL, 251190, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024016', 'AN2068', '結束夏凛', 'カリンは不機嫌そうな女の子で、ジンが基地に来た時の様子からもそれがうかがえる。漫画では彼女の性格はあまり描かれていなかったが、アニメではジンにイライラしている様子が描かれていた。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179801-7WxOMyPPzNj2.jpg', NULL, NULL, '鎌田梢', NULL, 179801, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
