INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024019', 'AN2068', '烏丸京介', '烏丸京介は、A級エージェントであり、タマコマ支部の所属で、オサムとアイの指導役を務めている。彼は「チーム・タマコマ・ファースト」のメンバーでもある。 京介はキリエをからかうのが好きで、よく彼女を茶化す。また、キリエを混乱させるためだけに冗談を言うことも好む。一方で非常に責任感が強く、ジンが言うように「彼は神のような先生」である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179747-kqpsP5eccGt5.jpg', '5月9日', NULL, '福山潤', NULL, 179747, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
