INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024021', 'AN2068', '小荒井登', 'Bランクのエージェントであり、アズマ班の襲撃者。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179753-88gqeyNKZn80.jpg', '4月24日', NULL, '浅利遼太', NULL, 179753, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024022', 'AN2068', '東春秋', '東春秋はボーダー初のスナイパーであり、現在はBランク（元Aランク）で、数世代にわたる「アズマ部隊」のリーダーを務めている。東は非常に冷静沈着な人物である。 極限の戦闘状況下では感情を露わにすることもあるが、常に冷静さと分析力を失うことはなく、その姿勢が多くのボーダーエージェントからの信頼と尊敬を勝ち得ている。彼は組織内の数名のメンバーを指導してきたが、その中には、彼を「感情を露わにできない人物」という一般的なイメージよりも、はるかに狡猾な人物だと見抜いている者もいる。', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212010-NG3Zhzq1RKCM.png', '1月3日', 'A', '浜田賢二', NULL, 212010, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
