INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024029', 'AN2068', '影浦雅人', '種族：人間　所属：ボーダー　チーム：影浦小隊　階級：B　小隊内役割：アタッカー　ソロランク：20　副作用：感情感知　トリガータイプ：白　影浦雅人は、Bクラス第2小隊「影浦小隊」のリーダーである。 影浦は、乱れた黒髪と細長い瞳孔を持つ若い男性である。顎まで覆う防塵マスク、濃い色のセーター、ジーンズを身に着けている。   影浦は極めて好戦的であり、陰で自分の悪口を言ったとして、2人の訓練生を斬首したことがある。  （出典：World Trigger Wikia）', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179744-BqN3pk3YKEm5.jpg', '6月4日', NULL, '杉田智和', NULL, 179744, 'SUPPORTING', 71) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024030', 'AN2068', '絵馬ユズル', '絵馬ユズルは、Bランク（元Aランク）のスナイパーであり、カゲウラ部隊のメンバーである。彼は、中学生のエージェントの中で最高得点を誇る、並外れた才能を持つスナイパーだ。彼は雨取千佳に猛烈に片思いをしている。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236718-7MEhk1RFhhhY.png', '12月9日', NULL, '三瓶由布子', NULL, 236718, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024031', 'AN2068', '穂刈篤', 'Bランクの狙撃手で、アラフネ小隊の隊員。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179739-ijGMTA7SurqR.jpg', '6月15日', NULL, '泰勇気', NULL, 179739, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024032', 'AN2068', '二宮匡貴', '二宮は射撃の腕前が第1位、総合戦闘能力が第2位であり、Bランク第1小隊「二宮小隊」の隊長を務めている。二宮は、かつてのチームメイトに対しても誰に対しても極めて率直に接するため、厳しい人物という印象を与える。 戦闘においては鋭い洞察力を持ち、多少の競争心も持っている。一見傲慢に見えるが、二宮は自分より劣っていると判断した相手に対しても、礼儀正しく助けを求めることを厭わない。彼の射撃技術や戦闘能力の高さは、以下の事実からも裏付けられている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179775-ZL33jvZI2TWI.png', '10月27日', NULL, '諏訪部順一', NULL, 179775, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024033', 'AN2068', '日浦茜', 'Bランクのエージェントであり、那須小隊の狙撃手。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b179737-uMg1K3d2JWEe.jpg', '7月7日', NULL, '一木千洋', NULL, 179737, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024034', 'AN2068', '北添尋', '種族：人間　所属：ボーダー　チーム：影浦小隊　階級：B　小隊内での役割：砲手　トリガータイプ：ホワイト　北添尋は影浦小隊の隊員である。北添は感情豊かな少年で、泣き出したりパニックに陥ったりしやすい性格であることが描かれている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179751-PUqF36qdmqGG.jpg', '4月15日', NULL, '武虎 ', NULL, 179751, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024035', 'AN2068', '生駒達人', '生駒は、Bランク第4位の「生駒部隊」のキャプテンであり、第6アタッカーを務める。非常に風変わりな性格で、他の人ならどうでもいいと思うような細部にこだわる傾向があり、チームメイトさえも驚かせることがある。 感情を表に出すことはめったにないが、ありふれた出来事にも大いに興奮し、それを無意味な逸話として語るのが好きだ。この興奮ぶりは、彼ののんびりとした態度と相まって、おっちょこちょい、あるいは完全に変わり者に見えることもある。彼は結果には気を配っているが、', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b251191-GaZ0waqsLbT7.png', '4月29日', 'B', '小西克幸', NULL, 251191, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024036', 'AN2069', 'メメンプー', 'サクガンは、夢の中で約束されたそびえ立つ建造物を見つけるために、マーカーになりたいと願う小さな女の子です。彼女は天才で、すでに大学を卒業しています。父親がこの夢を応援すると約束した後、二人は住み慣れた家から遠く離れた地へと旅立ちました。', 9, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161089-8Vci0JqoisL5.jpg', NULL, NULL, '天希かのん', NULL, 161089, 'MAIN', 65) ON CONFLICT DO NOTHING;
