INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024049', 'AN2069', 'ボス', '各コロニーの中心にある管制塔を襲撃する、謎の武装集団「シビト」のリーダー', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231987-gVpWa4nB5LQp.jpg', NULL, NULL, '小山剛志', NULL, 231987, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024050', 'AN2069', 'Sina', '彼女はドリーム・コロニーのコロニー・プリンセスを務めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b271516-o2qx45c0D516.png', NULL, NULL, '早見沙織', NULL, 271516, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024051', 'AN2070', '店主', '商店街の一角にある多テナントビルの地下にある老舗レストラン「西洋料理店 ネコヤ」のオーナー。10年前に父親からこの店を引き継いだ。西洋料理だけでなく、和食、中華料理、さらにはデザートなど、幅広い料理の腕に長けている。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122675-aCl4HDFlxs5T.png', NULL, NULL, '諏訪部順一', NULL, 122675, 'MAIN', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024052', 'AN2070', 'アレッタ', '失業中で運に見放されていた若い魔女が、西洋料理店「ネコヤ」に惹かれ、そこで雇われることになった。ネコヤで出会った人々を通じて、自分の世界での仕事のヒントも得ることができた。休憩時間には、店主の料理を食べるのをいつも楽しみにしている。  （出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122699-19cQiVMM3KVb.png', NULL, NULL, '上坂すみれ', NULL, 122699, 'MAIN', 163) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024053', 'AN2070', 'クロ', 'アレッタと同じく、西洋料理店「ネコヤ」で働く黒竜のアバター。店に来る際はエルフの少女の姿となり、テレパシーの力を使って他者と会話する。チキンカレーに少しばかり執着している。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122700-19bFe9RFuTVH.png', NULL, NULL, '大西沙織', NULL, 122700, 'MAIN', 187) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024054', 'AN2070', 'ヴィクトリア・サマナーク', '公爵の姉であり、才気あふれるソーサラーである。両親はともに人間だったが、彼女はハーフエルフとして生まれ、ソーサラーの道を歩むことを選んだ。好物はプディング・ア・ラ・モードだ。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123174-1rLVm1N6e4oC.png', NULL, NULL, '田村ゆかり', NULL, 123174, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024055', 'AN2070', 'ジュリエッタ', 'ある領主の娘であり、ロメロの恋人。ロメロと一生を共に過ごすため、彼女は光の世界に別れを告げた。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255037-vFpJHON8Fb0Y.png', NULL, NULL, '富田美憂', NULL, 255037, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024056', 'AN2070', 'ルシア', '「赤の主」に仕える巫女。彼女はラミアであり、上半身は女性、下半身は蛇という姿をしている。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255045-vO5AVm79Sg0w.png', NULL, NULL, '久川綾', NULL, 255045, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024057', 'AN2070', 'カミラ', '公国の港町の岬に住む「魔女」。彼女はフルーツゼリーの研究を行い、人間たちにその作り方を教えている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258772-7cltJYrunDN9.png', NULL, NULL, '小清水亜美', NULL, 258772, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024058', 'AN2070', 'エドモン', '王国の大臣。鋭い観察眼を持ち、諜報活動に長けており、王でさえ彼を深く信頼している。彼は帝国と「砂の国」の情勢を注視し続けている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259980-NpJQLRljfYo7.png', NULL, NULL, '家中宏', NULL, 259980, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024059', 'AN2070', 'アーデルハイド', '帝国の第一王女。宮殿の別邸で療養中、ネコヤに定期的に通うようになり、徐々に回復していった。好物はチョコレートパフェだ。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123177-uvJ43uVVwUvV.png', NULL, NULL, '上田麗奈', NULL, 123177, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024060', 'AN2070', 'ジャック', '帝国の辺境の田舎に住む少年。よくテリーやケントとパンク・トリオを結成して一緒に過ごしている。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255038-isrld3owpxMQ.png', NULL, NULL, '吉永拓斗', NULL, 255038, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024061', 'AN2070', 'エミリオ', '強くなるために故郷を離れ、旅の途中でルシアと出会った放浪者。自分の容姿にかなりコンプレックスを抱いている。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255046-mJye2N1wpHyg.png', NULL, NULL, '天崎滉平', NULL, 255046, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024062', 'AN2070', 'イルゼガント', '外の世界から遥か遠く離れた空に浮かぶ「パラダイス」という島に住むエルフ。彼は長年にわたり魔法の研究を続けてきたが、次第にそれに飽きてきている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258774-qJDZyOliZm5v.png', NULL, NULL, '渡辺明乃', NULL, 258774, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024063', 'AN2070', 'ヨミ', 'アルトリウスと並び、魔族との戦いに終止符を打った偉大な英雄の一人。魔神を討ち取った代償として、彼女は異世界へと放り出された。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259979-ChvISDx7zIAh.png', NULL, NULL, '井上喜久子', NULL, 259979, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024064', 'AN2070', 'シャリーフ', '「砂の国」でアイスコーヒーを流行させた王子。「愛しき乙女」アーデルハイドに心を奪われている。好物はコーヒーフロートだ。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123339-pAzdj7gNedlc.png', NULL, NULL, '田丸篤志', NULL, 123339, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024065', 'AN2070', 'ケント', 'パンク・トリオのメンバー。魔術師の息子であるため、魔法の知識を持っている。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255039-OwHazKfg2b0e.png', NULL, NULL, '山本颯侍', NULL, 255039, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024066', 'AN2070', 'トーマス', 'その王国出身の元トレジャーハンター。引退後は、トレジャーハンティングで培った経験を活かし、調査を専門とする冒険者として活動している。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255047-i7LSZKptM7iP.png', NULL, NULL, '木村良平', NULL, 255047, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024067', 'AN2070', 'ドウシュン', '「海の国」出身の占い師。宮廷に仕えているため、貴族や商人との人脈が広い。隣国の出身であるソウエモンとは、常に対立している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258769-SljSVVeCGOZw.png', NULL, NULL, '平川大輔', NULL, 258769, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024068', 'AN2070', 'タツゴロウ', 'その武勇伝が吟遊詩人によって世界中で歌い継がれてきた伝説の剣士。アルトリウスとは親友である。好物はテリヤキチキン。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122705-UwmWaO21YTPA.png', NULL, NULL, '大塚芳忠', NULL, 122705, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024069', 'AN2070', 'ラナー', '砂の国の王女。異母兄のシャリーフの前では、男っぽい口調で話す。好物はソーダフロート。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123340-8f1Iscnyv0JB.png', NULL, NULL, '下地紫野', NULL, 123340, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024070', 'AN2070', 'テリー', 'パンク・トリオのメンバー。市長の三男で、他の2人の息子より1歳年上である。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255040-N9mGWIPr3w0N.png', NULL, NULL, '土田玲央', NULL, 255040, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024071', 'AN2070', 'アリス', '公国の一角にあるハーフエルフの村に住んでいる。森で迷子になったとき、ファルダニアに助けられた。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255048-9cgJ3Qm9elxa.png', NULL, NULL, '戸田めぐみ', NULL, 255048, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024072', 'AN2070', 'アリシア', 'ヒルダやラニージャの知人である悪魔の傭兵。熊のような太い上腕と、並外れてがっしりとした体格から、「フェムベア」というあだ名で呼ばれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258773-zQFLHpRDEaCm.png', NULL, NULL, '國立幸', NULL, 258773, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024073', 'AN2070', 'アルトリウス', '悪魔との戦争に終止符を打った英雄の一人で、「伝説の大賢者」として知られる。ネコヤの常連たちの中では最年長である。好物は豚ロースのカツだ。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122704-JRPQA7Vg2qKf.png', NULL, NULL, '清川元夢', NULL, 122704, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024074', 'AN2070', 'ハインリヒ・ゼーレマン', '公国を危機から救い、その功績として要塞を授かった騎士隊長。港町で生まれたため、シーフードを好む。特にエビのフライがお気に入りだ。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122703-ZnRinaxtiSSi.png', NULL, NULL, '杉田智和', NULL, 122703, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024075', 'AN2070', 'アルフレッド', '公国の第一王子であり、マルガレーテの双子の兄。非常に好奇心旺盛で勇敢な人物である。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255041-gBjqEIA4Q5rm.png', NULL, NULL, '海田朱音', NULL, 255041, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024076', 'AN2070', 'ジョナサン', 'アルファデ社のシェフ。シリウスが彼を連れて「ネコヤ」を訪れる。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255049-Ruyr0lP3lX8l.png', NULL, NULL, '保住有哉', NULL, 255049, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024077', 'AN2070', 'ラニージャ', 'アリシアとよく行動を共にする悪魔の傭兵。蛇のような牙と、そこから放出される強力な毒から、「ポイズン・バイパー」というあだ名で呼ばれている。砂の国出身である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258771-TVQHfGtHG4c8.png', NULL, NULL, '名塚佳織', NULL, 258771, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024078', 'AN2070', 'ヒルダ', '帝都を拠点とする悪魔の傭兵。その優れた暗視能力と、ごくわずかな音さえも正確に聞き分ける能力から、「ナイト・ストライダー」という異名で知られている。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244351-djIcDAh4cr4t.png', NULL, NULL, '東山奈央', NULL, 244351, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024079', 'AN2070', 'ファルダニア', 'エルフの料理研究者。動物性食材を含む料理は一切口にしない。ネコヤの料理に触発され、世界中を旅して料理についてできる限り学んでいる。好物は豆腐ステーキ。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123175-ANYlzgCTJKc9.png', NULL, NULL, '日笠陽子', NULL, 123175, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024080', 'AN2070', 'マルガレーテ', '公国の第一王女であり、アルフレッドの双子の妹。好奇心旺盛だが、少し臆病なところがある。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255042-BhZaQeodNh22.png', NULL, NULL, '星谷美緒', NULL, 255042, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024081', 'AN2070', 'ラスティーナ', '魔都を統べる魔王。彼女は自身の能力に自信が持てず、前魔王である母の偉大さと自分を比べては、しばしば落ち込んでしまう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258768-8p0aWKMKVch3.png', NULL, NULL, '花澤香菜', NULL, 258768, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024082', 'AN2070', 'ヨハン', 'マイラの幼なじみで、見張り隊の一員。少々威張り屋で、つい熱中しすぎてしまうところがあるが、誠実な若者だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258775-hJQEM0cv3tUf.png', NULL, NULL, '熊谷健太郎', NULL, 258775, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024083', 'AN2070', 'サラ・ゴールド', '若きトレジャーハンター。猫屋でアレッタと出会った後、その若き悪魔を住み込みのメイドとして迎え入れた。好物はひき肉のカツレツ。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122702-k2U9WTUTlGW0.png', NULL, NULL, '安野希世乃', NULL, 122702, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024084', 'AN2070', 'シリウス・アルフェイド', 'アルファデ社の後継者。同社の元社長である祖父のトーマスが、彼をネコヤに紹介した。好物はミートソースだが、その味を再現するのに苦労している。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b123176-tiXJJu7t5W2S.png', NULL, NULL, '下野紘', NULL, 123176, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024085', 'AN2070', 'ピッケ', '大人になってもなお、子供の体つきを保っているハーフリング。妻のパッケと共に世界を旅している。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255043-wDRcbyoiszxO.png', NULL, NULL, '髙橋ミナミ', NULL, 255043, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024086', 'AN2070', 'ソウエモン', '「山の国」出身の侍。数々の戦功を挙げ、近衛兵の地位にまで上り詰めた。彼は、隣国のドウシュンと、犬と猫のように仲が悪い。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258770-ln7iBz1ZBFy0.png', NULL, NULL, '小山剛志', NULL, 258770, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024087', 'AN2070', 'ロロナ', '「黒の主」に仕える巫女。黒の信徒となったのはつい最近のことであるため、それに伴う力をまだ完全に使いこなせてはいない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258776-YcI4a1KOuWzT.png', NULL, NULL, '沼倉愛美', NULL, 258776, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024088', 'AN2070', 'アルフォンス', '公国で最強と称される海軍提督。遥か彼方の海にある人里離れた島に漂着した際、ネコヤを発見し、そのパトロンとなった。救助されるまでの20年間、島でできる限りの手段を尽くして生き延びた。好物はカレーライス。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255035-Zp4Ecv5ANpv0.png', NULL, NULL, '立木文彦', NULL, 255035, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024089', 'AN2070', 'ロメロ', 'ジュリエッタの恋人。現在、最愛のジュリエッタと共に逃亡中。顔色は悪いが、体調が悪いわけではない。（出典：公式サイト）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255036-ohBF0KDfwWEi.png', NULL, NULL, '八代拓', NULL, 255036, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024090', 'AN2070', 'パッケ', 'ハーフリングの女性。夫のピッケと共に世界を旅しながら、立ち寄った町で見つけた食材を使って料理を作り、それを販売している。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255044-ptlgzPIQInLx.png', NULL, NULL, '高田憂希', NULL, 255044, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024091', 'AN2070', 'マイラ', '王国の郊外にある町の、全粒粉パン職人の娘。彼女はレストランで父の手伝いをするのに忙しく過ごしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258777-cB1O98ASLDGE.png', NULL, NULL, '加隈亜衣', NULL, 258777, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024092', 'AN2070', 'ヴォルフガング', '帝国の皇帝であり、アーデルハイドの父。砂の国のシャリーフ王子から贈り物を受け取ったことをきっかけに、彼に関心を寄せるようになる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259978-09pTCliO8Lrd.png', NULL, NULL, '中田譲治', NULL, 259978, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024093', 'AN2071', 'ドラルク', 'ドラルクは、名門ドラゴン一族に属する不死の高等吸血鬼だが、些細なことで何度も死んでしまい、塵と化してしまう。 城が破壊されたため、彼はロナルドの家に居候することになったが、ロナルドはそれを大いに嫌がっていた。ドラルクは、青白く骨ばった顔立ちに、尖った耳と鼻を持つ、典型的な大人の吸血鬼の姿をしている。丸く垂れ目のような目をしていて、短い黒髪を後ろに撫でつけている。', 208, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195177-yXosuPbcJag8.png', '11月28日', NULL, '福山潤', NULL, 195177, 'MAIN', 197) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024094', 'AN2071', 'ロナルド', '新横浜を拠点とする20代の吸血鬼ハンター。 当初はドラルクをルームメイトに迎えることに乗り気ではなかったが、小説シリーズ『ロナルド・クロニクルズ』でのパートナーシップが成功したため、しぶしぶながらその吸血鬼を受け入れるようになった。イライラすると頻繁にドラルクを殺してしまう。また、セロリに対して極度の恐怖症を抱いている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195178-rhZQGshcPlO8.png', '8月8日', NULL, '古川慎', NULL, 195178, 'MAIN', 207) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024095', 'AN2071', 'ジョン', 'ジョンはオスのアルマジロで、ドラルクの使い魔である。人間の言葉は理解できるが、話すことはできない。彼の言葉を理解できるのはドラルクだけであるため、ジョンは身振り手振りを使って他者と意思疎通を図っている。ドラルクの使い魔として正式に認められた後、彼は不老不死の力を得た。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217146-bXXuJrvBnHFB.png', '7月1日', NULL, '田村睦心', NULL, 217146, 'MAIN', 565) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024096', 'AN2071', 'フクマ', '『オータム・ボクス』のロナルドの編集者。同社の全社員と同様、戦斧を振るう、恐ろしいほど冷静な男だ。締め切りを守るよりも猫を愛している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230540-feusimckYIgH.png', NULL, NULL, '土岐隼一', NULL, 230540, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024097', 'AN2071', 'ゴルゴナ', 'ドラルクの叔母であり、ドラウスの義姉。彼女はロナルドのポールダンスにかなり興味を持っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269438-8UDQNT1XEeNx.png', '5月7日', NULL, '小平有希', NULL, 269438, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024098', 'AN2071', 'Y談おじさん', '催眠術を使って、人々に秘めたフェチを口に出させる、中年の風貌をした吸血鬼。ドラウスの旧知の仲である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269446-gSxFF0nF1mmJ.png', NULL, NULL, '井上和彦', NULL, 269446, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024099', 'AN2071', 'アラネア', 'クモをモチーフにした吸血鬼。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269454-Yiit8bT4g7hm.png', NULL, NULL, '上坂すみれ', NULL, 269454, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024100', 'AN2071', '横田浩', '自称「新横浜・ボーイハンターズ」のメンバー。吸血鬼狩りをする小学生の男の子3人組。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269434-q22euJRFu9KR.png', NULL, NULL, '菊池紗矢香', NULL, 269434, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024101', 'AN2071', 'ステラ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b327634-tovaBfp46c6I.png', NULL, NULL, '中西尚也', NULL, 327634, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024102', 'AN2071', 'ヒヨシ', 'ヴァンパイア対策課の課長であり、ロナルドの兄。かつてはハンターだった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230539-sszYCtmGVRUh.png', '1月1日', NULL, '小野大輔', NULL, 230539, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024103', 'AN2071', '月光院希美', '彼女は、アダムが自分の友人に対して見せた軽薄な態度を、自分に向けられたものと勘違いし、彼を執拗に追いかけ回し、彼に噛まれることさえ喜んで受け入れた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269439-g9hGM484UksR.png', NULL, NULL, '花澤香菜', NULL, 269439, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024104', 'AN2071', '野球拳大好き', 'ヤキュケンが大好きな吸血鬼で、対戦相手を突破不可能なバリアの中に閉じ込めてプレイする。負けた方は服を脱がされる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269447-HtDr93EetOdz.png', NULL, NULL, '千葉繁', NULL, 269447, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024105', 'AN2071', 'シーニャ・シリスキー', 'ボンデージを用いて、自分より劣る吸血鬼を訓練し、支配する吸血鬼トレーナー。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269455-Cmekljflr9LR.png', NULL, NULL, '小野坂昌也', NULL, 269455, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024106', 'AN2071', 'ケイ・カンタロウ', 'ヴァンパイア対策課の隊員。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269431-wrkVJRdL4Yzy.png', NULL, NULL, '山下誠一郎', NULL, 269431, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024107', 'AN2071', 'ヒナイチ', '吸血鬼対策課の警官。同課史上最年少の副課長である。勤務中は二刀流を駆使する。一見、堅物で厳しい印象を与えるが、実はすぐに動揺してしまう。ドラルクの料理、特にクッキーが大好きだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217145-VCcQWihXPYaU.png', '3月3日', NULL, '日岡なつみ', NULL, 217145, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024108', 'AN2071', 'カメ谷レンジ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243493-Cnyd55Aq6WcD.png', NULL, NULL, '近藤孝行', NULL, 243493, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024109', 'AN2071', 'マナー違反', 'ゴーストを操る吸血鬼。ゴミをポイ捨てするなど、マナー違反を犯す。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269440-4CTTaU4v1yYo.png', NULL, NULL, '斉藤壮馬', NULL, 269440, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024110', 'AN2071', 'マイクロビキニ', '身につけているマイクロビキニから力を引き出す吸血鬼。彼が噛んだ相手は誰でもマイクロビキニを身にまとい、彼の支配下に入る。彼は『ヤキュケン・ラバー』の弟にあたる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269448-3e0e59DckSxQ.png', NULL, NULL, '安元洋貴', NULL, 269448, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024111', 'AN2071', 'サギョウ', '吸血鬼対策課の比較的新しいメンバーの一人。彼は自分の仕事をかなり真剣に受け止めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269456-T6yFIKzwHJZO.png', '5月4日', NULL, '西山宏太朗', NULL, 269456, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024112', 'AN2071', 'ヴァミマの店長', 'コンビニ「ヴァミマ」の店長であり、タケオの父親。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269433-VQrSwVDcPcVo.png', NULL, NULL, '山岸治雄', NULL, 269433, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024113', 'AN2071', 'わたあめ造り', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b327654-H6mpRyvZG8uT.png', NULL, NULL, '柳晃平', NULL, 327654, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024114', 'AN2071', 'ボサツ', '近所に住んでいる普通の猫', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254600-FKAi1zl6Irzg.png', NULL, NULL, '中尾隆聖', NULL, 254600, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024115', 'AN2071', 'フォン・ナ・ドゥーブツ', '性的なことばかり考えてしまうため、変身能力をほとんど制御できない吸血鬼。彼の真の姿はハンサムな金髪の吸血鬼だが、その姿になれるのは、欲求が満たされたときか、あるいは完全に興ざめしたときだけである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269441-B2zvI3HYSUK7.png', NULL, NULL, '高戸靖広', NULL, 269441, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024116', 'AN2071', '小林未沙', '3組の唇を持つ奇妙な姿の吸血鬼で、若くてハンサムな男性を標的にし、キスを通じて血を吸う。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269449-5pnfzhnwyZaO.png', NULL, NULL, '小林未沙', NULL, 269449, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024117', 'AN2071', 'メドキ', '吸血鬼ハンター。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269457-A4Yzagu4TOFJ.png', NULL, NULL, '酒井広大', NULL, 269457, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024118', 'AN2071', 'ゴウセツ', 'かつては吸血鬼ハンターだったが、現在はギルドのバーテンダーを務めている。ギルドに寄せられる依頼を受け付け、割り当てを行っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269432-2MxSXGjJzHnS.png', NULL, NULL, '稲田徹', NULL, 269432, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024119', 'AN2071', '半田桃', 'ヒナイチの部下。 ダンピールであり、ロナルドの高校時代の同級生。マザコン気質の彼は、吸血鬼である母親がロナルドの本のファンであることを嫌っており、ハンターであるロナルドのあまり好ましくない一面を母親に見せつけようとしている。その憎しみは執着に近いほどで、彼の部屋はロナルドのポスターやグッズで埋め尽くされている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217147-0CU5dEWC2Paw.png', '7月2日', NULL, '松岡禎丞', NULL, 217147, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024120', 'AN2071', 'ドラウス', 'ドラウスはドラルクの父である。彼は不死の高等吸血鬼であり、おそらくドラゴン一族の次期当主となるだろう。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258658-fvNQhKX21vrZ.png', '11月21日', NULL, '速水奨', 188, 258658, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024121', 'AN2071', '御真祖様', 'ドラルクの祖父。一族の長であり、一族の中で最も強い。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269442-ySGJXDC20i24.png', '11月10日', NULL, '中田譲治', NULL, 269442, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024122', 'AN2071', '半田あけ美', '半田桃の吸血鬼の母親。彼女はロナルドの大ファンだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269450-yfbqVWHgP45B.png', '9月3日', NULL, '井上喜久子', NULL, 269450, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
