INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024124', 'AN2071', 'ホームランバッター', 'バットとボールを使って戦う吸血鬼ハンター。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269460-YyhNt9ILzUDU.png', NULL, NULL, '塩尻浩規', NULL, 269460, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024125', 'AN2071', 'サテツ', 'ロナルドのギルドに所属する吸血鬼ハンターで、左腕に金属製の鎧をまとっている。元不良だが、たいていの状況では冷静さを保っている。しかし、怒らせると過去の面影が表れてしまう。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230537-a3OPzK2EPBg1.png', '6月13日', NULL, '細谷佳正', NULL, 230537, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024126', 'AN2071', '萩野真', '自称「新横浜・ボーイハンターズ」のメンバー。吸血鬼狩りをする小学生の男の子3人組。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262757-BsAJtcY23NtN.png', NULL, NULL, '朝井彩加', NULL, 262757, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024127', 'AN2071', '辻斬りナギリ', 'かつては連続殺人鬼だった吸血鬼だが、新横浜に入ってからというもの、かつての面影は影も形もなく、哀れな姿と化している。彼は自分の血を刃に変え、たいていは手のひらからそれを生み出す。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269443-2oO88bQogkGC.png', NULL, NULL, '関俊彦', NULL, 269443, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024128', 'AN2071', 'アダム', '別の女の子に言い寄ろうとしていたハンサムな吸血鬼が、その代わりにマレミの注目を集めてしまった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269451-DOGpu5Z4Fa1G.png', NULL, NULL, '大町知広', NULL, 269451, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024129', 'AN2071', '加藤新一', '自称「新横浜・ボーイハンターズ」のリーダー。吸血鬼狩りをする小学生の男の子3人組。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269436-pwvfsg36qkW3.png', NULL, NULL, '藤原夏海', NULL, 269436, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
