INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024141', 'AN2071', 'ター・チャン', 'ロナルドのギルドでハンターとして働く小柄な少女で、チャイナドレスを思わせる衣装を身にまとっている。物言いが率直で、的を射た個人攻撃的な侮辱で知られている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269445-qS0VDAGxG1k2.png', NULL, NULL, '石原夏織', NULL, 269445, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
