INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024152', 'AN2072', '石乃目巽', '新しい京都タワーに、まるで住人のかのように暮らしている謎の男で、いつも自分の好きなように振る舞っている。式神を操ったり、瞬時に移動したりといった、謎の能力を持っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b267073-je3ZUPCGaXBB.png', NULL, NULL, '松風雅也', NULL, 267073, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
