INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024167', 'AN2073', '天沢灯', '出身地：東京都　彼女は第1回「SELECTION PROJECT」の優勝者である。他の夢追い人たちの希望の光としてこの世界に登場した、伝説的なアイドルだ。しかし、18歳という若さで、依然として世の中で輝きを放っていたにもかかわらず、あかりの人生は交通事故により悲劇的な最期を迎えてしまった。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215440-6eLGLAfiv9kj.png', '4月11日', 'A', '早見沙織', 167, 215440, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
