INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024177', 'AN2074', '結希アンジュ', 'Ange Yuki (結希 アンジュ, Yuki Anju) is a character in Visual Prison and a member of OZ. He is a dhampir.  The protagonist. An awkward but strong-willed boy. Unable to adjust to his hometown, he leaves for Harajuku. He has loved music since he was a child and admires the songs of Guil from first generation ECLIPSE. In order to get to the bottom of things, he unconsciously goes into people''s pockets.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215279-luZDcJW0qpI8.png', '3月31日', NULL, '千葉翔也', NULL, 215279, 'MAIN', 95) ON CONFLICT DO NOTHING;
