INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024195', 'AN2076', '御剣冥夜', '国籍：日本人　所属：国連軍　柊白龍　3年B組　飛行隊A207-B　役職：ストーム・ヴァンガード　TSF： Type-00R タケミカヅチ、Type-77 ゲキシン、Type-97 フブキ、Type-94 シラヌイ　タケルとの出会いは「運命」だと信じ、突如として彼の部屋に忍び込んだ奇妙な少女。 恋のライバルたちと接するにつれ、メイアのその「運命」への信念は揺らぎ始めている。 巨大で裕福な三剣財閥の令嬢として、彼女は多少保護された環境で育った', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31933-lGhcO8YJOedr.jpg', '12月16日', 'AB', '奈波果林', 164, 31933, 'MAIN', 424) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024196', 'AN2076', '鑑純夏', '国籍：日本人　所属：白龍・柊（3年B組）　タケルの幼なじみで、明るくおっちょこちょいな性格。タケルに対しては、非常に独占欲が強い傾向がある。 二人はほぼ生まれてからずっと隣同士で暮らしており、彼女はタケルがいない生活など想像もできず、二人で築いた思い出を何よりも大切にしている。彼女は、何も変わることなく二人が永遠に一緒にいられるだろうと期待し、彼への想いをずっと胸に秘めてきた。しかし、メイアが現れたとき、', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31931-3lzD4H8P9T6E.png', '7月7日', 'O', '楠木ともり', 156, 31931, 'MAIN', 449) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024197', 'AN2076', '白銀武', '国籍：日本人　所属：国連軍　柊白龍　3年B組　飛行隊A207-B　役職：ストーム・ヴァンガード　TSF： 77式「激神」、97式「吹雪」、94式「白無」 『Muv-Luv』の主人公。タケル人気者で、頭はそこそこ良いが、怠け者の学生だ。 その怠け者ぶりにもかかわらず、タケルはいかなる状況でも、困っている人や自分に頼っている人を決して見捨てないタイプの人物だ。彼には奇妙な出来事が次々と起こるため、小月先生からは「ラブ・ニュークリアス」と呼ばれている。彼は', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31932-5OxcwZ1kpNhJ.png', '12月16日', NULL, '神木孝一', 175, 31932, 'MAIN', 315) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024198', 'AN2076', '榊千鶴', '国籍：日本人　所属：国連軍・白龍ヒイラギ第3年B組　飛行隊A207-B　役職：ガン・スイーパー　TSF： 77式「激神」、97式「吹雪」、94式「白無」  3年B組のクラス委員長で、神経質で命令口調、頑固な性格。かつては白龍高校ラクロス部の主将を務めていた。 学業とスポーツの両方で優秀な優等生だが、何でも自分でやろうとする傾向がある。無関心でルールを破る者に対しては寛容さがなく、そのせいで口論の渦に巻き込まれることも多い。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31934-NGr1JIAjKMAg.png', '5月5日', 'A', '伊藤美来', 157, 31934, 'MAIN', 82) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024199', 'AN2076', '彩峰慧', '国籍：日本人　所属：国連軍　柊白龍　3-B組　飛行隊A207-B　役職：ストーム・ヴァンガード　TSF： 77式「激神」、97式「吹雪」、94式「白無」   3-B組の無口で謎めいた少女。授業をサボって校舎の屋上でぶらぶらしていることがよくある。 頭の回転が速く自由奔放な性格で、規則に厳格な千鶴とは常に衝突しており、時にはわざと彼女を苛立たせようとしたりもする。焼きそばパンが大好き。   彼女の物腰や外見は', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31935-9C3Hq77XQHws.jpg', '9月27日', 'B', '佐伯伊織', 170, 31935, 'MAIN', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024200', 'AN2076', '香月夕呼', '国籍：日本　所属：白龍・柊、大日本帝国大学、国連軍　階級：副司令官　白龍・柊の物理教師。 ユウコはその分野の天才だが、反権威的な振る舞いのため学界から疎外されてしまった。そこで、親友のマリモと共に教師になることを決意した。余暇には、量子力学に関する理論の研究に取り組んでいる。  何よりも楽しみを愛する彼女は、常に人々を操り、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b32569-vA7te2nf8GGj.png', '6月8日', NULL, '青木瑠璃子', 174, 32569, 'MAIN', 176) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024201', 'AN2076', '社霞', '国籍：ロシア　所属：国連軍　かすみは、横浜基地で小月教授の世話を受けながら暮らす謎めいた少女で、B-19号室で脳が入ったシリンダーを手にしている姿がよく目撃される。彼女は「Alternative IV」と書かれたパッチが付いた、他とは異なる制服を着ている。   かすみは物静かで控えめな性格で、自ら他人に話しかけたり、感情を露わにしたりすることはめったにない。普段はめったに外に出ないが、タケルと少し親しくなってからは、タケルのところへ来るようになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b64253-YFCSpqvc74jz.jpg', '10月24日', NULL, '高尾奏音', 133, 64253, 'SUPPORTING', 122) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024202', 'AN2076', '月詠真那', '国籍：日本　所属：大日本帝国皇室近衛隊（第19独立近衛飛行隊）　階級：中尉　TSF：77式「激神」、00F型「タケミカヅチ」　マナは、ミツルギ・メイヤの専属付き人であり、家庭教師でもある。 彼女は「ミツルギ」という家名を非常に重んじており、それに対する不敬な行為は決して許さない。任務上という理由だけでなく、純粋にメイアのことを気にかけているため、メイアがタケルと同居している間、メイアがタケルの心を掴めるよう手助けしようとしているが、彼女自身も経験が浅いため', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b67135-JLN4ascffjaG.png', '1月14日', NULL, '柳澤良音', 168, 67135, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024203', 'AN2076', '臼杵咲良', '国籍：日本　所属：国連軍（横浜基地、特殊任務部隊A-01）　階級：少尉　福岡で生まれたサクラは、9歳の時に佐渡島へ引っ越した。サクラには、オリンピックのマラソン選手だった愛情深い両親がおり、母親は歌うことが大好きだった。 テレビで両親の競技を観戦したり、母の歌声を聴いたりした時間は、彼女にとって最も幸せな思い出の一部だった。9歳の時、飲酒運転による事故で両親を亡くしてしまった。その後、祖父母に引き取られ、佐渡島で新たな生活を始めた。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282938-xQ1FeQOBjz2N.png', '4月19日', NULL, 'ヰ世界情緒', 146, 282938, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024204', 'AN2076', 'イルマ・テスレフ', '米陸軍の少尉。アルフレッド・ウォーケン少佐の指揮下、第66戦術装甲大隊「ハンター」の副官を務め、コールサインは「ハンター-2」である。フィンランドからの難民である彼女は、自身と家族の市民権と安全を確保するため、米陸軍に入隊した。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245040-l1ya16qYxAB7.png', '8月26日', NULL, '白石晴香', NULL, 245040, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024205', 'AN2076', '門兵1', '国籍：日本人　階級：伍長　所属：国連　タケルがこの世界で最初に出会った2人のうちの1人。横浜基地の正門の警備を担当する兵士たちである。2人とも「エイシ」になるための適性試験に不合格となり、代わりに基地の警備員となった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294189-AmmqHpZjMt9D.jpg', '11月11日', NULL, '深川和征', NULL, 294189, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024206', 'AN2076', '佐渡島の老爺', '国籍：日本人　臼杵桜の世話をしている佐渡島の老人。避難指示が出された際、避難先が定まっていなかったため、彼を含む数十人は直ちに避難せず、その結果、島への予期せぬ攻撃に巻き込まれてしまった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313061-GsloSv42VXMJ.png', NULL, NULL, NULL, NULL, 313061, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024207', 'AN2076', '早乙女まどか', '国籍：日本人　所属：日本陸軍／MDF（佐渡基地 第3戦術予備部隊 アルファ飛行隊）　階級：少尉　TSF：77式「激神」　1998年9月に新潟へ派遣された要員に代わるため、佐渡島の予備部隊に配属されたパイロット。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313070-ECvMPfVJhYOm.png', NULL, NULL, '林鼓子', NULL, 313070, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024208', 'AN2076', 'パウル・ラダビノッド', '国籍：インド　所属：国連太平洋第11軍　階級：准将　日本・横浜にある国連太平洋第11軍基地の司令官。同基地の初代司令官であり、1999年の就任以来、基地の防衛を統括している。   ラダビノッドは横浜基地の最高軍事責任者であり、同基地に関するあらゆる軍事事項について最終決定権を有しているが、実際には小月教授が基地の運営の大部分を担っていることが知られている。指揮官に任命される前は、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b13926-tGBNfCCW9pMR.jpg', '12月7日', NULL, '若本規夫', NULL, 13926, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024209', 'AN2076', '神代巽', 'R大宅lガードの一員。辰巳は、蛭子ミナギや雪野トモエと共にマナに仕えており、第19独立ガード飛行隊に所属し、コールサインは「Blod-2」である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247273-5Gc4tIVVLgY0.png', '6月7日', NULL, '宮崎珠子', NULL, 247273, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024210', 'AN2076', '涼宮茜', 'はるかの妹。当初は、たかゆきとみづきの両方を兄姉のように見ていたが、二人がはるかの知らないところで付き合っていたことを知ってしまう。はるかが病院に入院している間、たとえ昏睡状態であっても、はるかに付き添える人が他にいないため、彼女は毎日見舞いに訪れている。 このことから、彼女が姉をどれほど愛しているかがうかがえる。彼女もミツキ同様、それ自体が実力のある水泳選手だが、ミツキには到底及ばないと感じている。その後、ミツキに対する彼女の激しい憎しみは……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b918-wHLQbmou9v7K.jpg', '10月20日', NULL, '伊藤彩沙', NULL, 918, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024211', 'AN2076', '小沢久彌', '国籍：日本人　所属：日本海軍　階級：大将　小沢は、日本海軍の戦艦「最上」の艦長である。また、佐渡島がBETAに陥落するのを目の当たりにした。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294254-I0x1y7V8B3Fa.png', NULL, NULL, '伊丸岡篤', NULL, 294254, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024212', 'AN2076', '大倉鈴乃', '国籍：日本人　所属：日本陸軍／MDF（佐渡基地 第3戦術予備隊 ブラボー中隊）　TSF：77式ゲキシン　日本陸軍の指揮官。大倉は、佐渡基地の第3戦術予備隊ブラボー中隊の指揮を執っている。   第1大隊と第2大隊が第3大隊の要員と共に新潟へ派遣された後、大倉は人員不足を補うため、他部隊から配属された多くの新人や若手パイロットを率いることになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313071-HPREHLOBERXh.png', NULL, NULL, '矢作紗友里', NULL, 313071, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024213', 'AN2076', '神宮司まりも', '国籍：日本人　所属：白龍・ヒイラギ、国連軍横浜基地、日本陸軍／MDF第1大隊　階級：軍曹、少佐　TSF： 77式ゲキシン、94式シラヌイ　白龍高校の英語教師であり、3年B組の担任。タケルからは「マリモちゃん」と呼ばれている。おっちょこちょいで少し小言が多いところもあるが、優しい性格の持ち主だ。 男子にも女子にも人気があり、マリモは生徒全員から愛されている。  彼女は、白龍・柊の親友であるユウコと共に教師になった。彼女はいつも…', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b32570-8e7bpgz45qzQ.jpg', '8月10日', NULL, '渡部紗弓', 166, 32570, 'SUPPORTING', 136) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024214', 'AN2076', '沙霧尚哉', '国籍：日本人　所属：日本陸軍／MDF（第1戦術装甲連隊）　階級：大尉　TSF：94式「シラヌイ」　欅総合病院に勤務する医師。 新人医師だった頃、サギリは綾峰家の母親と仕事を共にし、ケイの家庭教師も務めるなど、綾峰家と親しく付き合っていた。その親しさは、ケイの母親を自分の母親のように思うほどだった。当時、ケイと彼は非常に親しい友人関係にあり、互いに好意を抱いていたが、それ以上の関係には発展しなかった。  ある事故で、ケイの母親が身代わりとなって', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203531-SxFDZDPSgD5U.png', '3月31日', NULL, '興津和幸', NULL, 203531, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024215', 'AN2076', '高原萌香', '国籍：日本　階級：少尉　所属：国連軍　TSF：吹雪、94式白波　『エクストラ』では、高原は3-D組の生徒の一人であり、茜や朝倉と共に3-B組とのラクロス試合に出場している。  『オルタナティブ』では、高原は神宮寺マリモ率いる訓練小隊207Aの一員として士官候補生を務めており、小隊長は涼宮茜が務めていた。その後、高原はCCSEを修了し、茜、春子、タエ、Aと共に卒業した後、ヴァルキリーズに配属される。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294294-tUAGsfRBPJNa.png', NULL, NULL, '三谷綾子', NULL, 294294, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024216', 'AN2076', '衛士 2', '彼女は、横浜基地に駐留する国連所属のエイシである。格納庫内の「タケミカヅチ」に不審を抱き、PXで第207訓練部隊の隊員たちに不快感を示した2人のエイシのうちの1人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294187-pJXwwGZVUF6A.png', NULL, NULL, '藤田麻美', NULL, 294187, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024217', 'AN2076', '大宅', '国籍：日本人　所属：日本陸軍／MDF（佐渡基地 第3戦術予備隊 ブラボー中隊）　階級：少尉　TSF：77式ゲキシン　1998年9月に新潟へ派遣された要員に代わるため、佐渡島の予備部隊に配属されたパイロット。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313072-GEkr7FrX03K1.png', NULL, NULL, NULL, NULL, 313072, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024218', 'AN2076', '反乱軍衛士', '国籍：日本人　所属：日本陸軍／MDF　サギリ大尉率いる反乱軍に所属するパイロットで、強い反英感情を抱いている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313081-UbWJltuCG8n2.jpg', NULL, NULL, '利根健太朗', NULL, 313081, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024219', 'AN2076', '衛士C', '国籍：アメリカ　所属：国連軍　TSF：F-15C イーグル　「オペレーション・ルシファー」の後、横浜ハイブのメインホールに到着した小規模な飛行隊に所属するパイロット。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313104-tWUVuhWofSG9.png', NULL, NULL, '高橋大輔', NULL, 313104, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024220', 'AN2076', '珠瀬壬姫', '国籍：日本　所属：国連軍　柊白龍　3年B組　飛行隊A207-B　役職：インパクトガード　TSF： 77式ゲキシン、97式フブキ、94式シラヌイ  知り合いの皆が仲良くして、幸せになってほしいと願う、元気で楽天的な少女。仲間同士の喧嘩が勃発すると、たいてい彼女が仲裁に入る。 猫のような外見から、タケルにはペットのように扱われ、「タマ」というあだ名をつけられているが、本人は全く気にしていないようだ。クラスでは「m', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31936-8hiRTXOxv864.png', '2月29日', 'A', '田中貴子', 134, 31936, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024221', 'AN2076', '駒木咲代子', '小牧さよ子は第1戦術装甲連隊の中尉であり、「12/5事件」では、佐桐奈大宅大尉の副官として参戦した。佐桐を深く尊敬しており、彼の理想を信じ、その実現に向けて尽力している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246822-j7EVtuMJM3Oa.png', '11月3日', NULL, '豊口めぐみ', NULL, 246822, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024222', 'AN2076', '煌武院悠陽', '国籍：日本人　所属：日本帝国皇宮警護隊、小布院藩・保世家　位階：将軍　TSF：タイプ-00R タケミカヅチ　日本の将軍であり、小布院藩・保世家の現当主。 常に穏やかで気品のある振る舞いをみせるユヒは、めったに慌てることなく、彼女と話をしたすべての人々から尊敬されている。将軍に選出される前の10代の頃でさえ、彼女は日本国内の非常に影響力のある人物たちから、将来の支持者として注目されていた。彼女の言葉遣い、身振り手振り、そして決断力は人々に強い印象を与えた。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b38245-Noga6IZl6kYI.png', '12月16日', 'AB', '野口瑠璃子', 164, 38245, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024223', 'AN2076', '珠瀬玄丞斎', '彼は国連の事務次長である。珠瀬壬姫の父である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247272-0gygrZx1U0H1.png', NULL, NULL, '田島章寛', NULL, 247272, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024224', 'AN2076', '衛士 1', '彼は、横浜基地に駐留する国連所属のエイシである。格納庫内の「タケミカヅチ」を不審に思い、PXで第207訓練部隊の隊員たちに不快感を示していた2人のエイシのうちの1人である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294190-jqcY8YgPUrAI.png', NULL, NULL, '室元気', NULL, 294190, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024225', 'AN2076', '村田彬義', '国籍：日本人　所属：日本陸軍／MDF（佐渡基地 第3戦術予備部隊 アルファ飛行隊）　階級：少尉　TSF：77式「激神」　1998年9月に新潟へ派遣された要員に代わるため、佐渡島の予備部隊に配属されたパイロット。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313073-sAVHyNw7g8kN.png', NULL, NULL, '天崎滉平', NULL, 313073, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024226', 'AN2076', 'ブラボーリーダー', '国籍：アメリカ　所属：国連軍　階級：中尉　TSF：F-15C イーグル　「オペレーション・ルシファー」の後、横浜ハイブのメインホールに到着したTSFパイロットからなる小規模な飛行隊の隊長。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313103-8Gh5RUwOC1lh.jpg', NULL, NULL, '利根健太朗', NULL, 313103, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024227', 'AN2076', '風間梼子', '国籍：日本　所属：白龍・ヒイラギ、国連軍（横浜基地、特殊任務部隊A-01）　階級：少尉　TSF： 94式シラヌイ、シラヌイII、F-15SEJ「月光」　イスミの「ヴァルキリー」の一員で、タケルやアカネたちより先に配属された。 トコは物腰が柔らかく、優雅で、非常に聡明であり、先鋒を率いるミツキと後衛を率いるミサエという、それぞれ強い個性を持つ二人の間を、しばしば緩衝役として支えている。また、彼女は宗像ミサエの親友でもあり、二人は', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234885-b0Cqhbcih6ug.png', '12月4日', NULL, '和氣あず未', 155, 234885, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024228', 'AN2076', '鎧衣左近', '帝国情報局第二課の課長であり、鎧御子の父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245041-jR5hr32I7wZ5.png', '2月16日', NULL, '田所陽向', NULL, 245041, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024229', 'AN2076', '彩峰萩閣', '国籍：日本　階級：陸軍中将　所属：日本陸軍　綾峰修角は綾峰圭の父であり、佐桐奈大宅にとって師であり、父親代わりの存在であった。  日本陸軍の陸軍中将であった綾峰は、1998年に韓国南西部で行われた「光州作戦」に参加した。この作戦は後に「光州の悲劇」として知られることになる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294304-4mGHY4arecnR.png', NULL, NULL, '中村和正', NULL, 294304, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024230', 'AN2076', '侍従長', '国籍：日本人　ユヒの腹心である大侍従。12月5日の事件の際、ユヒが都から脱出する際に同行したのは彼女ただ一人だった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294300-dSzD0k2YvxHq.png', NULL, NULL, '寺依沙織', NULL, 294300, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024231', 'AN2076', '橘雅清', '国籍：日本　所属：日本陸軍／陸軍防衛隊　橘雅清は、日本海防衛の要である佐渡島の要塞陣地の指揮官である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313074-8kQy4TdqDMBy.png', NULL, NULL, '青山穣', NULL, 313074, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024232', 'AN2076', 'ハンター3', '所属：米陸軍（第66戦術装甲大隊） TSF：F-22A ラプター  12月5日の事件当時、ウォーケン少佐率いるハンター飛行隊の一員として現場に居合わせた。F-22A ラプターを操縦している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313083-gz9I8gfCkOH7.png', NULL, NULL, '綿貫竜之介', NULL, 313083, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024233', 'AN2076', '速瀬水月', 'ミツキはタカユキとハルカの両方と友達だが、密かにタカユキに想いを寄せている。高校時代は競泳選手だったが、ハルカの事故の直後、タカユキの世話をするために水泳を辞めることになった。 高之がうつ状態から抜け出せないでいると、彼女は彼に身を投げ出し、想いを打ち明ける。美月は善意に満ちているが、自分の感情を抑え込みすぎてしまい、それが溜まりに溜まって危険な形で爆発してしまう。また、美月は自分が責任を負っていると思い込んでおり――', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b917-XwMwDx1gpPy1.png', '8月27日', NULL, '山村響', NULL, 917, 'SUPPORTING', 94) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024234', 'AN2076', '柏木晴子', '国籍：日本　所属：白龍・柊高校3年B組、国連軍第207A飛行隊および特殊任務部隊A-01　階級：少尉　TSF：97式「吹雪」、94式「白波」　タケルの3年B組の同級生の一人。 白龍高校バスケットボール部のポイントガードであり、卒業後は大学スポーツへの推薦を受けている。春子のボーイッシュな外見と、明るく気さくな性格は、男女を問わずクラスメートから人気がある。春子とタケルは親友同士であり、二人は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234814-4vuqbr6x4m1z.png', '10月10日', NULL, '野田真理愛', 171, 234814, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024235', 'AN2076', '戎美凪', 'ミナギはマナの下で、トモエ・ユキノやカミヨ・タツミと共に従事しており、第19独立護衛飛行隊の一員である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247268-wJMsrlmP9TU9.png', '1月30日', NULL, NULL, NULL, 247268, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024236', 'AN2076', '京塚志津江', '横浜基地の再建後、彼女は基地職員としてそこで働くことを志願した。以前の職務経験が評価され、基地内のPXの一つ、具体的にはタケルとその友人たちが利用する店舗で、コックとして働くことになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247271-l8qJhDntCxXv.png', NULL, NULL, '斉藤貴美子', NULL, 247271, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024237', 'AN2076', '石川', '国籍：日本人　所属：日本陸軍／MDF（佐渡基地 第3戦術予備隊 ブラボー中隊）　階級：少尉　TSF：77式ゲキシン　1998年9月に新潟へ派遣された要員に代わるため、佐渡島の予備部隊に配属されたパイロット。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313075-lICziaPsvpDu.png', NULL, NULL, NULL, NULL, 313075, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024238', 'AN2076', '鎧衣美琴', '国籍：日本人　所属：国連軍 3-B組 白龍・ヒイラギ　クラス　A207-B飛行隊　役職：ブラストガード　TSF： 77式「激神」、97式「吹雪」、94式「白無」　3-B組で、タケルと性別が曖昧な親友であり、ヴァルガーン・オンのパートナー。周囲からは男性と見なされている。 ミコトはとても人懐っこいが、会話に耳を傾けず、無視して自分の行きたい方向へふらふらと逸れてしまうという悪い癖がある。これは父親から受け継いだ癖だ。彼と父親は……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b31937-pctzPHZimXnF.jpg', '4月1日', 'O', 'Lynn', 156, 31937, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024239', 'AN2076', '伊隅みちる', '国籍：日本　所属：白龍・柊＆大学、国連軍特殊任務部隊A-01　階級：大尉　TSF： 94式シラヌイ、TF-4J ゲキシン  特殊任務部隊A-01「イスミのヴァルキリー」の指揮官であり、イスミ家の4人の娘のうち次女。 個人的に知る者からは慕われているミチルは、指揮官として、また部下に対する個人的な接し方においても率直で、深刻な事柄について話す際には、めったに言葉を濁さない。 戦場を経験し、極めて有能な', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b74912-ER7rPHT7OgJ3.png', '10月13日', 'AB', '大地葉', 164, 74912, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024240', 'AN2076', 'イリーナ・ピアティフ', '国連軍で中尉の階級を持つイリーナ・ピアティフは、横浜基地の通信担当官を務めるとともに、同基地副司令官である小月裕子の秘書も兼任している。彼女はポーランド出身である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247270-BYkwt4CXb2F0.png', NULL, NULL, '咲々木瞳', NULL, 247270, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024241', 'AN2076', '巴雪乃', 'ユキノは、エビス・ミナギやカミヨ・タツミと共にマナの下で働き、第19独立護衛飛行隊の一員である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247269-JPGsOJiHdhT3.png', '4月6日', NULL, NULL, NULL, 247269, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024242', 'AN2076', '門兵2', '国籍：アメリカ人　階級：伍長　所属：国連　タケルがこの世界で最初に出会った2人のうちの1人。横浜基地の正門の警備を担当する兵士たちだ。2人とも「エイシ」になるための適性試験に不合格となり、代わりに基地の警備員となった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294188-r6OcW3XA7bEV.jpg', '11月11日', NULL, '利根健太朗', NULL, 294188, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024243', 'AN2076', '築地多恵', '国連第11部隊の一員であり、神宮寺マリモの指揮下にある横浜基地第207訓練部隊A小隊に所属し、小隊長を務めるのは涼宮茜である。その後、総合戦闘技能評価を無事に通過した築地は、ヴァルキリーに配属されることになる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247274-GD1kpGdRyr5s.png', NULL, NULL, '近野 千聡', NULL, 247274, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024244', 'AN2076', '坂崎都', '国籍：日本人　所属：日本陸軍／MDF（佐渡基地 第3戦術予備隊 アルファ飛行隊）　TSF：77式ゲキシン　日本陸軍の指揮官。坂崎は佐渡基地の第3戦術予備隊の指揮を執っている。   第1大隊と第2大隊が第3大隊の要員と共に新潟へ派遣された後、坂崎は人員不足を補うため、他部隊から配属された多くの新人や若手パイロットを率いることになった。その中には小牧も含まれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313067-DWXGRBbbSDXV.png', NULL, NULL, '白石涼子', NULL, 313067, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024245', 'AN2076', '米軍衛士', '国籍：アメリカ人　所属：米陸軍（第174戦術装甲大隊・ヒート中隊）　TSF：F-15E ストライク・イーグル　グアムのアンダーセン基地に駐留するTSFパイロット。 12月5日の事件が発生すると、彼と所属大隊は反乱軍の鎮圧任務に就くことになった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313076-PAnAHiiq31Ws.png', NULL, NULL, '深川和征', NULL, 313076, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024246', 'AN2076', '衛士B', '国籍：アメリカ　所属：国連軍　TSF：F-15C イーグル　「オペレーション・ルシファー」の後、横浜ハイブのメインホールに到着した小規模な飛行隊に所属するパイロット。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313085-hOvneuxSS5W9.jpg', NULL, NULL, '深川和征', NULL, 313085, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024247', 'AN2076', '宗像美冴', '国籍：日本　所属：国連軍・白龍・柊（横浜基地、特殊任務部隊A-01）　階級： 中尉 TSF：94式シラヌイ、シラヌイII、F-15SEJ「月光」　京都出身、イスミのヴァルキリーC飛行隊長。 特殊任務部隊A-01において3番目に高い階級を持ち、イスミと同様に卓越したパイロットである。ミサエは謎に包まれた女性で、しばしばよそよそしく、捉えどころがなく、他人をからかったり混乱させたりするために風変わりなジョークを飛ばすため、その本心を見抜くのは難しい。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234884-8w1Oi08xTkFR.png', '11月7日', NULL, '八巻アンナ', 167, 234884, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024248', 'AN2076', 'アルフレッド・ウォーケン', '米陸軍の少佐であり、第66戦術装甲大隊「ハンター」の指揮官を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246824-nDFsb72yygiJ.png', '4月5日', NULL, '露崎亘', NULL, 246824, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024249', 'AN2076', '安倍智彦', '国籍：日本人　所属：日本海軍　階級：大将　安倍は、日本海軍の戦艦「信濃」の艦長である。彼は、佐渡島がBETAに陥落した際、艦長を務めていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294273-dZHfHEjTNiZh.png', NULL, NULL, '上田燿司', NULL, 294273, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024250', 'AN2076', '草野哲也', '国籍：日本　所属：日本陸軍／MDF（佐渡基地 第3戦術予備部隊 アルファ飛行隊）　階級：少尉　TSF：77式「激神」　横浜出身の新人TSFパイロット。 草野は、1998年9月に新潟へ派遣された人員の補充として、佐渡島の予備部隊に配属された。小牧が佐渡島に到着すると、彼は彼女のウィングマンに任命され、基地内を案内したことをきっかけに、二人は友人となった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313069-MJqVjg3xGrYH.png', NULL, NULL, '河西健吾', NULL, 313069, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024251', 'AN2076', '岩城副官', '国籍：日本人　所属：日本陸軍／海上防衛軍　いわきは橘の副官であり、日本海防衛の要である佐渡島の要塞陣地の副指揮官を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313077-dDDJEzWdQTBP.png', NULL, NULL, '石谷春貴', NULL, 313077, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024252', 'AN2077', '時雨・ダニエル・魁', 'シグレは、「英雄」になることを夢見て、南極戦線に「スリーパー」として志願した若者だ。彼は、アサイラムの最前線を調査する第11プラトン（ヴェラ・プラトン）に配属された。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b240281-dkA2yRAf5QrZ.png', NULL, NULL, '下野紘', NULL, 240281, 'MAIN', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024253', 'AN2077', 'ヴェーラ・ルスタモワ', '南極戦線「プラトン11」の指揮官。巨大な鎌のような武器を操り、時間を繰り返させる能力を持っているようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254765-ZNY1JIjNaBFV.png', NULL, NULL, '小清水亜美', NULL, 254765, 'MAIN', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024254', 'AN2077', 'ローレンス・ラリー・ジャクソン', '彼はいたずら好きで、軍隊入隊初日にシグレにサプライズを仕掛けた。脳に傷があり、痛みを感じることができない。脳科学の研究に役立つと考え、アサイラムに加わった。 戦闘では、「おとり」といった危険な役割も躊躇なく引き受ける。（出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254767-KG8tvCKVSJaJ.png', NULL, NULL, '広瀬裕也', NULL, 254767, 'MAIN', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024255', 'AN2077', '餅木スミレ', '元アンダーグラウンドアイドル。夢を諦め、再起を図るために軍に入隊した。しかし、「アサイラム」に対する抵抗力が乏しかったため、作戦命令を下す「サニティ・アンカー」となってしまう。何らかの理由でシグレと対立する。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254770-C8wxmK1jmDeu.png', NULL, NULL, '本渡楓', NULL, 254770, 'MAIN', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024256', 'AN2077', '小鳩玲香', '彼女は優雅な口調で「はい」と答えた。彼女は裕福な男性の娘である。重傷を負ったため、右足は義足に置き換えられていた。最先端の戦闘用義足を入手できることを知ると、彼女は志願した。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254769-QABDfCQPKDXa.png', NULL, NULL, '野口瑠璃子', NULL, 254769, 'MAIN', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024257', 'AN2077', 'ヘイデン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286089-gV0jtLpaelQl.jpg', NULL, NULL, '鈴木崚汰', NULL, 286089, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024258', 'AN2077', 'ちゃんジェームス', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286088-XElzGSu5UGFG.png', NULL, NULL, '手塚ヒロミチ', NULL, 286088, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024259', 'AN2077', 'レスリー・ブラン', '彼は第11小隊の副隊長である。また、元ダンサーでもある。男性だが、女性のような振る舞いをする。剣術はかなり巧みで、新入隊員を気遣う優しい一面も持っている。（出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254766-tFQsQ5RG55k3.png', NULL, NULL, '鳥海浩輔', NULL, 254766, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024260', 'AN2077', 'ナディア', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286087-PUwHEe9WLlCy.png', NULL, NULL, '森永千才', NULL, 286087, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024261', 'AN2077', 'ニコラス・クルーガー', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254768-D0nzo6F15Zja.png', NULL, NULL, '島田岳洋', NULL, 254768, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024262', 'AN2077', 'ホットプ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286090-1UJVxHgwJSMz.png', NULL, NULL, '近藤孝行', NULL, 286090, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024263', 'AN2078', '日暮とわ', '日暮とわは、令和の時代に暮らす半妖である。彼女は殺生丸の長女であり、せつなの一卵性双生児の姉にあたる。4歳の時、骨喰の井戸にある「時の樹」の力によって、何らかの形で現代へと送り込まれた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169510-OD4XFyNkRY2L.png', NULL, NULL, '松本沙羅', NULL, 169510, 'MAIN', 127) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024264', 'AN2078', 'せつな', 'せつなは、琥珀のもとで働く半妖の鬼殺隊員だ。4歳の時に双子の姉・トワと離ればなれになったが、いとこのもろはと共に未来へ旅をした後、トワと再会した。', 14, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169509-ldlnMY6Jd2JC.png', NULL, NULL, '小松未可子', NULL, 169509, 'MAIN', 140) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024265', 'AN2078', 'もろは', 'もろはは、犬夜叉と日暮かごめの唯一の娘である。彼女は四分の一の妖怪の血を引く賞金稼ぎで、妖怪を退治し、その部位を他の妖怪退治者に売り渡している。おそらく、彼らがそれを使って武器や鎧を作るためだろう。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169511-XL5d5sayJpTz.png', NULL, NULL, '田所あずさ', NULL, 169511, 'MAIN', 259) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024266', 'AN2078', 'Grandpa Higurashi', 'かごめの祖父。かごめが学校を休む際、彼はよく面白い言い訳でかごめの欠席をカバーしており、そのせいでかごめの友人たちは彼女のことを大いに心配している。    おじいさんは、その服装から見て伝統的な日本の神職であることがわかる。どうやら、代々一族が受け継いできた日暮神社の現在の管理人／守護者／世話役／所有者のようだ。彼は、日常の生活の中に一族の神社の歴史に関する知識を織り込もうと絶えず努めており、その熱意は', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/40419.jpg', NULL, NULL, '鈴木勝美', NULL, 40419, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024267', 'AN2078', '翡翠', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b189857-3rW7tMHSOT4R.png', NULL, NULL, '浦尾岳大', NULL, 189857, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024268', 'AN2078', '雲母', '雲母は、妖怪退治師の集まる山村出身の妖怪退治師・珊瑚の相棒である猫又だ。 雲母は通常、子猫ほどの大きさの小さくて可愛らしい猫の姿で現れ、クリーム色の毛並み、黒い耳、さまざまな黒い模様、大きな赤い目、そして二本の尾を持っているが、その真の姿は、大きな剣歯虎のような妖怪である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/8323.jpg', NULL, NULL, NULL, NULL, 8323, 'SUPPORTING', 229) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024269', 'AN2078', '犬夜叉', '誕生日：不明　出身地：日本西部（富山に相当）　武器：爪、剣「テッサイガ」　必殺技：爪「三魂鉄砕」、飛人鉄砕。 鉄砕牙――「風の傷」、「爆龍波」、「金剛波」、「冥道斬月波」。    家族：イザヨイ（母）、犬大将（父）、殺生丸（異母兄弟）。    人間の父と妖怪の母の間に生まれた半妖の少年で、物語の主人公。彼は、自身の父の体の一部から作られた超自然的な刀「テサイガ」（アメリカ版吹き替えでは「テサイガ」と発音）を振るう。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1353-xsZhvfi7IFzT.png', NULL, NULL, '山口勝平', 167, 1353, 'SUPPORTING', 2927) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024270', 'AN2078', '玉兎', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191930-SnigGCgoFyuX.jpg', NULL, NULL, '上田瞳', NULL, 191930, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024271', 'AN2078', 'りおん', 'りおんはキリンマルの娘です。', 600, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b320917-FrjyWYEF5URN.jpg', NULL, NULL, '藤田咲', NULL, 320917, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024272', 'AN2078', '日暮かごめ', 'ヒロインで、中学3年生。高橋留美子の作品に登場する多くのヒロイン（ルム、天道茜、音無京子など）と同様に、かごめはとてつもなく優しい一面を持つ一方で、挑発されると非常に危険な存在にもなり得る。   犬夜叉は、かごめの命令にしか反応しない特別な数珠（「制圧の数珠」として知られる）を身につけており、かごめが「おすわり！」と叫ぶと （吹き替え版ではしばしば「お座り、坊や！」）と叫ぶと、犬夜叉は地面に叩きつけられる。この首飾りは、彼の危険な性質ゆえに彼に付けられたものである。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1354-PuUTCSX7UzKA.png', NULL, NULL, 'ゆきのさつき', NULL, 1354, 'SUPPORTING', 1684) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024273', 'AN2078', '金烏', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191931-6gM63cCswo8R.jpg', NULL, NULL, '胡麻鶴彩', NULL, 191931, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024274', 'AN2078', '邪見', '殺生丸に仕える妖怪。特に強いわけではないが、極めて忠実で、普段はコミカルなキャラクターとして描かれる。 殺生丸は、邪見の失敗や厄介な振る舞いに対して、たいてい容赦ない殴打で応じるが、邪見はこれを殺生丸の当然の権利だと信じ、その忠誠心を決して揺るがすことはない。 邪見が殺生丸に従うようになったきっかけは、殺生丸が脅威となる妖怪を討ち、邪見の命を救った際、その力と威厳に心を奪われたことだった（これは偶然の出来事であり、殺生丸はその妖怪を単に', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1364-4Y3v1IMEAwIg.jpg', NULL, NULL, 'チョー ', NULL, 1364, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024275', 'AN2078', '珊瑚', '珊瑚は、プロの妖怪退治師の村出身の妖怪退治師である。 犬夜叉の仲間の中で唯一、超自然的な力を持たない珊瑚は、その代わりに妖怪の骨で作られた巨大なブーメラン「ヒライコツ」を操り、さらに妖怪と戦うための多彩な道具や技を駆使する。 珊瑚もまた、奈落の邪悪な陰謀の犠牲者である。奈落の妖怪たちによって家族を殺され、村全体が破壊された。これにより、奈落は犬夜叉のせいにし、珊瑚を操って……', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1355-zPTmTwhMXQbt.png', NULL, NULL, '桑島法子', 165, 1355, 'SUPPORTING', 1254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024276', 'AN2078', '竹千代', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b189856-O0v1vkwY3T5w.png', NULL, NULL, 'ファイルーズあい', NULL, 189856, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024277', 'AN2078', '殺生丸', '犬夜叉の異母兄。犬夜叉とは異なり、殺生丸は純血の犬妖で、犬夜叉が半妖であることや人間と交わることを軽蔑している。  彼は非常に強力な妖怪であり、純粋な戦闘力において真に匹敵する者はいないと思われるが、第23巻でその機会があったにもかかわらず、奈落を倒すことはできなかった。  ファンからは「西の国の主」と呼ばれているが、この称号は漫画のどこにも登場しない。高橋先生も、殺生丸にはそのような称号はないと述べている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1358-oR7bIGfc5pnX.png', NULL, NULL, '成田剣', NULL, 1358, 'SUPPORTING', 2762) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024278', 'AN2078', '弥勒', '仏教の「法師」、すなわち下級の行脚僧である弥勒は、生計を立てるために田舎を巡り、除霊や妖怪退治などの業を行っていた。 彼は、祖父の宮津（同じく仏教の僧侶）がかつて受けた先祖代々の呪いに苦しんでいる。その呪いは、美しい女性への弱みにつけ込み、女性の姿に変身した奈落によってかけられたもので、奈落は宮津のお札の一つを反射させ、宮津の右手の手のひらを貫いたのだ （英語版では左手のように見えるが）', 18, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1356-rLhVHJzPY0Mp.jpg', NULL, NULL, '保村真', NULL, 1356, 'SUPPORTING', 560) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024279', 'AN2078', '希林理', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215206-DDaVh2Hui82Q.png', NULL, NULL, '細谷佳正', NULL, 215206, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024280', 'AN2078', '刀々斎', '「犬の大将」（犬夜叉と殺生丸の父）の友人である年老いた鍛冶師で、鉄砕牙と天砕牙を鍛え上げた人物。傷ついた刀を修理したり、犬夜叉に鉄砕牙に秘められた力を教えたりする時以外は、めったに登場しない。 刀々斎は火を吐くことができ、巨大な鍛冶の槌を振るう。また、空を飛ぶ三つの目を持つ牛に乗っている。（「刀々斎」は「刀の浄化」を意味する。）', 200, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/1362.jpg', NULL, NULL, '龍田直樹', NULL, 1362, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024281', 'AN2078', '七宝', '「雷兄弟」である飛天と満天に父を殺された、孤児の若い妖怪・狐（キツネ）。父の仇を討つため、かごめと犬夜叉を助けた。 物語の中で、犬夜叉とかごめの旅にグループの一員として加わった最初のキャラクターである。七宝は変身できるが、その姿は一時的なものであり、しばしば不完全で役に立たない。また、特徴的な尾があることで、たいてい正体がバレてしまう。 彼のその他の注目すべき能力としては、空を飛ぶことのできる神馬に変身し、その軌跡として', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1357-q81pBzC7ynld.jpg', NULL, NULL, '渡辺久美子', NULL, 1357, 'SUPPORTING', 360) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024282', 'AN2078', '八衛門', '弥勒と親しくなった、気さくな変身妖怪。ハチの本来の姿はタヌキである。ハチは「八衛門」の愛称だ。かつては弥勒の姿に変身し、偽の御札を売りさばいたり、女性たちを口説いたりして楽しんでいた。 しかし、弥勒にその現場を目撃された時、彼は洞窟に取り憑いた霊に襲われていた。ハチは時折、犬夜叉の一行の移動手段として活躍し、必要とあれば敵地の奥深くへ彼らを連れて行ったり、危険な場所から脱出させたりするために、自らの命を賭けることもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1363-Y7kRvDaEWe1W.png', NULL, NULL, '茶風林 ', NULL, 1363, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024283', 'AN2078', '日暮 草太', 'ソータは日暮かごめの弟です。彼は姉のことをとても気遣う優しい子です。また、ソータは犬夜叉がかっこいいと思っています。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/25422.jpg', NULL, NULL, '榎木淳弥', NULL, 25422, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024284', 'AN2078', 'りん', '犬夜叉との戦いの傷を癒やしていた殺生丸を、森の中で発見した孤児の少女。山賊に家族を殺されるというトラウマで言葉を失い、小さな村からの不安定な施しを受けつつ、ほとんど自力で生きてきた。 殺生丸は彼女が世話をしようとする努力を冷たくあしらうが、彼女はそれでも彼に食べ物や水を持ち続け、村人たちに負わされた傷について彼が何気なく尋ねてきた時には、彼には理解できないほど大喜びする。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1365-C5r2sPW8PwA8.jpg', NULL, NULL, '能登麻美子', NULL, 1365, 'SUPPORTING', 251) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024285', 'AN2078', '楓', '桔梗の妹であり、巫女。姉の死後、50年にわたり村を守り続けてきた。かごめが姉の生まれ変わりであることを、誰よりも早く見抜いた人物である。 彼女はよく犬夜叉の一行に、妖怪やその他の霊的な異変に関する助言や知識を授けており、かごめ、珊瑚、七宝、弥勒、そして時には犬夜叉自身からも深く尊敬され、高く評価されている。 彼の気性からすれば当然のことだが、犬夜叉は彼女にすぐに苛立つものの、その話には耳を傾ける。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1360-nvgYPaUEMeG6.jpg', NULL, NULL, '京田尚子', NULL, 1360, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024286', 'AN2078', 'ママ', 'ママ・ヒグチは、ソータと日暮かごめの思いやりのある母親です。誰も彼女の名前について言及したことがなく、本名に関する情報は一切ありません。子供たちは彼女を「ママ」と呼んでいるため、彼女は「ママ・ヒグチ」として知られています。   ママ・ヒグラシに関する情報がほとんどない中、彼女の夫についてはさらに情報が乏しい。夫について明らかになっている唯一の情報は、彼が「五神木」の下で彼女にプロポーズしたということだけだ。ただし、漫画では彼が自動車事故で亡くなったと述べられている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b39399-mhywbOOMiUOJ.png', NULL, NULL, '百々麻子', NULL, 39399, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024287', 'AN2078', '冥加', '犬夜叉の情報源である妖怪のノミ。普段は危険な状況から逃げ出すのが常だ。当初は、鉄砕牙が納められた犬夜叉の父の遺骸／墓を守る役目を任されていた。 その墓は、犬夜叉の右目にある黒い真珠の中に隠されており、兄である殺生丸との最初の対決の際に開かれた。 冥加は妖怪の血を飲むことも好んでおり、ある時、犬夜叉の血から毒を吸い取って彼の命を救ったこともある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1361-qz5kWP3aFK9M.jpg', NULL, NULL, '緒方賢一', NULL, 1361, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
