INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024296', 'AN2079', 'ケイト・バーン', 'ジェフリーを補佐する女性副隊長。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255547-nGKLQfbEUXVR.png', NULL, NULL, '石上静香', NULL, 255547, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024297', 'AN2079', 'ダリア・リヴォフ', 'ユーラシア連邦の少尉であり、アレクセイの副官。幼い頃からアレクセイを知っており、彼を手のかかる弟のように思っている。大規模な軍隊を指揮する能力に長けている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314086-sosm57gsHxrK.png', NULL, NULL, '遠藤綾', NULL, 314086, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024298', 'AN2079', 'ホウ・グアン', '瀬戸内海の沿岸地域の治安を担当する指揮官。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255549-e53AEj1fbjjH.png', NULL, NULL, '水中雅章', NULL, 255549, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024299', 'AN2079', 'アレクセイ・ゼレノイ', '彼はユーラシア連邦の少佐である。その話し方は独特で、周囲の人々をしばしば居心地悪くさせてしまうが、AMAIMの操縦技術はユーラシア軍でもトップクラスである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314087-ejONFgXupgdn.png', NULL, NULL, '浪川大輔', NULL, 314087, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
