INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024301', 'AN2079', '熊井ゴウケン', 'ヤタガラスの第2特殊部隊（熊井軍団）を率いる隊長。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255551-TUhVJ2bfxsAm.png', NULL, NULL, 'てらそままさき', NULL, 255551, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
