INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024307', 'AN2080', '水沢愛佳', '出身地：栃木県日光市　ポジション：FW　利き手：右　彼女は明るく、前向きで、良い意味で楽観的だ。物事をじっくり考えるというよりは、直感や思いつきで行動する傾向がある。感情的な性格で、泣き虫でもある。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199729-pGLunrtEJGlX.jpg', '11月5日', NULL, '増田里紅', 157, 199729, 'MAIN', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024308', 'AN2080', '清瀬優', '出身地：北海道釧路市　ポジション：FW　利き手：左　彼女は完璧主義者で真面目な性格だが、実は繊細で傷つきやすい一面もある。 愛香の楽観的な性格には失望しつつも、内心では彼女を羨ましく思っている。アイスホッケー以外のことは一切気にせず、世間知らずだ。いざという時には神がかり的なプレーを見せ、チームメイトから厚い信頼を寄せられている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199730-jzLVyoGBebAy.jpg', '7月14日', NULL, '本郷里実', 158, 199730, 'MAIN', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024309', 'AN2080', '水沢彩佳', '出身地：栃木県日光市　利き手：右　マナカの妹。小柄で体力に自信がないことにコンプレックスを抱いている。姉のマナカやその友人たちに追いつこうと必死に努力する努力家だ。 また、危機的な状況でも果敢に行動できる能力を持っている。チームのマスコット的存在である。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199731-Y1baQ79C8n3L.jpg', '2月2日', NULL, '相良茉優', 151, 199731, 'MAIN', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024310', 'AN2080', '鷺沼梨子', '出身地：栃木県日光市　出身校：桐生里中学校　チームのエースであり、前向きで、姉のような気さくさがあり、情熱的な性格の持ち主だ。運動神経が非常に良く、子供の頃はボーイッシュだった。その性格にふさわしい、少年のような外見をしている。 負けず嫌いで、どんなことにも一生懸命取り組む。子供の頃、一度アイスホッケーをしたことがある。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199732-MtOo233p543j.jpg', '8月30日', NULL, '北守さいか', 154, 199732, 'MAIN', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024311', 'AN2080', '柳田薫子', '出身地：栃木県日光市　ポジション：GK　利き手：右　日光の名産であるイチゴ農家のひとり娘。チームにとって母のような存在だ。分別があり、忍耐強く、いつも笑顔を絶やさない。また、みんなのおやつの手配も担当している。 穏やかな性格だが、芯は強く、誰よりも仲間を大切にしている。温泉が大好きで、その情熱は誰にも負けない。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199734-WUwegDxpz1Is.jpg', '1月15日', NULL, '森山由梨佳', 160, 199734, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024312', 'AN2080', '小野真美', '出身地：栃木県日光市　ポジション：FW　利き手：右　真奈香の幼なじみであり、親友。いつも優しく、裏方で真奈香やその仲間たちを支えている。 物静かな性格で、スピード感のあるアイスホッケーはあまり得意ではないが……刺繍が大好きで、それが彼女の特技でもある。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199735-i5XWa9pz2dyw.jpg', '12月15日', NULL, '青山吉能', 156, 199735, 'MAIN', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024313', 'AN2080', '高木尚美', '出身地：栃木県日光市　ポジション：DF　利き手：右　彼女は頭脳明晰で、成績も優秀（IQも高い）。内気で人見知りなため、打ち解けるには時間がかかる。あまり話さないが、鋭いユーモアのセンスを持っている。 リコに惹かれてチームに加入した。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199733-d8Exret5vYtr.jpg', '4月14日', NULL, '汐入あすか', 161, 199733, 'MAIN', 19) ON CONFLICT DO NOTHING;
