INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024345', 'AN2081', '結城友奈', '中学2年生で、「ヒーロー部」の部員。ヒーローであることを誇りにしており、困っている人を助け、常に前向きな姿勢を貫いている。  彼女は装甲の手甲とすね当てを装備して、ヴァーテックスと戦う。妖精の使い魔「ギュキ」の力により、拳にエネルギーを凝縮させ、必殺技「ヒーローパンチ」を放つことができる。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88636-qlblbpue9jvK.jpg', '3月21日', 'O', '照井春佳', NULL, 88636, 'MAIN', 375) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024346', 'AN2081', '高嶋友奈', '学年：中学2年生　初代ヒーローチームのメンバーの一人。ユナは明るく元気な女の子で、「チームのムードメーカー」とも言える存在だ。彼女にとって、友達と家族は最も大切なものであり、他人の気持ちにも敏感である。 また、ユナは自己犠牲の精神に富んでおり、たとえ自分に不利益が及ぶとしても、友人のために戦いに身を投じる。しかし、自分の感情を隠してしまう癖がある。ユナがヒーロー形態になると、彼女の武器は「テッコ」となる。彼女のものは、一部', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126201-1f5V7s3fLQVS.jpg', '1月11日', 'A', '照井春佳', 154, 126201, 'MAIN', 82) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024347', 'AN2081', '犬吠埼風', '中学3年生で、「ヒーロー部」の部長であり、イツキの姉。些細なことは気にしないが、大局を見据え、姉として仲間たちを鼓舞する。妹や友人たちをとても大切に思っている。料理や家事が得意で、食べることも大好きだ。  ヒーローとして、フーは巨大な大剣を振るう。その刃の大きさゆえ、剣としてだけでなく盾としても頻繁に活用している。また、フェアリーであるイヌガミの力を借りて、', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88638-0I3nqQKI774u.png', '5月1日', 'A', '内山夕実', NULL, 88638, 'MAIN', 120) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024348', 'AN2081', '乃木若葉', '学年：中学2年生　中学2年生の少女であり、初代ヒーローチームのメンバーの一人、そしてソノコの先祖にあたる。若葉は、恩は恩で返すべきだと信じる、真面目で意志の強い少女だ。彼女はバーテックスへの復讐を誓っており、そのためにリスクを厭わない。 生まれながらのカリスマ性を持つリーダーであり、一般大衆からも絶大な人気を誇っている。しかし、その真面目な態度が時に人々を遠ざけてしまうことに心を痛める、心優しい少女でもあり、彼女は……', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126200-x3zUygRnG68A.jpg', '6月20日', 'A', '大橋彩香', 163, 126200, 'MAIN', 173) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024349', 'AN2081', '東郷美森', 'ユナの親友であり、同級生で同じクラブのメンバー。ユナの隣に住んでおり、よく名字で呼ばれることを好む。ミモリは自国の伝統を誇りに思っており、いつでも祖国を守り、国民を守る覚悟ができている。彼女は、交通事故が原因とされる事故により、両足の機能を失い、記憶の一部も失ってしまった。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88637-WXqWFtEUnSt6.jpg', '4月8日', 'AB', '三森すずこ', NULL, 88637, 'MAIN', 358) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024350', 'AN2081', '乃木園子', '乃木園子は、ライトノベル『鷲尾スミはヒーロー』の3人の主人公の一人である。物語の舞台となる時期、彼女は三ノ輪銀や鷲尾スミと共に、ヴェルテックスと戦うヒーローとしてタイシャに選ばれた小学6年生である。 彼女はとてものんびりした性格で、ぼんやりしてしまう癖がある。しかし、そのおっちょこちょいな性格の裏には、実に驚異的な知性が隠されており、ほんの数秒で計画を練り上げることができる。また、園子は小説家としても成功しており、専門は', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88641-ikpD1qwAjhmF.png', '8月30日', 'O', '花澤香菜', 156, 88641, 'MAIN', 282) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024351', 'AN2081', '犬吠埼樹', '中学1年生で、「ヒーロー部」の部員。フーの妹であり、姉を心から尊敬している。姉とは異なり、イツキはとても内気で臆病だ。しかし、心は優しく、人を助けることが好きだ。また、親しい人の前では内気さが和らぎ、時には皮肉な発言をすることもある。  ヒーローとして、イツキは白い花が縁取りされたタンバリンのようなリングを使い、そこから魔法のつるを放つ。このつるは敵を絡め取り、切り裂くことができる。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88639-mGNBV2FXxR8V.jpg', '12月7日', 'O', '黒沢ともよ', NULL, 88639, 'MAIN', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024352', 'AN2081', '三好夏凜', '中学2年生で、ヒーロー部の部員。ユナやミモリのクラスに転校してきたベテランのヒーローであり、他のヒーローたちを指導するためにヒーロー部に入部した。 カリンは、頑固で一途、そして一筋な性格の持ち主として描かれている。口調はきつい方で、他人に対して自分の気持ちを表現するのが苦手だ。しかし、誰かが困っていると、どうしても助けずにはいられない。かなり自信家であり前向きで、当初は自分が', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88640-Zpb2n4Kft1GD.jpg', '6月12日', 'B', '長妻樹里', NULL, 88640, 'MAIN', 177) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024353', 'AN2081', '郡千景', '学年：中学3年生　第1ヒーローチームのヒーローの一人。千影は、人付き合いが苦手な、内気で物静かで孤独な少女だ。多くの内向的な人と同じように、ビデオゲームを楽しむのが好きだ。 他人に対して不信感を抱き、無口に見えるものの、心の底では誰からも受け入れられたいと願う優しい性格の持ち主だ。特に高嶋友奈とは親しい関係にあるが、チームの他のメンバーのことも大切に思っている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126240-wKYYgKIEOgR2.png', '2月3日', 'A', '鈴木愛奈', 159, 126240, 'MAIN', 165) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024354', 'AN2081', '楠芽吹', '学年：中学2年生　楠目吹は、同名のシリーズ『楠目吹はヒーロー』に登場する主人公である。彼女は意志が強く勤勉で、勝利のためならどんな手段も厭わない。 また、彼女は非常に頑固で、ヒーローであることや、彼女の情熱である職人としての活動に関しても、その姿勢は変わりません。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136191-S4fUcahZXsta.jpg', '5月9日', 'B', '田中美海', 159, 136191, 'MAIN', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024355', 'AN2081', '山伏しずく', '学年：中学2年生　好きな食べ物：ラーメン　山伏しずくは、ライトノベル『楠目吹はヒーロー』の主要キャラクターである。彼女は物静かで、よく一人でいることが多い少女だ。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136193-mzaykdbCfiby.png', '2月4日', 'AB', '石上静香', 156, 136193, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024356', 'AN2081', '弥勒夕海子', '学年：中学3年生　好きな食べ物：カツオ　弥勒由美子は『楠目吹はヒーロー』の主要キャラクターの一人である。彼女は、目吹の「最大のライバル」を自称する、高慢な令嬢である。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136194-eWhrl0oqVLVT.png', '4月27日', 'O', '大空直美', 163, 136194, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024357', 'AN2081', '国土亜耶', '国土綾は、『楠目吹はヒーロー』シリーズの主要キャラクターの一人である。彼女はセンチネルたちの巫女である。綾は極めて心優しく、センチネルたち全員を平等に扱っている。彼女が話すときは、常に真剣そのものだ。センチネルたちを助けるためなら、どんなことでも厭わない。', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136192-R2NCDxDdId4G.png', '11月20日', 'A', '大野柚布子', 147, 136192, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024358', 'AN2081', '安芸', '298年チームの指導者兼メンター。安芸は生徒たちに対して厳格で厳しいが、嫌われることはない。一部の生徒を怖がらせて従わせる才能はある。その裏には、親切で、喜んで手助けをしてくれる一面がある。', 25, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130893-0O5IEgbzPt09.png', NULL, NULL, '佐藤利奈', NULL, 130893, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024359', 'AN2081', '三ノ輪銀', 'スミとソノコの同級生であり、ヒーロー仲間。ジンは3人の友人の中で最年少かつ最も背が低い一方で、体力は最も強く、スポーツ万能なタイプだ。ヒーロー形態では、一対の大きな刃を使う。  ギンは親切でエネルギッシュな女の子で、元気いっぱいで前向きな性格だ。おてんばな一面もあるが、女の子らしい一面も持っている。主な趣味はスポーツや様々な競技だ。自由時間、主に学校に行く前には、弟の世話をしている。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124148-xBYqo3EM6PB4.png', '11月10日', 'A', '花守ゆみり', NULL, 124148, 'SUPPORTING', 145) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024360', 'AN2081', '伊予島杏', '初代ヒーローチームのメンバーの一人で、5人組の中で最年少。アンズは、特に恋愛小説が大好きな本好きの虫。チームの中で最も体力に優れているわけではないが、非常に頭脳明晰で、チームのほとんどのメンバーよりも知識が豊富だ。 彼女はタマコと非常に仲が良く、タマコを先輩として慕い、親友だと思っている。アンズは時々戦うことを恐れることがあり、ヒーローとして戦わなければならない時にはそれが弱点となる。しかし、彼女は仲間を非常に大切にし、守るために戦うだろう。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126244-X6RnWOGJnWIz.jpg', '9月16日', 'A', '近藤玲奈', 156, 126244, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024361', 'AN2081', '上里ひなた', '学年：中学2年生　上里ひなたは、ライトノベル『野木若葉はヒーロー』の主人公の一人である。彼女はヒーローではないが、第1ヒーローチームの一員である。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126245-B3cm11ZSyXlN.jpg', '10月4日', 'AB', '高野麻里佳', 150, 126245, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024362', 'AN2081', '加賀城雀', 'カガジョ・スズメは、『楠目吹はヒーロー』シリーズの主要キャラクターの一人である。彼女は弱気で臆病な少女であり、センチネルの32番である。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136190-WOBD3WHe2HTW.png', '7月22日', 'A', '種﨑敦美', 152, 136190, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024363', 'AN2081', '土居球子', '初代ヒーローチームのメンバーの一人。タマコは、屋外が大好きで、元気いっぱいで感情豊かな少女だ。よく笑う一方で、怒りっぽいところもある。また、自分の名前を使った駄洒落を好んで使い、自分を三人称で呼ぶ癖がある。 彼女は友達を大切にし、友達が傷つくのを防ごうとします。ヒーローとして、タマコは「カムヤタテヒメ」という名の、6枚の刃を持つ伸縮式の盾を使って戦います。これはヨーヨーのように投げて使うこともでき、', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126241-9ertEn2nIwGf.jpg', '9月2日', 'B', '本渡楓', 147, 126241, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
