INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024377', 'AN2083', '根来牡丹', '幼い頃から祖父のジンゴに育てられ、秘密工作員となるべく訓練を受けてきた。悪行を見逃すことができない彼女は、しばしば無謀にも危険な状況に飛び込んでしまうが、普段は内向的な高校生を装い、本性を隠している。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217141-fTedmoFNZGDb.jpg', NULL, NULL, '小原好美', NULL, 217141, 'MAIN', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024378', 'AN2083', 'クルマ', '「日本安全推進」の自称ナンバーワンエージェント。軽薄で気取った態度をとることも多いが、その使命への献身ぶりは誰にも負けない。突然ボタンとペアを組まされたことをきっかけに、彼女に対して敵意を抱いている。', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217140-kB9F1ZISuOHg.jpg', NULL, NULL, '鈴木達央', NULL, 217140, 'MAIN', 9) ON CONFLICT DO NOTHING;
