INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024382', 'AN2083', '高松隆之介', 'データ収集と分析を専門とする精鋭エージェント。ボタンとクルマの援護にあたる。物事を整然と清潔に保つことを好む完璧主義者。', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217144-b15JoUOuCoIW.jpg', NULL, NULL, '前野智昭', NULL, 217144, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
