INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024394', 'AN2084', 'ルパン三世', 'ルパン三世は、アルセーヌ・ルパン一世の孫である。彼は世界一指名手配されている泥棒だ。冒険の過程で、彼はしばしば自らと仲間たちを率いて、より重大な犯罪に手を染める他の犯罪者たちを阻止する。時折、無能に見えることもあるが、それは主に敵の油断を誘うための芝居である。 これまで何度も逮捕され、刑務所に投獄されてきたが、そのたびに脱獄に成功している。峰不二子への想いは、おそらく彼の最大の弱点であり、それが原因でしばしば望ましくない状況に陥ってしまう。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/1044-UriNGSc2CKPO.jpg', NULL, NULL, '栗田貫一', NULL, 1044, 'MAIN', 1621) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024395', 'AN2084', '石川五ェ門', 'The thirteenth generation of renegade samurai, beginning with the legendary figure Ishikawa Goemon (石川 五右衛門). He has a sword called Zantetsuken (斬鉄剣), meaning "iron-cutting sword", which can cut through almost anything. In one episode during the TV series Goemon admitted that his sword cannot cut konnyaku, which is a starch-based jelly made from yams, because the blade just gets stuck in it. The Zantetsuken is usually used to cut inanimate objects, which Goemon considers unworthy of his blade an', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1046-kFemmr8KkgFb.png', NULL, NULL, '浪川大輔', NULL, 1046, 'MAIN', 573) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024396', 'AN2084', '銭形幸一', '銭形は、ルパンを逮捕することを人生の使命としている。ルパンの一味の他のメンバーを逮捕するのももちろん望んでいるが、銭形が本当に狙っているのは、その首謀者であるルパン本人なのだ。 ルパンと銭形は、一見すると不倶戴天の敵のように見えるが、ある意味では友人でもある。ルパンはそれを公然と示している（しばしば、銭形に冗談めかした親しみを込めて挨拶するなどして）が、銭形はそれを認めることに極めて消極的だ。 同様に、彼はルパンの天才ぶりにしばしば感服しているが、それを表に出そうとはしない。アニメ版では', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1048-GDlCKww1le0Q.jpg', NULL, NULL, '山寺宏一', NULL, 1048, 'MAIN', 398) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024397', 'AN2084', '次元大介', 'ルパンの狙撃手。0.3秒という素早い抜き撃ちと、驚異的な精度の射撃をこなす。帽子で目を隠すことを好んでおり、それによってより謎めいた雰囲気を醸し出している。 その帽子は、照準や標的の捕捉に利用されるため、彼の抜群の射撃精度にとって重要な要素でもある。また、機関銃やスナイパーライフル、さらにはPTRS対戦車ライフルに至るまで、多種多様な銃器の扱いに長けている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/1045-5VLjexUmCT6p.jpg', NULL, NULL, '大塚明夫', NULL, 1045, 'MAIN', 1049) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024398', 'AN2084', 'リリー', 'ホームズに所属する若い女性。彼女は以前、ルパンと出会ったことがある。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247307-y8Xm3ApE6lxZ.png', NULL, NULL, '諸星すみれ', NULL, 247307, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
