INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024420', 'AN2085', 'ガンマモン', 'ごく稀な、幼体の白いケラトプス類のデジモンで、最近発見されたばかりである。ガンマモンの進化は、「銀河系外の宇宙から届いたデジタル信号」と関連していると言われている。 額から生えた2本の硬い角は、攻撃にも防御にも役立つ武器である。また、背中の小さな翼を使って、浮遊したり、短時間であれば飛行することも可能だ。感情をほとんど表に出さないが、一度親しくなれば、徐々にあなたに愛着を抱くようになるようだ。その必殺技は', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b247597-WEDZqclwa2GX.png', NULL, NULL, '沢城みゆき', NULL, 247597, 'MAIN', 58) ON CONFLICT DO NOTHING;
