INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024427', 'AN2085', 'アルケニモン', 'アルケニモンは『デジモンアドベンチャー02』の主要な敵役の一人で、女性の頭部と胴体、クモの腹部と脚を持つ、クモの遊女妖怪「ジョロウグモ」の姿をしたデジモンである。 ドクグモンの女王であり、その短気な性格ゆえに、ほとんどのデジモンから恐れられていた。     彼女の特殊能力は、美しい女性の姿に変身して犠牲者に近づき、油断を誘うことである。人間の姿では、髪の一本一本を「スピリットニードル」の呪文として使い、コントロール・スパ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b7591-pfnsQc7WdDdB.png', NULL, NULL, '山崎和佳奈', NULL, 7591, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
