INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024430', 'AN2085', 'リリスモン', 'リリスモンは、『デジモンクロスウォーズ』に登場するバグラ軍の三大将の一人である。唯一の女性将軍として知られるリリスモンは、ブラストモンやタクティモンといった他の高位の将軍たちと肩を並べている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b70377-pi5vnYujti2c.png', NULL, NULL, '園崎未恵', NULL, 70377, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
