INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024436', 'AN2085', 'マミーモン', 'マミーモンは『デジモンアドベンチャー02』の主要な敵キャラクターの一人で、松葉杖の形をしたライフルを携えたミイラの姿をしたデジモンである。本来は気難しい性格だが、非常に危険な存在でもある。 『デジモンアドベンチャー02』において、マミーモンは灰色の肌をした、青いコートを着た片目のヒューマノイドに変身する能力を持っている。彼はアルケニモンとパートナーを組んでおり、彼女に深く恋をしている。    情報元：Wikimon。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b21691-zUAaLCuaaTjk.jpg', NULL, NULL, '菅生隆之', NULL, 21691, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024437', 'AN2085', 'ゴートモン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b260931-TnJsn7qCNfuA.jpg', NULL, NULL, NULL, NULL, 260931, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024438', 'AN2085', 'ヴァンデモン', 'ヴァンデモンは、「ヴァンパイア」と「デーモン」に由来する名を持つアンデッドデジモンであり、その英語名「マイオティスマン」は、オオモセコウモリに由来している。 アンデッドデジモンの王として、黒魔術によって蘇生し、強大な力を手に入れた。もともとは吸収したコンピュータデータを破壊する凶悪なコンピュータウイルスだったが、破壊されたデータを悪質なコンピュータウイルスとして復活させる能力を持っていた。極めて残酷で狡猾な性格の持ち主であり、その凶暴さは並外れており……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b9955-Avn9chPkDG9B.png', NULL, NULL, '森川智之', NULL, 9955, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
