INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024441', 'AN2085', 'ホークモン', 'ホークモンは『デジモンアドベンチャー02』に主要なデジモンの1体として登場します。 ホークモンはミヤコとペアを組んでいる。ホークモンは「愛のデジエッグ」を使ってホルセモンへ、「純潔のデジエッグ」を使ってシュリモンへとアーマーデジヴォルブすることができる。また、ホークモンは通常通りデジヴォルブしてアクイラモンになることもできる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b24801-hS7QuI0v9Rvg.png', NULL, NULL, '長江里加', NULL, 24801, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
