INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024460', 'AN2085', 'ポテモン', 'ポテモンは「フードデジモン」の一種です。あらゆる種類のフライドポテトのデータを吸収したグルメなデジモンです。フライドポテトを食べながら歩き回り、その美味しさを多くのデジモンに知ってもらいたいと願い、自分のおすすめのフライドポテトを配りながら回っています。 自分のフライドポテトを批判する者を「文句ばかり言う人」と見なしている。自分に謝罪した者には、そのフライドポテトの素晴らしさを味わわせてあげる。ファストフードの腕前を巡って、バーガーモンとライバル関係にある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212866-vzsEmdESZ1QL.png', NULL, NULL, '川口莉奈', NULL, 212866, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
