INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024472', 'AN2085', 'ダークナイトモン', 'ダークナイトモンは、神話に登場するダークナイトに由来する名前とデザインを持つダークナイトデジモンである。これは、スカルナイトモンとデッドリーアクスモンが「兄弟の絆」を交わし、融合した姿である。 兄の知略と弟の機動性を兼ね備えたダークナイトモンは、一流の戦士へと成長した。 状況に応じて、手にした「ツイン・スピア」を突き、斬り、払い、あるいは投げるなど、状況に応じて自在に使いこなすダークナイトモンの技量は極めて高度であり、それは', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/66935.jpg', NULL, NULL, '三宅健太', NULL, 66935, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024473', 'AN2085', 'エマ・ヘインズ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302731-yDu7hzRoTX62.jpg', NULL, NULL, '井上麻里奈', NULL, 302731, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024474', 'AN2085', 'クオンタモン', 'クオンタモンはピクシーデジモンです。このメガデジモンは、広大なネットオーシャンの上空に浮かぶ空中都市「ラーク」に祀られており、巨大な雲塊に覆われてその姿は見えません。 ラークの広範な能力のおかげで、クオンタモンはネットオーシャンから膨大な量のデータを吸収し、数十億、数兆もの未来の可能性をシミュレーションすることができる。そして、いつかデジタルワールドを襲うかもしれない災害を防ぐため、最善の対策を講じるべく、その配下たちと共に活動している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b302739-rPqZ8vmjXrNV.png', NULL, NULL, '早見沙織', NULL, 302739, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
