INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024479', 'AN2085', 'ボコモン', 'ボコモンは「学者デジモン」の一種です。その姿を正確に表現するのは難しいですが、体は白く、頭に角があり、耳が尖っているため、なんとなくインコに似ています。  声優：杉山和子（日本語）、ブライアン・ビーコック（英語）、ウヴェ・ビュシュケン（ドイツ語）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b26540-jph7x6j1hp1h.png', NULL, NULL, '沼田祐介', NULL, 26540, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
