INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024483', 'AN2085', 'ピエモン', 'ピエモンは闇の荒野を支配し、レディ・デヴィモンや数多くのヴィレモンからなる悪魔の軍団「ナイトメア・ソルジャーズ」を率いている。 ピエモンはダークマスターズの中で最も強靭であり、最も残酷でもある。また、サディスティックなユーモアのセンスを持ち、しばしば冗談を飛ばしてヒステリックに笑う。彼は欺瞞と策略の達人である。それにもかかわらず、彼は仲間を尊重し、対等な存在として接している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b9957-t0Cvn5wVgdqy.png', NULL, NULL, '山路和弘', NULL, 9957, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024484', 'AN2085', 'アシュラモン', 'アシュラモンはウィザードデジモンである。4本の腕と3つの顔を持つ伝説のデジモンだ。古代ヒンドゥー文化の文献を分析していたコンピューターの中に、突如として現れた。アシュラモンの3つの顔のうち、1つは怒りの顔、1つは慈悲の顔、そしてもう1つは祝福の顔である。 その異様な外見とは裏腹に、正義を重んじるため、不正を見れば決して妥協することなく徹底的に攻撃すると言われており、その性格はまさに', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b302732-q9gHXY7AkqDb.png', NULL, NULL, '玄田哲章', NULL, 302732, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
