INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024557', 'AN2089', 'みゃむ', 'みゃむは、魔法の世界からやってきた魔法使いです。彼女のお気に入りのブランドは「LOVELY MELODY」です。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234289-Jua1zEyEozg6.png', '8月8日', 'B', '小池理子', 150, 234289, 'MAIN', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024558', 'AN2089', '皇あまね', '彼女は中学3年生で、後輩たちから尊敬されている。お気に入りのブランドは「エターナル・レビュー」だ。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248019-8AbK2xni8Ljy.png', '6月2日', 'AB', '庄司宇芽香', 167, 248019, 'MAIN', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024559', 'AN2089', '陽比野まつり', 'マツリは、『プリマギ』とお祭りが大好きな中学1年生。熱くなると、その力が爆発する。お気に入りのブランドは「LOVELY MELODY」だ。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234290-EupzVaRgxlnW.png', '8月8日', 'B', '廣瀬千夏', 160, 234290, 'MAIN', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024560', 'AN2089', '御芽河あうる', NULL, 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248017-m9htUWxRo34i.jpg', '4月28日', 'O', '藤寺美徳', 152, 248017, 'MAIN', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024561', 'AN2089', '弥生ひな', '彼女は、プリマギの名門校であるアラワシ中学校の3年生だ。お気に入りのブランドはVIVID STAR。  情熱的で率直な性格で、後輩たちから慕われている。前回のプリマギ・グランドフェスティバルで、ライバルと見なしているジェニファーに敗れたため、非常に努力家で、自己研鑽に熱心に取り組んでいる。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242050-xdBfuAEgOGKt.png', '3月27日', 'O', '内田彩', 165, 242050, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024562', 'AN2089', '甘瓜みるき', 'ミルキは、一見すると可愛らしい中学2年生だ。彼女の夢は「ミルキ・キュート・ミュージアム」を建てること。お気に入りのブランドは「チェリーシュガー」だ。表面的には甘く無邪気に見えるが、その実、自分の可愛さを巧みに利用する人物である。 また、ミルキは傲慢で自己中心的な一面も持ち合わせており、それは彼女の内なる独白や鏡の前での独り言からも明らかだ。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248018-imKpxMozmk8y.png', '9月10日', 'A', '相良茉優', 153, 248018, 'MAIN', 59) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH024563', 'AN2089', '心愛れもん', 'レモンは中学2年生です。彼女は「プリマギ」オタクで、その知識は非常に豊富です。お気に入りのブランドは「ラディアント・アビス」です。彼女は極度の内気な性格で、すぐに緊張してしまう傾向があります。 誰かが彼女に近づきすぎると、口からソル／エクトプラズムが漏れ出してしまうが、それが見えるのは魔法使いだけだ。内気な性格のせいで、彼女の言葉は他人には無礼に聞こえてしまうことがある。しかし、ゲームの話になると、彼女ははるかに社交的で気さくになり、', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242051-4bfZcUlLUvlL.png', '11月28日', 'A', '鈴木杏奈', 158, 242051, 'MAIN', 41) ON CONFLICT DO NOTHING;
